import React, { useState, useEffect, useRef } from 'react';
import { HERO_IMAGE } from '../constants';
import { Upload } from 'lucide-react';

export const CoverImage: React.FC = () => {
  const [imageSrc, setImageSrc] = useState(HERO_IMAGE);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Carregar imagem salva ao iniciar
  useEffect(() => {
    const savedImage = localStorage.getItem('vilage_dashboard_cover');
    if (savedImage) {
      setImageSrc(savedImage);
    }
  }, []);

  const handleImageError = () => {
    // Fallback se a imagem der erro
    setImageSrc("https://picsum.photos/seed/hotel/1920/400");
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setImageSrc(base64String);
        // Salvar no LocalStorage para persistência (limite de ~5MB)
        try {
            localStorage.setItem('vilage_dashboard_cover', base64String);
        } catch (e) {
            console.error("Imagem muito grande para salvar localmente", e);
            alert("A imagem selecionada é muito grande para salvar no navegador. Ela será exibida apenas nesta sessão.");
        }
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="group relative w-full h-[30vh] min-h-[200px] max-h-[360px] overflow-hidden mt-11 bg-notion-card select-none">
      <img 
        src={imageSrc} 
        alt="Cover" 
        className="w-full h-full object-cover object-center transition-opacity duration-500"
        onError={handleImageError}
      />

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*" 
        className="hidden" 
      />

      {/* Notion-style hover controls for cover */}
      <div className="absolute top-1/2 right-4 md:right-24 transform -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2 text-xs text-notion-text">
         <button 
            onClick={handleUploadClick}
            className="bg-notion-bg/60 hover:bg-notion-bg/90 px-3 py-1.5 rounded backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10 shadow-sm"
         >
            <Upload size={12} />
            Alterar capa
         </button>
      </div>
    </div>
  );
};

