import React, { useEffect } from 'react';
import { DashboardCard } from '../types';
import { X, Maximize2, MoreHorizontal } from 'lucide-react';

interface PageModalProps {
  card: DashboardCard;
  onClose: () => void;
}

export const PageModal: React.FC<PageModalProps> = ({ card, onClose }) => {
  const Icon = card.icon;

  // Fechar com ESC
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 sm:p-8 animate-in fade-in duration-200">
      {/* Modal Content */}
      <div className="bg-[#202020] w-full max-w-4xl h-full max-h-[85vh] rounded-xl shadow-2xl flex flex-col overflow-hidden border border-white/10 relative animate-in zoom-in-95 duration-200">

        {/* Modal Header Actions */}
        <div className="flex items-center justify-between p-3 absolute top-0 left-0 right-0 z-10">
            <button onClick={onClose} className="p-1 hover:bg-white/10 rounded text-notion-muted hover:text-notion-text transition-colors">
                <Maximize2 size={16} />
            </button>
            <div className="flex items-center gap-1">
                <button className="p-1 hover:bg-white/10 rounded text-notion-muted hover:text-notion-text transition-colors">
                    <MoreHorizontal size={16} />
                </button>
                <button onClick={onClose} className="p-1 hover:bg-white/10 rounded text-notion-muted hover:text-notion-text transition-colors">
                    <X size={20} />
                </button>
            </div>
        </div>

        {/* Cover Image in Modal */}
        <div className="h-48 w-full shrink-0 relative">
             <img src={card.image} className="w-full h-full object-cover opacity-80" alt={card.title} />
        </div>

        {/* Scrollable Body */}
        <div className="flex-1 overflow-y-auto p-8 sm:px-16 custom-scrollbar">
            {/* Icon */}
            <div className="-mt-14 mb-4 relative z-10">
                <div className="text-4xl text-notion-text drop-shadow-md bg-[#202020] w-fit p-1 rounded">
                    <Icon size={48} />
                </div>
            </div>

            {/* Title */}
            <h1 className="text-4xl font-bold text-notion-text mb-8">{card.title}</h1>

            {/* Dynamic Content */}
            <div className="text-notion-text leading-relaxed pb-20">
                {card.content || <p className="text-notion-muted italic">Sem conteúdo disponível.</p>}
            </div>
        </div>
      </div>

      {/* Click outside to close */}
      <div className="absolute inset-0 -z-10" onClick={onClose}></div>
    </div>
  );
};

