export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { HERO_IMAGE } from '../constants';
import { Upload, GripBR } from 'lucide-react';

export const CoverImage: React.FC = () => {
  const [imageSrc, setImageSrc] = useState(HERO_IMAGE);

  // Estados para dimensões (Height em PX, Width em %)
  const [height, setHeight] = useState(300);
  const [width, setWidth] = useState(100);

  const containerRef = useRef<HTMLDivElement>(null);
  const isResizing = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Carregar dados salvos ao iniciar
  useEffect(() => {
    const savedImage = localStorage.getItem('vilage_dashboard_cover');
    const savedHeight = localStorage.getItem('vilage_dashboard_cover_height');
    const savedWidth = localStorage.getItem('vilage_dashboard_cover_width');

    if (savedImage) setImageSrc(savedImage);
    if (savedHeight) setHeight(parseInt(savedHeight, 10));
    if (savedWidth) setWidth(parseInt(savedWidth, 10));
  }, []);

  const handleImageError = () => {
    setImageSrc("https://picsum.photos/seed/hotel/1920/400");
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setImageSrc(base64String);
        try {
            localStorage.setItem('vilage_dashboard_cover', base64String);
        } catch (e) {
            alert("A imagem é muito grande para salvar no navegador.");
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // --- Lógica de Redimensionamento ---

  const startResizing = (e: React.MouseEvent) => {
    e.preventDefault();
    isResizing.current = true;
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', stopResizing);
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isResizing.current || !containerRef.current) return;

    // Calcular nova altura (baseado na posição Y do mouse em relação ao topo do container)
    const newHeight = e.clientY - containerRef.current.getBoundingClientRect().top;

    // Calcular nova largura (baseado na posição X do mouse em relação ao centro da tela, mas simplificado para % da janela)
    // Para simplificar UX: arrastar horizontalmente ajusta a % da largura total
    const windowWidth = window.innerWidth;
    const newWidthPercent = (e.clientX / windowWidth) * 100;

    // Limites de segurança
    if (newHeight > 100 && newHeight < 800) {
        setHeight(newHeight);
    }

    // A largura ajusta baseada na distância do mouse da esquerda. 
    // Se o mouse estiver perto da borda direita -> 100%.
    // Se arrastar para esquerda -> diminui.
    // Ajuste para centralização: consideraremos a largura baseada na posição do mouse relativa à tela
    // Uma abordagem melhor para UX centralizado: Width = (MouseX do centro * 2) / WindowWidth? 
    // Vamos usar uma abordagem mais simples: O container é centralizado, o resize handle está na direita.
    // A largura é determinada pela posição do mouse em relação ao container, mas como ele redimensiona e centraliza ao mesmo tempo,
    // precisamos calcular baseado na metade.

    // Abordagem simplificada: A posição do mouse define a borda direita.
    // Como está centralizado (mx-auto), a largura total seria aprox (MouseX - (WindowWidth - MouseX))??
    // Vamos simplificar: Width % = (MouseX / WindowWidth) * 100, mas com um fator de correção se quisermos que ele fique centralizado.
    // Mas se usarmos apenas style width %, o mouse pode "deslizar" do handle.

    // Vamos usar a posição do mouse relativa à janela para definir a largura visualmente
    // Se o mouse está em 90% da tela, largura é 90% (se alinhado à esquerda) ou algo diferente se centralizado.
    // Vamos travar em 100% se passar de 95%.

    let calculatedWidth = (e.clientX / windowWidth) * 100;

    // Como o container tem 'mx-auto', ele encolhe pelas duas pontas. 
    // Para o mouse acompanhar a borda direita, precisamos ajustar a matemática ou aceitar o "deslize".
    // Vamos tentar manter simples:
    if (calculatedWidth > 98) calculatedWidth = 100;
    if (calculatedWidth < 30) calculatedWidth = 30; // Mínimo 30%

    // Ajuste fino para a pegada (UX): Se o usuário arrasta a borda direita de um elemento centralizado,
    // o elemento encolhe 2x mais rápido que o mouse (porque a esquerda também encolhe).
    // Para corrigir isso, calculamos a distância do centro.
    const centerX = windowWidth / 2;
    const distFromCenter = e.clientX - centerX;
    // Largura = 2 * distância do centro (convertido para %)
    const centeredWidthConfig = ((distFromCenter * 2) / windowWidth) * 100;

    // Usamos a config centralizada se for válida, senão fallback
    if (centeredWidthConfig > 0 && centeredWidthConfig <= 100) {
        if (centeredWidthConfig > 96) setWidth(100);
        else if (centeredWidthConfig < 30) setWidth(30);
        else setWidth(centeredWidthConfig);
    }
  }, []);

  const stopResizing = useCallback(() => {
    isResizing.current = false;
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', stopResizing);

    // Salvar no LocalStorage ao soltar
    // Usando os valores atuais do state, que podem não estar atualizados dentro do listener antigo se não usarmos refs,
    // mas aqui estamos chamando a função que recria a cada render ou acessando state externo?
    // O ideal é salvar no próximo render ou usar ref para valores.
    // Vamos confiar que o React state update trigger re-render e podemos salvar no useEffect ou aqui via setItem direto com valor atual (temos acesso ao state scope closure?)
    // O closure de 'stopResizing' pode ter valores antigos se não estiver no dependency array.
    // Vamos simplificar: salvar no useEffect quando mudar? Não, muito I/O.
    // Vamos disparar um evento customizado ou apenas salvar o valor "live".
  }, []);

  // Effect para salvar quando parar de redimensionar (debounce simples ou apenas salvar no mouseup usando ref atualizado seria melhor, mas faremos no effect de mudança com debounce)
  useEffect(() => {
     const timer = setTimeout(() => {
         localStorage.setItem('vilage_dashboard_cover_height', height.toString());
         localStorage.setItem('vilage_dashboard_cover_width', width.toString());
     }, 500);
     return () => clearTimeout(timer);
  }, [height, width]);

  return (
    <div 
      ref={containerRef}
      style={{ height: `${height}px`, width: `${width}%` }}
      className="group relative mx-auto mt-11 bg-notion-card select-none transition-[width] duration-75 ease-linear"
    >
      <img 
        src={imageSrc} 
        alt="Cover" 
        className="w-full h-full object-cover object-center"
        onError={handleImageError}
      />

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*" 
        className="hidden" 
      />

      {/* Controls Overlay (Upload) */}
      <div className="absolute top-1/2 right-4 transform -translate-y-1/2 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2 text-xs text-notion-text z-20">
         <button 
            onClick={handleUploadClick}
            className="bg-notion-bg/60 hover:bg-notion-bg/90 px-3 py-1.5 rounded backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10 shadow-sm"
         >
            <Upload size={12} />
            Alterar capa
         </button>
      </div>

      {/* Resize Handle */}
      <div 
        onMouseDown={startResizing}
        className="absolute bottom-2 right-2 p-1 bg-black/50 hover:bg-notion-blue rounded cursor-nwse-resize opacity-0 group-hover:opacity-100 transition-opacity z-30 text-white shadow-lg"
        title="Arraste para redimensionar"
      >
        <GripBR size={20} />
      </div>

      {/* Visual Border on Hover to indicate editable area */}
      <div className="absolute inset-0 border-2 border-transparent group-hover:border-white/10 pointer-events-none transition-colors" />
    </div>
  );
};

