import React, { useState, useEffect, useRef, useCallback } from 'react';
import { HERO_IMAGE } from '../constants';
import { Upload, MoveVertical } from 'lucide-react';

export const CoverImage: React.FC = () => {
  const [imageSrc, setImageSrc] = useState(HERO_IMAGE);
  const [positionY, setPositionY] = useState(50); // 0 a 100%
  const [isRepositioning, setIsRepositioning] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const dragStartRef = useRef<number>(0);
  const startPosRef = useRef<number>(50);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Carregar dados salvos ao iniciar
  useEffect(() => {
    const savedImage = localStorage.getItem('vilage_dashboard_cover');
    const savedPos = localStorage.getItem('vilage_dashboard_cover_pos');

    if (savedImage) setImageSrc(savedImage);
    if (savedPos) setPositionY(parseFloat(savedPos));
  }, []);

  const handleImageError = () => {
    setImageSrc("https://picsum.photos/seed/hotel/1920/400");
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        setImageSrc(base64String);
        setPositionY(50); // Resetar posição ao trocar imagem
        try {
            localStorage.setItem('vilage_dashboard_cover', base64String);
            localStorage.setItem('vilage_dashboard_cover_pos', '50');
        } catch (e) {
            alert("A imagem é muito grande para salvar no navegador.");
        }
      };
      reader.readAsDataURL(file);
    }
  };

  // --- Lógica de Reposicionamento (Drag Image) ---

  const toggleRepositionMode = () => {
    if (isRepositioning) {
        // Salvando ao sair do modo
        localStorage.setItem('vilage_dashboard_cover_pos', positionY.toString());
        setIsRepositioning(false);
    } else {
        setIsRepositioning(true);
    }
  };

  const cancelReposition = () => {
      // Reverter para o salvo
      const savedPos = localStorage.getItem('vilage_dashboard_cover_pos');
      if (savedPos) setPositionY(parseFloat(savedPos));
      setIsRepositioning(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isRepositioning) return;
    e.preventDefault();
    setIsDragging(true);
    dragStartRef.current = e.clientY;
    startPosRef.current = positionY;

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!containerRef.current) return;

    // Sensibilidade do movimento
    const sensitivity = 0.2; 
    const deltaY = (e.clientY - dragStartRef.current) * sensitivity;

    // Novo percentual
    let newPos = startPosRef.current - deltaY;

    // Limites (0% é topo, 100% é base)
    if (newPos < 0) newPos = 0;
    if (newPos > 100) newPos = 100;

    setPositionY(newPos);
  }, []);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
  }, [handleMouseMove]);


  return (
    <div className="group relative w-full h-[30vh] min-h-[200px] max-h-[300px] mt-11 bg-notion-card select-none overflow-hidden">

      {/* A Imagem */}
      <img 
        ref={containerRef as any}
        src={imageSrc} 
        alt="Cover" 
        onMouseDown={handleMouseDown}
        style={{ objectPosition: `center ${positionY}%` }}
        className={`w-full h-full object-cover transition-none ${isRepositioning ? 'cursor-move' : ''}`}
        onError={handleImageError}
      />

      {/* Hidden File Input */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        accept="image/*" 
        className="hidden" 
      />

      {/* Overlay Escuro ao Reposicionar (Instrução visual) */}
      {isRepositioning && (
          <div className="absolute inset-0 bg-black/20 pointer-events-none flex items-center justify-center text-white/80 font-medium text-sm">
             Arraste para reposicionar
          </div>
      )}

      {/* Controls Overlay */}
      {/* Mostra apenas se NÃO estiver reposicionando */}
      {!isRepositioning && (
        <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2 text-xs text-notion-text z-20">
            <button 
                onClick={handleUploadClick}
                className="bg-black/50 hover:bg-black/70 px-3 py-1.5 rounded backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10 shadow-sm"
            >
                <Upload size={12} />
                Alterar capa
            </button>
            <button 
                onClick={toggleRepositionMode}
                className="bg-black/50 hover:bg-black/70 px-3 py-1.5 rounded backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10 shadow-sm"
            >
                <MoveVertical size={12} />
                Reposicionar
            </button>
        </div>
      )}

      {/* Controles DE Reposicionamento (Salvar/Cancelar) */}
      {isRepositioning && (
          <div className="absolute bottom-4 right-4 flex gap-2 text-xs text-notion-text z-30 animate-in fade-in slide-in-from-bottom-2">
            <button 
                onClick={toggleRepositionMode} // Salvar
                className="bg-notion-blue hover:bg-notion-blueHover text-white px-4 py-1.5 rounded shadow-sm font-medium"
            >
                Salvar posição
            </button>
            <button 
                onClick={cancelReposition}
                className="bg-black/50 hover:bg-black/70 px-3 py-1.5 rounded backdrop-blur-sm transition-colors border border-white/10 shadow-sm"
            >
                Cancelar
            </button>
          </div>
      )}
    </div>
  );
};

import React from 'react';
import { Share, MoreHorizontal, Menu, ChevronLeft, Home } from 'lucide-react';

interface NavbarProps {
  breadcrumbs?: { label: string; onClick?: () => void }[];
  onBack?: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({ breadcrumbs, onBack }) => {
  return (
    <nav className="h-11 w-full bg-notion-bg flex items-center justify-between px-3 fixed top-0 left-0 z-50 border-b border-white/5 transition-colors">

      {/* Left: Navigation / Breadcrumbs */}
      <div className="flex items-center gap-1 text-sm text-notion-text overflow-hidden">

        {/* Mobile Back Button (only if onBack provided) */}
        {onBack && (
            <button 
                onClick={onBack}
                className="p-1 mr-1 hover:bg-notion-hover rounded md:hidden text-notion-muted hover:text-notion-text"
            >
                <ChevronLeft size={20} />
            </button>
        )}

        <button className="p-1 hover:bg-notion-hover rounded md:hidden text-notion-muted">
            <Menu size={18} />
        </button>

        {/* Breadcrumb List */}
        {!breadcrumbs ? (
            // Default Home State
            <div className="flex items-center gap-2 hover:bg-notion-hover px-2 py-1 rounded cursor-pointer transition-colors whitespace-nowrap">
                <span className="text-lg">🏨</span>
                <span className="font-medium truncate">Hotel Vilage Inn Poços de Caldas</span>
            </div>
        ) : (
            // Dynamic Breadcrumbs
            <div className="flex items-center gap-1 whitespace-nowrap overflow-hidden">
                {breadcrumbs.map((item, index) => (
                    <React.Fragment key={index}>
                        {index > 0 && <span className="text-notion-muted">/</span>}
                        <button 
                            onClick={item.onClick}
                            className={`flex items-center gap-2 px-1.5 py-1 rounded transition-colors truncate
                                ${item.onClick ? 'hover:bg-notion-hover cursor-pointer text-notion-text' : 'text-notion-text cursor-default'}
                            `}
                        >
                            {index === 0 && <span className="text-lg mr-1">🏨</span>}
                            <span className={index === breadcrumbs.length - 1 ? "font-medium" : "font-normal text-notion-text"}>
                                {item.label}
                            </span>
                        </button>
                    </React.Fragment>
                ))}
            </div>
