// Script atualizado com lógica de Upload e Folder específico
const GOOGLE_SCRIPT_CODE = `// CONFIGURAÇÃO
var DRIVE_FOLDER_ID = "1w-DofVpEHKA46fEr6Gij38AcQJijl6iC";

function doGet() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheets = ss.getSheets();
  var output = [];

  sheets.forEach(function(sheet) {
    var sheetName = sheet.getName();
    if (sheetName.startsWith("_")) return;

    var title = sheet.getRange("B1").getValue();
    var image = sheet.getRange("B2").getValue();
    var icon = sheet.getRange("B3").getValue();

    if (!title) title = sheetName;

    var lastRow = sheet.getLastRow();
    var contentHtml = "";

    if (lastRow >= 5) {
      var range = sheet.getRange(5, 1, lastRow - 4, 2);
      var values = range.getValues();
      values.forEach(function(row) {
        var text = row[0] || row[1];
        if (text) contentHtml += "<p style='margin-bottom: 1rem;'>" + text + "</p>";
      });
    }

    output.push({
      id: sheet.getSheetId().toString(), 
      title: title,
      image: image || "https://picsum.photos/800/400",
      icon: icon || "FileText",
      content: contentHtml
    });
  });

  return ContentService.createTextOutput(JSON.stringify(output))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheets = ss.getSheets();
    var targetSheet = null;

    // Localizar a aba pelo ID
    for (var i = 0; i < sheets.length; i++) {
      if (sheets[i].getSheetId().toString() === data.id) {
        targetSheet = sheets[i];
        break;
      }
    }

    if (!targetSheet) {
       return ContentService.createTextOutput(JSON.stringify({status: "error", message: "Sheet not found"}))
        .setMimeType(ContentService.MimeType.JSON);
    }

    // 1. Atualizar Imagem (Upload)
    if (data.imageBase64) {
      var folder = DriveApp.getFolderById(DRIVE_FOLDER_ID);
      var contentType = data.mimeType || "image/jpeg";
      var blob = Utilities.newBlob(Utilities.base64Decode(data.imageBase64.split(",")[1]), contentType, "cover_" + data.id + "_" + new Date().getTime());
      var file = folder.createFile(blob);
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

      // Gerar link direto (thumbnail hack ou download link)
      // O link padrão de visualização do Drive as vezes não renderiza em <img> tags diretamente sem tratamento
      // Usaremos o link de thumbnail grande
      var fileUrl = "https://lh3.googleusercontent.com/d/" + file.getId();

      targetSheet.getRange("B2").setValue(fileUrl);
      data.image = fileUrl; // Retornar a nova URL
    }

    // 2. Atualizar Título
    if (data.title) {
      targetSheet.getRange("B1").setValue(data.title);
      // Opcional: Renomear a aba também?
      // targetSheet.setName(data.title.substring(0, 50)); 
    }

    // 3. Atualizar Ícone
    if (data.icon) {
      targetSheet.getRange("B3").setValue(data.icon);
    }

    return ContentService.createTextOutput(JSON.stringify({status: "success", data: data}))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({status: "error", message: err.toString()}))
      .setMimeType(ContentService.MimeType.JSON);
  }
}`

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS } from './constants';
// Import icons mapping
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCard, setActiveCard] = useState<DashboardCard | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Carregar dados salvos no localStorage (cache offline) ao iniciar
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsedCards = JSON.parse(cachedData);
            const rehydratedCards = parsedCards.map((card: any) => ({
                ...card,
                icon: (LucideIcons as any)[card.iconName] || LucideIcons.HelpCircle
            }));
            setCards(rehydratedCards);
        } catch (e) {
            console.error("Erro ao carregar cache", e);
        }
    }
  }, []);

  const handleBackToHome = () => {
    setActiveCard(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Função GET (Sincronizar tudo)
  const handleSync = async (url: string) => {
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Network response was not ok');

        const data = await response.json();

        const newCards: DashboardCard[] = data.map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id || Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content 
            };
        });

        setCards(newCards);

        const cacheableData = newCards.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || 'Info'
        }));
        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cacheableData));

    } catch (error) {
        console.error("Sync failed:", error);
        throw error;
    }
  };

  // Função POST (Atualizar um cartão específico: Titulo, Icone ou Upload Imagem)
  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string }) => {
    if (!activeCard) return;

    // 1. Otimisticamente atualiza a UI localmente
    const updatedCardFull = { ...activeCard, ...updatedFields };
    setActiveCard(updatedCardFull);

    const newCardsList = cards.map(c => c.id === activeCard.id ? updatedCardFull : c);
    setCards(newCardsList);

    // Salvar cache local
    const cacheableData = newCardsList.map((c: any) => ({
        ...c,
        icon: undefined,
        iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info')
    }));
    localStorage.setItem('vilage_dashboard_data', JSON.stringify(cacheableData));

    // 2. Enviar para o Google Apps Script via POST
    const apiUrl = localStorage.getItem('vilage_dashboard_api_url');
    if (!apiUrl) {
        console.warn("API URL not set. Changes saved locally only.");
        return;
    }

    try {
        const payload = {
            id: activeCard.id,
            title: updatedFields.title,
            icon: typeof updatedFields.icon === 'string' ? updatedFields.icon : updatedFields.iconName,
            imageBase64: updatedFields.imageBase64, // Se houver upload
            mimeType: updatedFields.mimeType
        };

        // fetch com POST no-cors ou cors dependendo da config do script, 
        // mas apps script web app geralmente requer redirect follow.
        // O metodo mais seguro para POST em Apps Script é usar text/plain para evitar preflight options complexo,
        // e parsear no script.
        await fetch(apiUrl, {
            method: 'POST',
            body: JSON.stringify(payload)
        });

        // Em um cenário ideal, recarregariamos os dados da resposta para confirmar a URL da imagem do Drive
        // mas vamos manter otimista por enquanto.

    } catch (e) {
        console.error("Failed to update remote sheet", e);
        alert("Erro ao salvar na planilha. Verifique sua conexão ou a URL da API.");
    }
  };

  const breadcrumbs = activeCard ? [
    { label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome },
    { label: activeCard.title } 
  ] : undefined;

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                card={activeCard} 
                onUpdateCard={handleUpdateCard} 
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage />
                <PageContent 
                    cards={cards}
                    onCardClick={(card) => {
                        setActiveCard(card);
                        window.scrollTo({ top: 0, behavior: 'auto' });
                    }} 
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

