    if (savedUrl) setUrl(savedUrl);
  }, []);

  const handleSaveAndSync = async () => {
    if (!url) return;

    setIsLoading(true);
    setStatus('idle');

    try {
      localStorage.setItem('vilage_dashboard_api_url', url);
      await onSync(url);
      setStatus('success');
      setTimeout(() => {
        onClose();
        setStatus('idle');
      }, 1000);
