import React, { useState, useRef } from 'react';
import { DashboardCard } from '../types';
import { LayoutTemplate, Loader2 } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { IconPicker } from './IconPicker';

interface ActivePageProps {
  card: DashboardCard;
  onUpdateCard: (fields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string }) => void;
}

export const ActivePage: React.FC<ActivePageProps> = ({ card, onUpdateCard }) => {
  const [currentIconName, setCurrentIconName] = useState<string>(
    typeof card.icon === 'string' ? card.icon : ((card as any).iconName || 'HelpCircle')
  );
  const [isUploading, setIsUploading] = useState(false);
  const [showIconPicker, setShowIconPicker] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Resolver o componente de ícone dinamicamente
  const Icon = (LucideIcons as any)[currentIconName] || LucideIcons.HelpCircle;

  // --- Handlers ---

  const handleTitleChange = (e: React.FocusEvent<HTMLInputElement>) => {
    if (e.target.value !== card.title) {
        onUpdateCard({ title: e.target.value });
    }
  };

  const handleIconSelect = (newIconName: string) => {
    setCurrentIconName(newIconName);
    onUpdateCard({ icon: newIconName, iconName: newIconName } as any);
    setShowIconPicker(false);
  };

  const handleChangeCoverClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 4 * 1024 * 1024) { // 4MB limit check (safe margin for GAS 5MB limit)
          alert("A imagem deve ser menor que 4MB para envio seguro.");
          return;
      }

      setIsUploading(true);
      const reader = new FileReader();

      reader.onloadend = () => {
        const base64String = reader.result as string;

        // Atualiza UI imediatamente e dispara upload
        onUpdateCard({ 
            image: base64String, // Mostra localmente
            imageBase64: base64String, // Envia para o servidor salvar no Drive
            mimeType: file.type 
        });

        // Timeout para simular processamento e não piscar muito rápido
        setTimeout(() => setIsUploading(false), 2000);
      };

      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="w-full min-h-screen bg-notion-bg text-notion-text pb-32 animate-in fade-in duration-300">

      {showIconPicker && (
          <IconPicker 
            onSelect={handleIconSelect} 
            onClose={() => setShowIconPicker(false)} 
          />
      )}

      {/* Cover Image */}
      <div className="h-[30vh] min-h-[200px] w-full group relative bg-notion-card select-none">
        <img 
          src={card.image} 
          alt={card.title} 
          className={`w-full h-full object-cover object-center transition-opacity ${isUploading ? 'opacity-50' : 'opacity-100'}`}
        />

        {/* Loading Overlay */}
        {isUploading && (
            <div className="absolute inset-0 flex items-center justify-center">
                <div className="bg-black/60 px-4 py-2 rounded-full flex items-center gap-2 text-white text-sm backdrop-blur-sm shadow-lg border border-white/10">
                    <Loader2 className="animate-spin text-notion-blue" size={16} />
                    <span>Salvando no Drive...</span>
                </div>
            </div>
        )}

        <div className="absolute inset-0 bg-black/10 group-hover:bg-black/0 transition-colors pointer-events-none" />

        <button 
            onClick={handleChangeCoverClick}
            disabled={isUploading}
            className="absolute bottom-4 right-4 bg-black/50 hover:bg-black/70 text-xs px-2 py-1 rounded backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 disabled:opacity-0 cursor-pointer text-white"
        >
            Alterar capa
        </button>
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
        />
      </div>

      {/* Content Container */}
      <div className="max-w-[900px] mx-auto px-4 md:px-24 relative">

        {/* Icon (Editable) */}
        <div className="-mt-10 mb-2 relative z-10 group w-fit">
          <div 
            onClick={() => setShowIconPicker(true)}
            className="w-[78px] h-[78px] flex items-center justify-center rounded bg-notion-card shadow-sm hover:bg-notion-hover cursor-pointer transition-colors text-notion-text relative"
            title="Clique para alterar o ícone"
          >
            {React.createElement(Icon, { size: 40 })}
            <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded opacity-0 group-hover:opacity-100 transition-opacity text-xs font-medium text-white pointer-events-none">
                Editar
            </div>
          </div>
        </div>

        {/* Top Controls */}
        <div className="flex items-center gap-2 mb-4 text-notion-muted text-sm group">
            <button className="flex items-center gap-1 hover:text-notion-text hover:bg-notion-hover px-1.5 py-0.5 rounded transition-colors">
                <LayoutTemplate size={14} />
                <span>Layout do bloco</span>
            </button>
        </div>

        {/* Title (Editable Input styled as H1) */}
        <div className="mb-6 group relative">
            <input 
                type="text"
                defaultValue={card.title}
                onBlur={handleTitleChange}
                className="w-full text-4xl font-bold text-notion-text bg-transparent border-none outline-none placeholder:text-notion-muted/20 focus:ring-0 p-0 m-0"
