import React, { useState, useRef, useEffect } from 'react';
import { DashboardCard } from '../types';
import { LayoutTemplate, Loader2, MoreHorizontal } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { IconPicker } from './IconPicker';
import { RichTextEditor } from './RichTextEditor';

interface ActivePageProps {
  card: DashboardCard;
  onUpdateCard: (fields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string }) => void;
}

export const ActivePage: React.FC<ActivePageProps> = ({ card, onUpdateCard }) => {
  const [currentIconName, setCurrentIconName] = useState<string>(
    typeof card.icon === 'string' ? card.icon : ((card as any).iconName || 'HelpCircle')
  );
  const [isUploading, setIsUploading] = useState(false);
  const [showIconPicker, setShowIconPicker] = useState(false);
  const [showPageOptions, setShowPageOptions] = useState(false);

  // Local state for layout preferences
  const [fullWidth, setFullWidth] = useState(card.fullWidth || false);
  const [smallText, setSmallText] = useState(card.smallText || false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const optionsMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setFullWidth(card.fullWidth || false);
    setSmallText(card.smallText || false);
  }, [card.id, card.fullWidth, card.smallText]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (optionsMenuRef.current && !optionsMenuRef.current.contains(event.target as Node)) {
        setShowPageOptions(false);
      }
    };
    if (showPageOptions) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showPageOptions]);

  const Icon = (LucideIcons as any)[currentIconName] || LucideIcons.HelpCircle;

  // --- Handlers ---

  const handleTitleChange = (e: React.FocusEvent<HTMLInputElement>) => {
    if (e.target.value !== card.title) {
        onUpdateCard({ title: e.target.value });
    }
  };

  const handleIconSelect = (newIconName: string) => {
    setCurrentIconName(newIconName);
    onUpdateCard({ icon: newIconName, iconName: newIconName } as any);
    setShowIconPicker(false);
  };

  const handleChangeCoverClick = () => {
    fileInputRef.current?.click();
  };

  const handleToggleFullWidth = () => {
    const newValue = !fullWidth;
    setFullWidth(newValue);
    onUpdateCard({ fullWidth: newValue });
  };

  const handleToggleSmallText = () => {
    const newValue = !smallText;
    setSmallText(newValue);
    onUpdateCard({ smallText: newValue });
  };

  const handleContentUpdate = (newHtml: string) => {
    if (newHtml !== card.content) {
        onUpdateCard({ content: newHtml });
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 4 * 1024 * 1024) { 
          alert("A imagem deve ser menor que 4MB para envio seguro.");
          return;
      }

      setIsUploading(true);
      const reader = new FileReader();

      reader.onloadend = () => {
        const base64String = reader.result as string;
        onUpdateCard({ 
            image: base64String,
            imageBase64: base64String,
            mimeType: file.type 
        });
        setTimeout(() => setIsUploading(false), 2000);
      };

      reader.readAsDataURL(file);
    }
  };

  return (
    <div className={`w-full min-h-screen bg-notion-bg text-notion-text pb-32 animate-in fade-in duration-300 ${smallText ? 'text-sm' : 'text-base'}`}>

      {showIconPicker && (
          <IconPicker 
            onSelect={handleIconSelect} 
            onClose={() => setShowIconPicker(false)} 
          />
      )}

      {/* Cover Image */}
      <div className="h-[30vh] min-h-[200px] w-full group relative bg-notion-card select-none">
        <img 
          src={card.image} 
          alt={card.title} 
          className={`w-full h-full object-cover object-center transition-opacity ${isUploading ? 'opacity-50' : 'opacity-100'}`}
        />

        {isUploading && (
            <div className="absolute inset-0 flex items-center justify-center">
                <div className="bg-black/60 px-4 py-2 rounded-full flex items-center gap-2 text-white text-sm backdrop-blur-sm shadow-lg border border-white/10">
                    <Loader2 className="animate-spin text-notion-blue" size={16} />
                    <span>Salvando no Drive...</span>
                </div>
            </div>
        )}

        <div className="absolute inset-0 bg-black/10 group-hover:bg-black/0 transition-colors pointer-events-none" />

        <button 
            onClick={handleChangeCoverClick}
            disabled={isUploading}
            className="absolute bottom-4 right-4 bg-black/50 hover:bg-black/70 text-xs px-2 py-1 rounded backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 disabled:opacity-0 cursor-pointer text-white"
        >
            Alterar capa
        </button>
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
        />
      </div>

      {/* Main Layout Container */}
      <div className={`mx-auto px-4 relative transition-all duration-300 ${fullWidth ? 'max-w-full px-8 md:px-12' : 'max-w-[900px] md:px-24'}`}>

        {/* Page Options Menu */}
        <div className="absolute top-4 right-4 z-50" ref={optionsMenuRef}>
            <button 
                onClick={() => setShowPageOptions(!showPageOptions)}
                className="p-1 text-notion-muted hover:bg-notion-hover hover:text-notion-text rounded transition-colors"
                title="Opções da página"
            >
                <MoreHorizontal size={20} />
            </button>

            {showPageOptions && (
                <div className="absolute right-0 top-8 w-60 bg-[#252525] border border-white/10 rounded-lg shadow-xl p-2 flex flex-col gap-1 animate-in fade-in slide-in-from-top-2">
                    <div className="px-2 py-1.5 text-xs font-bold text-notion-muted uppercase tracking-wider">
                        Estilo da página
                    </div>
                    <div className="flex items-center justify-between px-2 py-1.5 hover:bg-white/5 rounded transition-colors select-none">
                        <div className="flex items-center gap-2 text-sm text-notion-text">
                            <span className="text-xs border border-white/20 px-1 rounded">A</span>
                            <span>Small text</span>
                        </div>
                        <div 
                            onClick={handleToggleSmallText}
                            className={`w-9 h-5 rounded-full p-0.5 cursor-pointer transition-colors ${smallText ? 'bg-notion-blue' : 'bg-notion-muted/40'}`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${smallText ? 'translate-x-4' : 'translate-x-0'}`} />
                        </div>
                    </div>
                    <div className="flex items-center justify-between px-2 py-1.5 hover:bg-white/5 rounded transition-colors select-none">
                        <div className="flex items-center gap-2 text-sm text-notion-text">
                            <LayoutTemplate size={14} />
                            <span>Full width</span>
                        </div>
                        <div 
                            onClick={handleToggleFullWidth}
                            className={`w-9 h-5 rounded-full p-0.5 cursor-pointer transition-colors ${fullWidth ? 'bg-notion-blue' : 'bg-notion-muted/40'}`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${fullWidth ? 'translate-x-4' : 'translate-x-0'}`} />
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* Icon */}
        <div className="-mt-10 mb-2 relative z-10 group w-fit">
          <div 
            onClick={() => setShowIconPicker(true)}
            className="w-[78px] h-[78px] flex items-center justify-center rounded bg-notion-card shadow-sm hover:bg-notion-hover cursor-pointer transition-colors text-notion-text relative"
            title="Clique para alterar o ícone"
          >
            {React.createElement(Icon, { size: 40 })}
            <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded opacity-0 group-hover:opacity-100 transition-opacity text-xs font-medium text-white pointer-events-none">
                Editar
            </div>
          </div>
        </div>

        {/* Title */}
        <div className="mb-6 group relative">
            <input 
                type="text"
                defaultValue={card.title}
                onBlur={handleTitleChange}
                className="w-full text-4xl font-bold text-notion-text bg-transparent border-none outline-none placeholder:text-notion-muted/20 focus:ring-0 p-0 m-0"
                placeholder="Sem título"
            />
        </div>

        <div className="h-px bg-white/10 w-full mb-6" />

        <div className="mb-8">
            <div className="flex items-center gap-2 text-notion-muted text-sm mb-2">
                <span className="font-medium">Comentários</span>
            </div>
            <div className="flex items-center gap-3 group cursor-text">
                <div className="w-6 h-6 rounded-full bg-blue-500 flex items-center justify-center text-[10px] text-white font-bold">
                    VI
                </div>
                <div className="text-notion-muted hover:text-notion-text text-sm flex-1">
                    Adicionar um comentário...
                </div>
            </div>
        </div>

        <div className="h-px bg-white/10 w-full mb-8" />

        {/* --- Rich Text Editor Integration --- */}
        <RichTextEditor 
            initialContent={typeof card.content === 'string' ? card.content : ''}
            onUpdate={handleContentUpdate}
        />

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS } from './constants';
// Import icons mapping
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCard, setActiveCard] = useState<DashboardCard | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Carregar dados salvos no localStorage (cache offline) ao iniciar
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsedCards = JSON.parse(cachedData);
            const rehydratedCards = parsedCards.map((card: any) => ({
                ...card,
                icon: (LucideIcons as any)[card.iconName] || LucideIcons.HelpCircle
            }));
            setCards(rehydratedCards);
        } catch (e) {
            console.error("Erro ao carregar cache", e);
        }
    }
  }, []);

  const handleBackToHome = () => {
    setActiveCard(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Função GET (Sincronizar tudo)
  const handleSync = async (url: string) => {
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Network response was not ok');

        const data = await response.json();

        const newCards: DashboardCard[] = data.map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id || Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '' // Garante string para o editor
            };
        });

        setCards(newCards);

        const cacheableData = newCards.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || 'Info'
        }));
        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cacheableData));

    } catch (error) {
        console.error("Sync failed:", error);
        throw error;
    }
  };

  // Função POST (Atualizar um cartão específico)
  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string }) => {
    if (!activeCard) return;

    // 1. Otimisticamente atualiza a UI localmente
    const updatedCardFull = { 
        ...activeCard, 
        ...updatedFields,
        // Garante que se iconName veio, o componente Icon é atualizado
        icon: updatedFields.iconName ? (LucideIcons as any)[updatedFields.iconName] : (updatedFields.icon || activeCard.icon)
    };

    setActiveCard(updatedCardFull);

    const newCardsList = cards.map(c => c.id === activeCard.id ? updatedCardFull : c);
    setCards(newCardsList);

    // Salvar cache local
    const cacheableData = newCardsList.map((c: any) => ({
        ...c,
        icon: undefined,
        iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info')
    }));
    localStorage.setItem('vilage_dashboard_data', JSON.stringify(cacheableData));

    // 2. Enviar para o Google Apps Script via POST
    const apiUrl = localStorage.getItem('vilage_dashboard_api_url');
    if (!apiUrl) {
        // Apenas aviso de console, salvamento local funciona
        return;
    }

    try {
        const payload = {
            id: activeCard.id,
            title: updatedFields.title,
            // Preferência para iconName (string), fallback para o que já existia
            icon: updatedFields.iconName || (activeCard as any).iconName || 'HelpCircle',
            content: updatedFields.content, // Envia o HTML do editor
            imageBase64: updatedFields.imageBase64, 
            mimeType: updatedFields.mimeType
        };

        await fetch(apiUrl, {
            method: 'POST',
            mode: 'no-cors',
            headers: {
                'Content-Type': 'text/plain',
            },
            body: JSON.stringify(payload)
        });

    } catch (e) {
        console.error("Failed to update remote sheet", e);
    }
  };

  const breadcrumbs = activeCard ? [
    { label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome },
    { label: activeCard.title } 
  ] : undefined;

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                card={activeCard} 
                onUpdateCard={handleUpdateCard} 
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage />
                <PageContent 
                    cards={cards}
                    onCardClick={(card) => {
                        setActiveCard(card);
                        window.scrollTo({ top: 0, behavior: 'auto' });
                    }} 
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

