                <X size={20} />
            </button>
        </div>

        {/* Scrollable Body */}
        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar">

            {/* URL Input Section */}
            <div className="bg-[#252525] p-4 rounded border border-white/5">
                <label className="block text-xs font-bold text-notion-muted uppercase mb-2">
                    1. URL do Web App
                </label>
                <div className="flex gap-2">
                    <input 
                        type="text" 
                        value={url}
                        onChange={(e) => setUrl(e.target.value)}
                        placeholder="https://script.google.com/macros/s/..."
                        className="flex-1 bg-[#191919] border border-white/10 rounded px-3 py-2 text-notion-text text-sm focus:outline-none focus:border-notion-blue transition-colors"
                    />
                </div>
                {status === 'error' && <p className="text-red-400 text-xs mt-2">Erro ao conectar. Verifique o link.</p>}
