};

// Script atualizado para lidar com Base64, Criação de Abas e Armazenamento de HTML
const GOOGLE_SCRIPT_CODE = `// ID DA PASTA DO DRIVE
var DRIVE_FOLDER_ID = "1w-DofVpEHKA46fEr6Gij38AcQJijl6iC";

function doGet() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheets = ss.getSheets();
  var output = [];

  sheets.forEach(function(sheet) {
    var sheetName = sheet.getName();
    if (sheetName.startsWith("_")) return;

    // Leitura das células fixas
    var title = sheet.getRange("B1").getValue();
    var image = sheet.getRange("B2").getValue();
    var icon = sheet.getRange("B3").getValue();
    var content = sheet.getRange("B4").getValue(); // HTML Rich Text
    var fullWidth = sheet.getRange("B5").getValue();
    var smallText = sheet.getRange("B6").getValue();

    if (!title) title = sheetName;

    // Fallback: se B4 estiver vazio, tentar ler linhas (legado)
    if (!content) {
      var lastRow = sheet.getLastRow();
      if (lastRow >= 8) {
        var range = sheet.getRange(8, 1, lastRow - 7, 2);
        var values = range.getValues();
        values.forEach(function(row) {
          var text = row[0] || row[1];
          if (text) content += "<p>" + text + "</p>";
        });
      }
    }

    output.push({
      id: sheet.getSheetId().toString(), 
      title: title,
      image: image || "https://picsum.photos/800/400",
      icon: icon || "FileText",
      content: content,
      fullWidth: fullWidth === true || fullWidth === "TRUE",
      smallText: smallText === true || smallText === "TRUE"
    });
  });

  return ContentService.createTextOutput(JSON.stringify(output))
    .setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(10000); 

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheets = ss.getSheets();
    var targetSheet = null;

    // 1. Tentar encontrar por ID
    if (data.id) {
      for (var i = 0; i < sheets.length; i++) {
        if (sheets[i].getSheetId().toString() === data.id) {
          targetSheet = sheets[i];
          break;
        }
      }
    }

    // 2. Se não achou por ID, tentar por Título
    if (!targetSheet && data.title) {
       targetSheet = ss.getSheetByName(data.title);
    }

    // 3. Se não achou, criar nova aba
    if (!targetSheet) {
       var safeTitle = (data.title || "New Page").substring(0, 50); // Limite nome
       try {
         targetSheet = ss.insertSheet(safeTitle);
       } catch(e) {
         targetSheet = ss.insertSheet(safeTitle + " " + Math.floor(Math.random()*1000));
       }
       // Configurar Headers
       targetSheet.getRange("A1:A6").setValues([["Title"], ["Image"], ["Icon"], ["ContentHTML"], ["FullWidth"], ["SmallText"]]);
       targetSheet.getRange("A1:A6").setFontWeight("bold");
    }

    // --- SALVAR DADOS ---

    // Título
    if (data.title) targetSheet.getRange("B1").setValue(data.title);

    // Ícone
    if (data.icon) targetSheet.getRange("B3").setValue(data.icon);

    // Conteúdo (HTML)
    if (data.content !== undefined) targetSheet.getRange("B4").setValue(data.content);

    // Layout
    if (data.fullWidth !== undefined) targetSheet.getRange("B5").setValue(data.fullWidth);
    if (data.smallText !== undefined) targetSheet.getRange("B6").setValue(data.smallText);

    // Upload Imagem (Drive)
    if (data.imageBase64) {
      var folder;
      try {
        folder = DriveApp.getFolderById(DRIVE_FOLDER_ID);
      } catch (e) {
        folder = DriveApp.getRootFolder();
      }

      var contentType = data.mimeType || "image/jpeg";
      var encodedImage = data.imageBase64;
      if (encodedImage.indexOf("base64,") !== -1) {
        encodedImage = encodedImage.split("base64,")[1];
      }

      var blob = Utilities.newBlob(Utilities.base64Decode(encodedImage), contentType, "cover_" + targetSheet.getSheetId());
      var file = folder.createFile(blob);
      file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

      // Link direto
      var fileUrl = "https://lh3.googleusercontent.com/d/" + file.getId();

      targetSheet.getRange("B2").setValue(fileUrl);
      data.image = fileUrl; // Retorna a URL nova para o frontend
    }

    // Retorna ID atualizado caso tenha mudado (ex: create sheet)
    data.id = targetSheet.getSheetId().toString();

    return createJSONOutput({status: "success", data: data});

  } catch (err) {
    return createJSONOutput({status: "error", message: err.toString()});
  } finally {
    lock.releaseLock();
  }
}

function createJSONOutput(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}`;

