import React, { useState, useEffect, useRef, useCallback } from 'react';
import { HERO_IMAGE } from '../constants';
import { Upload, MoveVertical, Loader2 } from 'lucide-react';

interface CoverImageProps {
    imageSrc?: string;
    positionY?: number;
    onUpdate?: (data: { imageBase64?: string, mimeType?: string, position?: number }) => void;
}

export const CoverImage: React.FC<CoverImageProps> = ({ 
    imageSrc = HERO_IMAGE, 
    positionY = 50, 
    onUpdate 
}) => {
  const [isRepositioning, setIsRepositioning] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [localPos, setLocalPos] = useState(positionY);
  const [isUploading, setIsUploading] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const dragStartRef = useRef<number>(0);
  const startPosRef = useRef<number>(50);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync prop changes
  useEffect(() => {
    setLocalPos(positionY);
  }, [positionY]);

  const handleImageError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    e.currentTarget.src = "https://picsum.photos/seed/hotel/1920/400";
  };

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file && onUpdate) {
      if (file.size > 5 * 1024 * 1024) { 
          alert("A imagem deve ser menor que 5MB.");
          return;
      }

      setIsUploading(true);
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        onUpdate({ 
            imageBase64: base64String,
            mimeType: file.type
        });
        // Reset loading state after a delay or let parent control
        setTimeout(() => setIsUploading(false), 4000);
      };
      reader.readAsDataURL(file);
    }
  };

  // --- Lógica de Reposicionamento ---

  const toggleRepositionMode = () => {
    if (isRepositioning) {
        // Save
        if(onUpdate) onUpdate({ position: localPos });
        setIsRepositioning(false);
    } else {
        setIsRepositioning(true);
    }
  };

  const cancelReposition = () => {
      setLocalPos(positionY);
      setIsRepositioning(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!isRepositioning) return;
    e.preventDefault();
    setIsDragging(true);
    dragStartRef.current = e.clientY;
    startPosRef.current = localPos;

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!containerRef.current) return;
    const sensitivity = 0.2; 
    const deltaY = (e.clientY - dragStartRef.current) * sensitivity;
    let newPos = startPosRef.current - deltaY;
    if (newPos < 0) newPos = 0;
    if (newPos > 100) newPos = 100;
    setLocalPos(newPos);
  }, []);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
  }, [handleMouseMove]);


  return (
    <div className="group relative w-full h-[30vh] min-h-[200px] max-h-[300px] mt-11 bg-notion-card select-none overflow-hidden">

      {/* Imagem */}
      <img 
        ref={containerRef as any}
        src={imageSrc} 
        alt="Cover" 
        onMouseDown={handleMouseDown}
        style={{ objectPosition: `center ${localPos}%` }}
        className={`w-full h-full object-cover transition-none ${isRepositioning ? 'cursor-move' : ''} ${isUploading ? 'opacity-50' : 'opacity-100'}`}
        onError={handleImageError}
      />

      {isUploading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-40">
            <div className="flex items-center gap-2 text-white bg-black/60 px-4 py-2 rounded-full border border-white/10">
                <Loader2 className="animate-spin" size={16} />
                <span>Enviando para o Drive...</span>
            </div>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={handleFileChange} accept="image/*" className="hidden" />

      {isRepositioning && (
          <div className="absolute inset-0 bg-black/20 pointer-events-none flex items-center justify-center text-white/80 font-medium text-sm">
             Arraste para reposicionar
          </div>
      )}

      {!isRepositioning && !isUploading && (
        <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2 text-xs text-notion-text z-20">
            <button 
                onClick={handleUploadClick}
                className="bg-black/50 hover:bg-black/70 px-3 py-1.5 rounded backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10 shadow-sm"
            >
                <Upload size={12} />
                Alterar capa
            </button>
            <button 
                onClick={toggleRepositionMode}
                className="bg-black/50 hover:bg-black/70 px-3 py-1.5 rounded backdrop-blur-sm transition-colors flex items-center gap-2 border border-white/10 shadow-sm"
            >
                <MoveVertical size={12} />
                Reposicionar
            </button>
        </div>
      )}

      {isRepositioning && (
          <div className="absolute bottom-4 right-4 flex gap-2 text-xs text-notion-text z-30 animate-in fade-in slide-in-from-bottom-2">
            <button onClick={toggleRepositionMode} className="bg-notion-blue hover:bg-notion-blueHover text-white px-4 py-1.5 rounded shadow-sm font-medium">
                Salvar posição
            </button>
            <button onClick={cancelReposition} className="bg-black/50 hover:bg-black/70 px-3 py-1.5 rounded backdrop-blur-sm transition-colors border border-white/10 shadow-sm">
                Cancelar
            </button>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCard, setActiveCard] = useState<DashboardCard | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle
                }));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                if (parsed.metadata.home_cover_image) setHomeCover(parsed.metadata.home_cover_image);
                if (parsed.metadata.home_cover_pos) setHomeCoverPos(Number(parsed.metadata.home_cover_pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }
  }, []);

  const handleBackToHome = () => {
    setActiveCard(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleSync = async (url: string) => {
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();

        // Parse Cards
        const newCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id || Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText
            };
        });

        // Parse Metadata
        if (result.metadata) {
            if (result.metadata.home_cover_image) setHomeCover(result.metadata.home_cover_image);
            if (result.metadata.home_cover_pos) setHomeCoverPos(Number(result.metadata.home_cover_pos));
        }

        setCards(newCards);
        saveToLocalCache(newCards, result.metadata);

    } catch (error) {
        console.error("Sync failed:", error);
        throw error;
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    // 1. Optimistic Update
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    const apiUrl = localStorage.getItem('vilage_dashboard_api_url');
    if (!apiUrl) return;

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(apiUrl, {
            method: 'POST',
            body: JSON.stringify(payload)
        });
        const result = await response.json();

        if (result.status === 'success' && result.data.image) {
            setHomeCover(result.data.image); // Replace base64 with Drive URL
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string }) => {
    if (!activeCard) return;

    let updatedCardFull = { 
        ...activeCard, 
        ...updatedFields,
        icon: updatedFields.iconName ? (LucideIcons as any)[updatedFields.iconName] : (updatedFields.icon || activeCard.icon)
    };

    setActiveCard(updatedCardFull);
    const newCardsList = cards.map(c => c.id === activeCard.id ? updatedCardFull : c);
    setCards(newCardsList);

    const apiUrl = localStorage.getItem('vilage_dashboard_api_url');
    if (!apiUrl) {
        saveToLocalCache(newCardsList);
        return;
    }

    try {
        const payload = {
            id: activeCard.id,
            title: updatedFields.title,
            icon: updatedFields.iconName || (activeCard as any).iconName || 'HelpCircle',
            content: updatedFields.content, 
            imageBase64: updatedFields.imageBase64, 
            mimeType: updatedFields.mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText
        };

        const response = await fetch(apiUrl, { method: 'POST', body: JSON.stringify(payload) });
        const result = await response.json();

        if (result.status === 'success' && result.data) {
            if (result.data.image && result.data.image.startsWith('http')) {
                updatedCardFull = { ...updatedCardFull, image: result.data.image };
                setActiveCard(updatedCardFull);
                newCardsList = cards.map(c => c.id === activeCard.id ? updatedCardFull : c);
                setCards(newCardsList);
            }
            saveToLocalCache(newCardsList);
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
        saveToLocalCache(newCardsList);
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = activeCard ? [
    { label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome },
    { label: activeCard.title } 
  ] : undefined;

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                card={activeCard} 
                onUpdateCard={handleUpdateCard} 
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards}
                    onCardClick={(card) => {
                        setActiveCard(card);
                        window.scrollTo({ top: 0, behavior: 'auto' });
                    }} 
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

