import React, { useRef, useEffect, useState } from 'react';
import { 
  Bold, Italic, List, Heading1, Heading2, 
  Highlighter, Smile, Image as ImageIcon, Minus
} from 'lucide-react';

interface RichTextEditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  readOnly?: boolean;
}

export const RichTextEditor: React.FC<RichTextEditorProps> = ({ initialContent, onUpdate, readOnly = false }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showHighlightMenu, setShowHighlightMenu] = useState(false);
  const [showEmojiMenu, setShowEmojiMenu] = useState(false);

  // Inicializa o conteúdo apenas uma vez
  useEffect(() => {
    if (editorRef.current && initialContent) {
        if (editorRef.current.innerHTML !== initialContent) {
            editorRef.current.innerHTML = initialContent;
        }
    }
  }, []);

  const handleInput = () => {
    // Apenas atualiza estado interno se necessário
  };

  const handleBlur = () => {
    if (editorRef.current) {
      onUpdate(editorRef.current.innerHTML);
    }
  };

  const exec = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
    setShowHighlightMenu(false);
    setShowEmojiMenu(false);
  };

  const insertEmoji = (emoji: string) => {
    exec('insertText', emoji);
  };

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            const base64 = e.target?.result as string;
            // Insere a imagem onde o cursor está
            editorRef.current?.focus();
            document.execCommand('insertImage', false, base64);
        };
        reader.readAsDataURL(file);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // Cores estilo Notion
  const highlights = [
    { label: 'Padrão', color: 'transparent', icon: '🚫' },
    { label: 'Cinza', color: 'rgba(255, 255, 255, 0.15)', icon: '⚪' },
    { label: 'Marrom', color: 'rgba(68, 42, 30, 0.6)', icon: '🟤' },
    { label: 'Laranja', color: 'rgba(217, 115, 13, 0.3)', icon: '🟠' },
    { label: 'Amarelo', color: 'rgba(202, 138, 4, 0.3)', icon: '🟡' },
    { label: 'Verde', color: 'rgba(22, 163, 74, 0.3)', icon: '🟢' },
    { label: 'Azul', color: 'rgba(37, 99, 235, 0.3)', icon: '🔵' },
    { label: 'Vermelho', color: 'rgba(220, 38, 38, 0.3)', icon: '🔴' },
  ];

  const emojis = ['🌐', '🍽️', '🍕', '🥞', '🥩', '🕒', '📅', '📍', '🏊', '🍸'];

  return (
    <div className="relative group/editor">
      {/* CSS Isolation for Editor Content */}
      <style>{`
        .editor-content h1 { font-size: 1.875rem; font-weight: 700; margin-top: 1.5em; margin-bottom: 0.5em; line-height: 1.2; }
        .editor-content h2 { font-size: 1.5rem; font-weight: 600; margin-top: 1.2em; margin-bottom: 0.5em; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 4px; }
        .editor-content ul { list-style-type: disc; padding-left: 1.5em; margin-bottom: 1em; }
        .editor-content ol { list-style-type: decimal; padding-left: 1.5em; margin-bottom: 1em; }
        .editor-content li { margin-bottom: 0.25em; padding-left: 0.2em; }
        .editor-content p { margin-bottom: 0.75em; min-height: 1.5em; }
        .editor-content b, .editor-content strong { font-weight: 700; color: #fff; }
        .editor-content hr { border-color: rgba(255,255,255,0.1); margin: 1.5em 0; }
        .editor-content img { max-width: 100%; border-radius: 4px; margin: 1em 0; }
        .editor-content span[style*="background-color"] { padding: 2px 4px; border-radius: 4px; color: #fff; }
      `}</style>

      {/* Hidden File Input for Image Block */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        className="hidden" 
      />

      {/* Floating Toolbar */}
      {!readOnly && (
        <div className="sticky top-11 z-40 mb-4 bg-[#252525] border border-white/10 rounded-lg p-1 flex items-center gap-1 w-fit shadow-xl opacity-0 group-hover/editor:opacity-100 focus-within:opacity-100 transition-opacity">

          <button onClick={() => exec('formatBlock', 'H1')} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 1">
            <Heading1 size={16} />
          </button>
          <button onClick={() => exec('formatBlock', 'H2')} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 2">
            <Heading2 size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          <button onClick={() => exec('bold')} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Negrito">
            <Bold size={16} />
          </button>
          <button onClick={() => exec('italic')} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Itálico">
            <Italic size={16} />
          </button>
          <button onClick={() => exec('insertUnorderedList')} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Lista">
            <List size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          {/* New Blocks: Divider and Image */}
          <button onClick={() => exec('insertHorizontalRule')} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Divisor">
            <Minus size={16} />
          </button>
          <button onClick={handleImageClick} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Inserir Imagem">
            <ImageIcon size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          {/* Highlight Dropdown */}
          <div className="relative">
            <button 
                onClick={() => { setShowHighlightMenu(!showHighlightMenu); setShowEmojiMenu(false); }}
                className={`p-1.5 hover:bg-white/10 rounded transition-colors flex items-center gap-1 ${showHighlightMenu ? 'bg-white/20 text-white' : 'text-notion-muted hover:text-white'}`} 
                title="Cor de Fundo"
            >
                <Highlighter size={16} />
            </button>
            {showHighlightMenu && (
                <div className="absolute top-full left-0 mt-2 bg-[#252525] border border-white/10 rounded shadow-xl p-1 grid grid-cols-4 gap-1 w-32 z-50">
                    {highlights.map((h) => (
                        <button
                            key={h.label}
                            onClick={() => exec('hiliteColor', h.color)}
                            className="w-6 h-6 rounded hover:scale-110 transition-transform flex items-center justify-center border border-white/5"
                            style={{ backgroundColor: h.color === 'transparent' ? '#333' : h.color }}
                            title={h.label}
                        >
                            {h.color === 'transparent' ? <div className="w-full h-px bg-red-400 rotate-45" /> : null}
                        </button>
                    ))}
                </div>
            )}
          </div>

          {/* Emoji Dropdown */}
          <div className="relative">
            <button 
                onClick={() => { setShowEmojiMenu(!showEmojiMenu); setShowHighlightMenu(false); }}
                className={`p-1.5 hover:bg-white/10 rounded transition-colors ${showEmojiMenu ? 'bg-white/20 text-white' : 'text-notion-muted hover:text-white'}`} 
                title="Inserir Ícone"
            >
                <Smile size={16} />
            </button>
            {showEmojiMenu && (
                <div className="absolute top-full left-0 mt-2 bg-[#252525] border border-white/10 rounded shadow-xl p-2 grid grid-cols-5 gap-1 w-40 z-50">
                    {emojis.map((emoji) => (
                        <button
                            key={emoji}
                            onClick={() => insertEmoji(emoji)}
                            className="text-lg hover:bg-white/10 rounded p-1 transition-colors"
                        >
                            {emoji}
                        </button>
                    ))}
                </div>
            )}
          </div>

        </div>
      )}

      {/* Editable Area */}
      <div
        ref={editorRef}
        contentEditable={!readOnly}
        onInput={handleInput}
        onBlur={handleBlur}
        className={`editor-content w-full min-h-[60px] outline-none text-notion-text empty:before:content-['Clique_para_editar...'] empty:before:text-notion-muted/50 ${readOnly ? '' : 'cursor-text'}`}
        spellCheck={false}
      />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCard, setActiveCard] = useState<DashboardCard | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards && Array.isArray(parsed.cards)) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle
                }));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                const img = parsed.metadata.home_cover_image || parsed.metadata.Home_Cover_Image;
                const pos = parsed.metadata.home_cover_pos || parsed.metadata.Home_Cover_Pos;
                if (img) setHomeCover(img);
                if (pos) setHomeCoverPos(Number(pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }
  }, []);

  // Navigation Logic
  const handleBackToHome = () => {
    setActiveCard(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleNavigateToCard = (card: DashboardCard) => {
    setActiveCard(card);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleBreadcrumbClick = (targetCard: DashboardCard) => {
    setActiveCard(targetCard);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Helper to build Breadcrumbs path from activeCard up to root
  const getBreadcrumbs = () => {
    if (!activeCard) return undefined;

    const path: { label: string; onClick?: () => void }[] = [];

    // Add Home
    path.push({ label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome });

    // Build hierarchy recursively
    const hierarchy: DashboardCard[] = [];
    let current: DashboardCard | undefined = activeCard;

    while (current) {
        hierarchy.unshift(current); // Add to front
        if (current.parentId) {
            current = cards.find(c => c.id === current?.parentId);
        } else {
            current = undefined;
        }
    }

    hierarchy.forEach((c, index) => {
        const isLast = index === hierarchy.length - 1;
        path.push({
            label: c.title,
            onClick: isLast ? undefined : () => handleBreadcrumbClick(c)
        });
    });

    return path;
  };

  const handleCreateNewCard = (parentId?: string) => {
    const newId = Date.now().toString(); 
    const newCard: DashboardCard = {
        id: newId,
        title: 'Nova Página',
        image: 'https://picsum.photos/seed/' + newId + '/600/300',
        icon: LucideIcons.FileText,
        iconName: 'FileText',
        content: '<p>Comece a escrever aqui...</p>',
        fullWidth: false,
        smallText: false,
        parentId: parentId || undefined // Define se é sub-página ou raiz
    };

    const updatedCards = [...cards, newCard];
    setCards(updatedCards);
    setActiveCard(newCard); // Navigate to new card
    window.scrollTo({ top: 0, behavior: 'auto' });
    saveToLocalCache(updatedCards);

    // Sync
    handleUpdateCard(newCard, true);
  };

  const handleSync = async (url: string) => {
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();
        console.log("Sync Result:", result); 

        // Parse Cards
        const newCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id || Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText,
                parentId: item.parentId
            };
        });

        // Parse Metadata
        if (result.metadata) {
            const img = result.metadata['home_cover_image'] || result.metadata['Home_Cover_Image'];
            const pos = result.metadata['home_cover_pos'] || result.metadata['Home_Cover_Pos'];

            if (img) setHomeCover(img);
            if (pos) setHomeCoverPos(Number(pos));
        }

        if (newCards.length > 0) {
            setCards(newCards);
            saveToLocalCache(newCards, result.metadata);
        }

    } catch (error) {
        console.error("Sync failed:", error);
        throw error;
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    const apiUrl = localStorage.getItem('vilage_dashboard_api_url');
    if (!apiUrl) return;

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(apiUrl, {
            method: 'POST',
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        if (result.status === 'success' && result.data.image && result.data.image.startsWith('http')) {
            setHomeCover(result.data.image);
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  // overload para aceitar card completo ou parcial
  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string } | DashboardCard, isNew = false) => {

    // Determina qual card estamos atualizando
    const targetCard = isNew ? (updatedFields as DashboardCard) : activeCard;
    if (!targetCard) return;

    // Mescla updates
    let updatedCardFull = { 
        ...targetCard, 
        ...updatedFields,
        icon: (updatedFields as any).iconName ? (LucideIcons as any)[(updatedFields as any).iconName] : (updatedFields.icon || targetCard.icon)
    };

    // Atualiza estado local
    if (!isNew && activeCard && activeCard.id === targetCard.id) setActiveCard(updatedCardFull);

    let newCardsList = cards.map(c => c.id === targetCard.id ? updatedCardFull : c);

    // Se for novo e não estiver na lista (segurança), adiciona
    if (isNew && !cards.find(c => c.id === targetCard.id)) {
        newCardsList = [...cards, updatedCardFull];
    }

    setCards(newCardsList);

    const apiUrl = localStorage.getItem('vilage_dashboard_api_url');
    if (!apiUrl) {
        saveToLocalCache(newCardsList);
        return;
    }

    try {
        const payload = {
            id: targetCard.id,
            title: updatedFields.title || targetCard.title,
            icon: (updatedFields as any).iconName || (targetCard as any).iconName || 'HelpCircle',
            content: updatedFields.content !== undefined ? updatedFields.content : targetCard.content,
            imageBase64: (updatedFields as any).imageBase64, 
            mimeType: (updatedFields as any).mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText,
            parentId: updatedCardFull.parentId // Envia o parentId para o script
        };

        const response = await fetch(apiUrl, { 
            method: 'POST', 
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        console.log("Card Update Result:", result);

        if (result.status === 'success' && result.data) {
            if (result.data.image && result.data.image.startsWith('http')) {
                updatedCardFull = { ...updatedCardFull, image: result.data.image };
                if (!isNew && activeCard && activeCard.id === targetCard.id) setActiveCard(updatedCardFull);
                newCardsList = newCardsList.map(c => c.id === targetCard.id ? updatedCardFull : c);
                setCards(newCardsList);
            }
            saveToLocalCache(newCardsList);
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
        saveToLocalCache(newCardsList);
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = getBreadcrumbs();

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                key={activeCard.id} // CRITICAL: Forces remount when navigating, fixing state issues
                card={activeCard} 
                allCards={cards} // Pass full list to find children
                onUpdateCard={handleUpdateCard} 
                onNavigateToCard={handleNavigateToCard}
                onCreateSubPage={handleCreateNewCard}
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards.filter(c => !c.parentId)} // Only show root cards on home
                    onCardClick={handleNavigateToCard} 
                    onNewCard={() => handleCreateNewCard()} // Root card
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useState } from 'react';
