        <p><br/></p>
    `;

    document.execCommand('insertHTML', false, html);
  };

  // --- Image Styling Actions ---

  const updateImageStyle = (action: 'size' | 'rounded' | 'border' | 'frame', value?: string) => {
    if (!selectedImage || selectedImage.tagName !== 'IMG') return;

    const img = selectedImage as HTMLImageElement;
    const figure = img.closest('figure');
    const wrapper = img.parentElement; // div.image-wrapper

    if (!figure || !wrapper) return;

    // Save current selection to restore focus later? No need for images.

    switch (action) {
        case 'size':
            // We adjust the wrapper width
            wrapper.style.width = value || '100%';
            break;
        case 'rounded':
             if (img.classList.contains('rounded-xl')) {
                 img.classList.remove('rounded-xl', 'rounded-full');
                 img.classList.add('rounded-md'); // default
             } else {
                 img.classList.remove('rounded-md');
                 img.classList.add('rounded-xl');
             }
             break;
        case 'border':
             if (img.classList.contains('border-4')) {
                 img.classList.remove('border-4', 'border-notion-text/20');
                 img.classList.add('border-transparent');
             } else {
                 img.classList.remove('border-transparent');
                 img.classList.add('border-4', 'border-notion-text/20');
             }
             break;
        case 'frame':
             // Add border to the whole figure (image + text)
             if (figure.classList.contains('p-4')) {
                 figure.classList.remove('border', 'border-notion-muted/30', 'bg-white/5', 'rounded-xl', 'p-4');
             } else {
                 figure.classList.add('border', 'border-notion-muted/30', 'bg-white/5', 'rounded-xl', 'p-4');
             }
             break;
    }

