        /* Selection Outline for Image */
        .editor-content img.selected-img { outline: 3px solid #2383e2; box-shadow: 0 0 0 4px rgba(35, 131, 226, 0.3); }
      `}</style>

      {/* Hidden File Input for Image Block */}
      <input 
