      {/* --- Main Text Toolbar --- */}
      {!readOnly && !selectedImage && (
        <div className="editor-toolbar sticky top-11 z-40 mb-4 bg-[#252525] border border-white/10 rounded-lg p-1 flex items-center gap-1 w-fit shadow-xl opacity-0 group-hover/editor:opacity-100 focus-within:opacity-100 transition-opacity">

          <button onMouseDown={(e) => { e.preventDefault(); exec('formatBlock', 'H1'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 1">
