import React, { useState } from 'react';
import { X, RefreshCw, Save, Copy, Check } from 'lucide-react';
import { API_URL } from '../constants';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSync: () => Promise<void>;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, onSync }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [copied, setCopied] = useState(false);

  const handleSaveAndSync = async () => {
    setIsLoading(true);
    setStatus('idle');

    try {
      await onSync();
      setStatus('success');
      setTimeout(() => {
        onClose();
        setStatus('idle');
      }, 1000);
    } catch (error) {
      console.error(error);
      setStatus('error');
    } finally {
      setIsLoading(false);
    }
  };

  const copyScript = () => {
    navigator.clipboard.writeText(GOOGLE_SCRIPT_CODE);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-[#202020] w-full max-w-2xl max-h-[90vh] rounded-xl shadow-2xl border border-white/10 flex flex-col relative">

        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5 shrink-0">
            <h2 className="text-notion-text font-medium text-lg">Integração Google Sheets & Drive</h2>
            <button onClick={onClose} className="text-notion-muted hover:text-notion-text transition-colors">
                <X size={20} />
            </button>
        </div>

        {/* Scrollable Body */}
        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar">

            {/* Status Section */}
            <div className="bg-[#252525] p-4 rounded border border-white/5">
                <label className="block text-xs font-bold text-notion-muted uppercase mb-2">
                    Status da Conexão
                </label>
                <div className="flex flex-col gap-2">
                   <p className="text-sm text-notion-text">
                       Conectado ao Web App integrado:
                   </p>
                   <code className="text-xs text-notion-muted break-all bg-[#191919] p-2 rounded">
                       {API_URL}
                   </code>
                </div>
                {status === 'error' && <p className="text-red-400 text-xs mt-2">Erro ao conectar. Verifique sua conexão.</p>}
                {status === 'success' && <p className="text-green-400 text-xs mt-2">Sincronizado com sucesso!</p>}
            </div>

            {/* Script Section */}
            <div>
                <div className="flex items-center justify-between mb-2">
                    <label className="block text-xs font-bold text-notion-muted uppercase">
                        Script do Backend
                    </label>
                    <button 
                        onClick={copyScript}
                        className="flex items-center gap-1 text-xs text-notion-blue hover:text-notion-blueHover transition-colors"
                    >
                        {copied ? <Check size={12} /> : <Copy size={12} />}
                        {copied ? 'Copiado!' : 'Copiar Script'}
                    </button>
                </div>

                <div className="text-xs text-notion-muted mb-2 space-y-1">
                   <p>Use este código no Google Apps Script caso precise reimplantar o backend.</p>
                </div>

                <div className="relative group">
                    <pre className="bg-[#151515] text-gray-300 p-4 rounded border border-white/5 text-[11px] font-mono overflow-x-auto whitespace-pre leading-relaxed select-all">
                        {GOOGLE_SCRIPT_CODE}
                    </pre>
                </div>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-white/5 flex justify-end gap-2 shrink-0 bg-[#202020]">
            <button 
                onClick={onClose}
                className="px-3 py-1.5 text-sm text-notion-muted hover:bg-white/5 rounded transition-colors"
            >
                Fechar
            </button>
            <button 
                onClick={handleSaveAndSync}
                disabled={isLoading}
                className="px-3 py-1.5 text-sm bg-notion-blue hover:bg-notion-blueHover text-white rounded shadow-sm disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
                {isLoading ? <RefreshCw className="animate-spin" size={14} /> : <Save size={14} />}
                {isLoading ? 'Sincronizando...' : 'Forçar Sincronização'}
            </button>
        </div>

      </div>
    </div>
  );
};

const GOOGLE_SCRIPT_CODE = `// CONFIGURAÇÃO
var DRIVE_FOLDER_ID = "1w-DofVpEHKA46fEr6Gij38AcQJijl6iC";
var METADATA_SHEET_NAME = "_Metadata";

function doGet() {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheets = ss.getSheets();
    var cards = [];
    var metadata = {};

    // 1. Ler Metadados
    var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
    if (metaSheet) {
      var data = metaSheet.getDataRange().getValues();
      for (var i = 0; i < data.length; i++) {
        if (data[i][0]) metadata[data[i][0].toString().toLowerCase()] = data[i][1];
      }
    }

    // 2. Ler Cartões
    sheets.forEach(function(sheet) {
      if (sheet.getName().startsWith("_")) return;

      var title = sheet.getRange("B1").getValue();
      if (!title) title = sheet.getName();

      // Leitura robusta das células
      var image = sheet.getRange("B2").getValue();
      var icon = sheet.getRange("B3").getValue();
      var content = sheet.getRange("B4").getValue();
      var fullWidth = sheet.getRange("B5").getValue();
      var smallText = sheet.getRange("B6").getValue();
      var parentId = sheet.getRange("B7").getValue(); // NOVO: Parent ID

      cards.push({
        id: sheet.getSheetId().toString(), 
        title: title,
        image: image || "https://picsum.photos/800/400",
        icon: icon || "FileText",
        content: content || "",
        fullWidth: fullWidth === true || fullWidth === "TRUE",
        smallText: smallText === true || smallText === "TRUE",
        parentId: parentId ? parentId.toString() : "" 
      });
    });

    return createJSONOutput({status: "success", cards: cards, metadata: metadata});
  } catch(e) {
    return createJSONOutput({status: "error", message: e.toString()});
  }
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(30000);

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- METADATA (Capa Global) ---
    if (data.type === 'metadata') {
       var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
       if (!metaSheet) {
         metaSheet = ss.insertSheet(METADATA_SHEET_NAME);
         metaSheet.appendRow(["Key", "Value"]);
       }

       var saveData = function(key, val) {
         var range = metaSheet.getDataRange();
         var values = range.getValues();
         for(var i=0; i<values.length; i++) {
           if(values[i][0].toString().toLowerCase() === key.toLowerCase()) {
             metaSheet.getRange(i+1, 2).setValue(val);
             return;
           }
         }
         metaSheet.appendRow([key, val]);
       };

       if (data.homeCoverPosition) saveData("home_cover_pos", data.homeCoverPosition);

       if (data.imageBase64) {
         var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Home_Cover_" + new Date().getTime());
         if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
         saveData("home_cover_image", uploadResult.url);
         data.image = uploadResult.url;
       }

       return createJSONOutput({status: "success", data: data});
    }

    // --- CARTÕES (Abas) ---
    var sheets = ss.getSheets();
    var targetSheet = null;

    if (data.id) {
      for (var i = 0; i < sheets.length; i++) {
        if (sheets[i].getSheetId().toString() === data.id) {
          targetSheet = sheets[i];
          break;
        }
      }
    }
    if (!targetSheet && data.title) targetSheet = ss.getSheetByName(data.title);

    // Criar Nova Aba se não existir
    if (!targetSheet) {
       var safeTitle = (data.title || "New Page " + new Date().getSeconds()).substring(0,50);
       try { targetSheet = ss.insertSheet(safeTitle); } 
       catch(e) { targetSheet = ss.insertSheet(safeTitle + Math.floor(Math.random()*100)); }

       targetSheet.getRange("A1:A7").setValues([["Title"], ["Image"], ["Icon"], ["ContentHTML"], ["FullWidth"], ["SmallText"], ["ParentID"]]);
    }

    // Salvar Dados
    if (data.title) targetSheet.getRange("B1").setValue(data.title);
    if (data.icon) targetSheet.getRange("B3").setValue(data.icon);
    if (data.content !== undefined) targetSheet.getRange("B4").setValue(data.content);
    if (data.fullWidth !== undefined) targetSheet.getRange("B5").setValue(data.fullWidth);
    if (data.smallText !== undefined) targetSheet.getRange("B6").setValue(data.smallText);

    // Salvar Parent ID (Vincular a sub-página)
    if (data.parentId !== undefined) targetSheet.getRange("B7").setValue(data.parentId);

    // Upload da Imagem do Cartão
    if (data.imageBase64) {
      var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Card_" + targetSheet.getName() + "_" + new Date().getTime());
      if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
      targetSheet.getRange("B2").setValue(uploadResult.url);
      data.image = uploadResult.url;
    }

    // Atualizar nome da aba
    if (data.title && targetSheet.getName() !== data.title) {
        try { targetSheet.setName(data.title.substring(0, 50)); } catch(e) {}
    }

    data.id = targetSheet.getSheetId().toString();
    return createJSONOutput({status: "success", data: data});

  } catch (err) {
    return createJSONOutput({status: "error", message: err.toString()});
  } finally {
    lock.releaseLock();
  }
}

function uploadToDrive(base64Data, mimeType, fileName) {
  try {
    var folder;
    if (DRIVE_FOLDER_ID) {
      try { folder = DriveApp.getFolderById(DRIVE_FOLDER_ID); } catch(e) { folder = null; }
    }
    if (!folder) folder = DriveApp.getRootFolder();

    var cleanBase64 = base64Data;
    if (base64Data.indexOf("base64,") !== -1) {
      cleanBase64 = base64Data.split("base64,")[1];
    }

    var blob = Utilities.newBlob(Utilities.base64Decode(cleanBase64), mimeType || "image/jpeg", fileName);
    var file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    return { url: "https://lh3.googleusercontent.com/d/" + file.getId() };

  } catch(e) {
    return { error: e.toString() };
  }
}

function createJSONOutput(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}`;

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE, API_URL } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCard, setActiveCard] = useState<DashboardCard | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards && Array.isArray(parsed.cards)) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle
                }));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                const img = parsed.metadata.home_cover_image || parsed.metadata.Home_Cover_Image;
                const pos = parsed.metadata.home_cover_pos || parsed.metadata.Home_Cover_Pos;
                if (img) setHomeCover(img);
                if (pos) setHomeCoverPos(Number(pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }

    // Auto-Sync on Mount (Integrated)
    handleSync();
  }, []);

  // Navigation Logic
  const handleBackToHome = () => {
    setActiveCard(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleNavigateToCard = (card: DashboardCard) => {
    setActiveCard(card);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleBreadcrumbClick = (targetCard: DashboardCard) => {
    setActiveCard(targetCard);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Helper to build Breadcrumbs path from activeCard up to root
  const getBreadcrumbs = () => {
    if (!activeCard) return undefined;

    const path: { label: string; onClick?: () => void }[] = [];

    // Add Home
    path.push({ label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome });

    // Build hierarchy recursively
    const hierarchy: DashboardCard[] = [];
    let current: DashboardCard | undefined = activeCard;

    while (current) {
        hierarchy.unshift(current); // Add to front
        if (current.parentId) {
            // Loose comparison for robustness (string vs number)
            current = cards.find(c => c.id == current?.parentId);
        } else {
            current = undefined;
        }
    }

    hierarchy.forEach((c, index) => {
        const isLast = index === hierarchy.length - 1;
        path.push({
            label: c.title,
            onClick: isLast ? undefined : () => handleBreadcrumbClick(c)
        });
    });

    return path;
  };

  const handleCreateNewCard = (parentId?: string) => {
    const newId = Date.now().toString(); 
    // If parentId is an event object (unlikely but possible), ignore it
    const safeParentId = typeof parentId === 'string' ? parentId : undefined;

    const newCard: DashboardCard = {
        id: newId,
        title: 'Nova Página',
        image: 'https://picsum.photos/seed/' + newId + '/600/300',
        icon: LucideIcons.FileText,
        iconName: 'FileText',
        content: '<p>Comece a escrever aqui...</p>',
        fullWidth: false,
        smallText: false,
        parentId: safeParentId
    };

    const updatedCards = [...cards, newCard];
    setCards(updatedCards);
    setActiveCard(newCard); // Navigate to new card
    window.scrollTo({ top: 0, behavior: 'auto' });
    saveToLocalCache(updatedCards);

    // Sync
    handleUpdateCard(newCard, true);
  };

  const handleSync = async () => {
    try {
        const response = await fetch(API_URL);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();
        console.log("Sync Result:", result); 

        // Parse Cards
        const newCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id ? item.id.toString() : Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText,
                parentId: item.parentId ? item.parentId.toString() : undefined
            };
        });

        // --- SMART ORGANIZATION FIX ---
        // Force days of the week to be children of "Programações" if they are orphan
        const progCard = newCards.find(c => c.title === 'Programações' || c.title === 'Programacoes');

        if (progCard) {
            const daysOfWeek = [
                'Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado',
                'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira'
            ];

            newCards.forEach(c => {
                // If the card title matches a day of the week AND it has no parent
                if (daysOfWeek.some(day => c.title.includes(day)) && !c.parentId && c.id !== progCard.id) {
                    console.log(`Auto-organizing: Moving ${c.title} under ${progCard.title}`);
                    c.parentId = progCard.id;
                }
            });
        }
        // -----------------------------

        // Parse Metadata
        if (result.metadata) {
            const img = result.metadata['home_cover_image'] || result.metadata['Home_Cover_Image'];
            const pos = result.metadata['home_cover_pos'] || result.metadata['Home_Cover_Pos'];

            if (img) setHomeCover(img);
            if (pos) setHomeCoverPos(Number(pos));
        }

        if (newCards.length > 0) {
            setCards(newCards);
            saveToLocalCache(newCards, result.metadata);
        }

    } catch (error) {
        console.error("Sync failed:", error);
        // Don't throw, just log
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        if (result.status === 'success' && result.data.image && result.data.image.startsWith('http')) {
            setHomeCover(result.data.image);
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  // overload para aceitar card completo ou parcial
  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string } | DashboardCard, isNew = false) => {

    // Determina qual card estamos atualizando
    const targetCard = isNew ? (updatedFields as DashboardCard) : activeCard;
    if (!targetCard) return;

    // Mescla updates
    let updatedCardFull = { 
        ...targetCard, 
        ...updatedFields,
        icon: (updatedFields as any).iconName ? (LucideIcons as any)[(updatedFields as any).iconName] : (updatedFields.icon || targetCard.icon)
    };

    // Atualiza estado local
    if (!isNew && activeCard && activeCard.id === targetCard.id) setActiveCard(updatedCardFull);

    let newCardsList = cards.map(c => c.id === targetCard.id ? updatedCardFull : c);

    // Se for novo e não estiver na lista (segurança), adiciona
    if (isNew && !cards.find(c => c.id === targetCard.id)) {
        newCardsList = [...cards, updatedCardFull];
    }

    setCards(newCardsList);

    // Optimistically save to cache
    saveToLocalCache(newCardsList);

    try {
        const payload = {
            id: targetCard.id,
            title: updatedFields.title || targetCard.title,
            icon: (updatedFields as any).iconName || (targetCard as any).iconName || 'HelpCircle',
            content: updatedFields.content !== undefined ? updatedFields.content : targetCard.content,
            imageBase64: (updatedFields as any).imageBase64, 
            mimeType: (updatedFields as any).mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText,
            parentId: updatedCardFull.parentId // Envia o parentId para o script
        };

        const response = await fetch(API_URL, { 
            method: 'POST', 
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        console.log("Card Update Result:", result);

        if (result.status === 'success' && result.data) {
            if (result.data.image && result.data.image.startsWith('http')) {
                updatedCardFull = { ...updatedCardFull, image: result.data.image };
                if (!isNew && activeCard && activeCard.id === targetCard.id) setActiveCard(updatedCardFull);
                newCardsList = newCardsList.map(c => c.id === targetCard.id ? updatedCardFull : c);
                setCards(newCardsList);
            }
            saveToLocalCache(newCardsList);
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
        // We already saved to local cache above, so data persists locally at least
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = getBreadcrumbs();

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                key={activeCard.id} // CRITICAL: Forces remount when navigating, fixing state issues
                card={activeCard} 
                allCards={cards} // Pass full list to find children
                onUpdateCard={handleUpdateCard} 
                onNavigateToCard={handleNavigateToCard}
                onCreateSubPage={handleCreateNewCard}
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards.filter(c => !c.parentId)} // Only show root cards on home
                    onCardClick={handleNavigateToCard} 
                    onNewCard={() => handleCreateNewCard()} // Root card
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

import React from 'react';
import { DashboardCard } from '../types';

interface CardProps {
  card: DashboardCard;
  onClick: (card: DashboardCard) => void;
  onDrop?: (draggedId: string, targetId: string) => void;
}

export const Card: React.FC<CardProps> = ({ card, onClick, onDrop }) => {
  const Icon = card.icon;

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('cardId', card.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Necessary to allow dropping
    e.currentTarget.classList.add('ring-2', 'ring-notion-blue', 'bg-notion-hover');
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.currentTarget.classList.remove('ring-2', 'ring-notion-blue', 'bg-notion-hover');
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.currentTarget.classList.remove('ring-2', 'ring-notion-blue', 'bg-notion-hover');

    const draggedId = e.dataTransfer.getData('cardId');
    if (draggedId && draggedId !== card.id && onDrop) {
        onDrop(draggedId, card.id);
    }
  };

  return (
    <div 
      draggable={!!onDrop}
      onDragStart={handleDragStart}
      onDragOver={onDrop ? handleDragOver : undefined}
      onDragLeave={onDrop ? handleDragLeave : undefined}
      onDrop={onDrop ? handleDrop : undefined}
      onClick={() => onClick(card)}
      className="group relative flex flex-col rounded-xl overflow-hidden bg-notion-card hover:bg-notion-hover transition-colors cursor-pointer border border-transparent hover:border-white/5 shadow-sm hover:shadow-lg select-none"
    >
      {/* Image Area */}
      <div className="h-32 w-full overflow-hidden relative pointer-events-none">
        <img 
          src={card.image} 
          alt={card.title} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
        />
        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
      </div>

      {/* Content Area */}
      <div className="p-3 flex items-center gap-3 pointer-events-none">
        {/* Icon Box */}
        <div className="flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-lg bg-white/5 text-notion-text border border-white/5 shadow-sm">
          <Icon size={18} />
        </div>

        {/* Title */}
        <span className="text-sm font-medium text-notion-text truncate w-full border-b border-transparent group-hover:border-notion-muted/50 pb-0.5 transition-all">
          {card.title}
        </span>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE, API_URL } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCard, setActiveCard] = useState<DashboardCard | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards && Array.isArray(parsed.cards)) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle
                }));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                const img = parsed.metadata.home_cover_image || parsed.metadata.Home_Cover_Image;
                const pos = parsed.metadata.home_cover_pos || parsed.metadata.Home_Cover_Pos;
                if (img) setHomeCover(img);
                if (pos) setHomeCoverPos(Number(pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }

    // Auto-Sync on Mount (Integrated)
    handleSync();
  }, []);

  // Navigation Logic
  const handleBackToHome = () => {
    setActiveCard(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleNavigateToCard = (card: DashboardCard) => {
    setActiveCard(card);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleBreadcrumbClick = (targetCard: DashboardCard) => {
    setActiveCard(targetCard);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Helper to build Breadcrumbs path from activeCard up to root
  const getBreadcrumbs = () => {
    if (!activeCard) return undefined;

    const path: { label: string; onClick?: () => void }[] = [];

    // Add Home
    path.push({ label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome });

    // Build hierarchy recursively
    const hierarchy: DashboardCard[] = [];
    let current: DashboardCard | undefined = activeCard;

    while (current) {
        hierarchy.unshift(current); // Add to front
        if (current.parentId) {
            // Loose comparison for robustness (string vs number)
            current = cards.find(c => c.id == current?.parentId);
        } else {
            current = undefined;
        }
    }

    hierarchy.forEach((c, index) => {
        const isLast = index === hierarchy.length - 1;
        path.push({
            label: c.title,
            onClick: isLast ? undefined : () => handleBreadcrumbClick(c)
        });
    });

    return path;
  };

  const handleCreateNewCard = (parentId?: string) => {
    const newId = Date.now().toString(); 
    // If parentId is an event object (unlikely but possible), ignore it
    const safeParentId = typeof parentId === 'string' ? parentId : undefined;

    const newCard: DashboardCard = {
        id: newId,
        title: 'Nova Página',
        image: 'https://picsum.photos/seed/' + newId + '/600/300',
        icon: LucideIcons.FileText,
        iconName: 'FileText',
        content: '<p>Comece a escrever aqui...</p>',
        fullWidth: false,
        smallText: false,
        parentId: safeParentId
    };

    const updatedCards = [...cards, newCard];
    setCards(updatedCards);
    setActiveCard(newCard); // Navigate to new card
    window.scrollTo({ top: 0, behavior: 'auto' });
    saveToLocalCache(updatedCards);

    // Sync
    handleUpdateCard(newCard, true);
  };

  // --- Deletion Logic ---
  const handleDeleteCard = async (cardId: string) => {
    if (!window.confirm("Tem certeza que deseja excluir esta página e todo o conteúdo dela?")) return;

    // Optimistic UI Update
    const updatedCards = cards.filter(c => c.id !== cardId && c.parentId !== cardId); // Remove card and children (simple approach)
    setCards(updatedCards);
    saveToLocalCache(updatedCards);

    // If active card was deleted, go home
    if (activeCard && activeCard.id === cardId) {
        handleBackToHome();
    }

    try {
        const payload = {
            type: 'delete',
            id: cardId
        };
        await fetch(API_URL, { method: 'POST', body: JSON.stringify(payload) });
    } catch (e) {
        console.error("Delete failed on server", e);
        alert("Erro ao excluir no servidor. A alteração local foi mantida.");
    }
  };

  // --- Move/Nest Logic (Drag and Drop) ---
  const handleMoveCard = async (draggedId: string, targetParentId?: string) => {
    // Prevent self-nesting or circular references (simple check)
    if (draggedId === targetParentId) return;

    console.log(`Moving ${draggedId} to ${targetParentId || 'root'}`);

    const cardToMove = cards.find(c => c.id === draggedId);
    if (!cardToMove) return;

    const updatedCard = { ...cardToMove, parentId: targetParentId };
    const updatedList = cards.map(c => c.id === draggedId ? updatedCard : c);

    setCards(updatedList);
    saveToLocalCache(updatedList);

    // Update active card if it's the one being moved
    if (activeCard && activeCard.id === draggedId) {
        setActiveCard(updatedCard);
    }

    // Server Sync
    handleUpdateCard(updatedCard);
  };

  const handleSync = async () => {
    try {
        const response = await fetch(API_URL);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();
        console.log("Sync Result:", result); 

        // Parse Cards
        const newCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id ? item.id.toString() : Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText,
                parentId: item.parentId ? item.parentId.toString() : undefined
            };
        });

        // --- SMART ORGANIZATION FIX ---
        const progCard = newCards.find(c => c.title === 'Programações' || c.title === 'Programacoes');
        if (progCard) {
            const daysOfWeek = [
                'Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado',
                'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira'
            ];
            newCards.forEach(c => {
                if (daysOfWeek.some(day => c.title.includes(day)) && !c.parentId && c.id !== progCard.id) {
                    c.parentId = progCard.id;
                }
            });
        }

        // Parse Metadata
        if (result.metadata) {
            const img = result.metadata['home_cover_image'] || result.metadata['Home_Cover_Image'];
            const pos = result.metadata['home_cover_pos'] || result.metadata['Home_Cover_Pos'];

            if (img) setHomeCover(img);
            if (pos) setHomeCoverPos(Number(pos));
        }

        if (newCards.length > 0) {
            setCards(newCards);
            saveToLocalCache(newCards, result.metadata);
        }

    } catch (error) {
        console.error("Sync failed:", error);
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        if (result.status === 'success' && result.data.image && result.data.image.startsWith('http')) {
            setHomeCover(result.data.image);
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  // overload para aceitar card completo ou parcial
  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string } | DashboardCard, isNew = false) => {

    const targetCard = isNew ? (updatedFields as DashboardCard) : (
        // If updating a card that isn't the active one (e.g. DnD), find it in list
        (updatedFields as any).id ? cards.find(c => c.id === (updatedFields as any).id) || activeCard : activeCard
    );

    if (!targetCard) return;

    let updatedCardFull = { 
        ...targetCard, 
        ...updatedFields,
        icon: (updatedFields as any).iconName ? (LucideIcons as any)[(updatedFields as any).iconName] : (updatedFields.icon || targetCard.icon)
    };

    // Atualiza estado local
    if (!isNew && activeCard && activeCard.id === targetCard.id) setActiveCard(updatedCardFull);

    let newCardsList = cards.map(c => c.id === targetCard.id ? updatedCardFull : c);

    if (isNew && !cards.find(c => c.id === targetCard.id)) {
        newCardsList = [...cards, updatedCardFull];
    }

    setCards(newCardsList);
    saveToLocalCache(newCardsList);

    try {
        const payload = {
            id: targetCard.id,
            title: updatedFields.title || targetCard.title,
            icon: (updatedFields as any).iconName || (targetCard as any).iconName || 'HelpCircle',
            content: updatedFields.content !== undefined ? updatedFields.content : targetCard.content,
            imageBase64: (updatedFields as any).imageBase64, 
            mimeType: (updatedFields as any).mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText,
            parentId: updatedCardFull.parentId // Critical for move logic
        };

        const response = await fetch(API_URL, { 
            method: 'POST', 
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        if (result.status === 'success' && result.data) {
            if (result.data.image && result.data.image.startsWith('http')) {
                updatedCardFull = { ...updatedCardFull, image: result.data.image };
                if (!isNew && activeCard && activeCard.id === targetCard.id) setActiveCard(updatedCardFull);
                newCardsList = newCardsList.map(c => c.id === targetCard.id ? updatedCardFull : c);
                setCards(newCardsList);
            }
            saveToLocalCache(newCardsList);
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = getBreadcrumbs();

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                key={activeCard.id} 
                card={activeCard} 
                allCards={cards} 
                onUpdateCard={handleUpdateCard} 
                onNavigateToCard={handleNavigateToCard}
                onCreateSubPage={handleCreateNewCard}
                onDeleteCard={handleDeleteCard} // Pass delete handler
                onMoveCard={handleMoveCard} // Pass move handler
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards.filter(c => !c.parentId)} 
                    onCardClick={handleNavigateToCard} 
                    onNewCard={() => handleCreateNewCard()}
                    onMoveCard={handleMoveCard} // Pass move handler to root
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { DashboardCard } from '../types';
import { LayoutTemplate, Loader2, MoreHorizontal, Plus, Trash2, ArrowUpCircle } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { IconPicker } from './IconPicker';
import { RichTextEditor } from './RichTextEditor';
import { Card } from './Card'; // Import reused Card component

interface ActivePageProps {
  card: DashboardCard;
  allCards: DashboardCard[]; 
  onUpdateCard: (fields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string }) => void;
  onNavigateToCard: (card: DashboardCard) => void;
  onCreateSubPage: (parentId: string) => void;
  onDeleteCard: (cardId: string) => void;
  onMoveCard: (draggedId: string, targetParentId?: string) => void;
}

export const ActivePage: React.FC<ActivePageProps> = ({ 
  card, 
  allCards, 
  onUpdateCard, 
  onNavigateToCard, 
  onCreateSubPage,
  onDeleteCard,
  onMoveCard
}) => {
  const [currentIconName, setCurrentIconName] = useState<string>(
    typeof card.icon === 'string' ? card.icon : ((card as any).iconName || 'HelpCircle')
  );
  const [isUploading, setIsUploading] = useState(false);
  const [showIconPicker, setShowIconPicker] = useState(false);
  const [showPageOptions, setShowPageOptions] = useState(false);

  const [fullWidth, setFullWidth] = useState(card.fullWidth || false);
  const [smallText, setSmallText] = useState(card.smallText || false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const optionsMenuRef = useRef<HTMLDivElement>(null);

  const subPages = allCards.filter(c => c.parentId === card.id);

  useEffect(() => {
    setFullWidth(card.fullWidth || false);
    setSmallText(card.smallText || false);
  }, [card.id, card.fullWidth, card.smallText]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (optionsMenuRef.current && !optionsMenuRef.current.contains(event.target as Node)) {
        setShowPageOptions(false);
      }
    };
    if (showPageOptions) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showPageOptions]);

  const Icon = (LucideIcons as any)[currentIconName] || LucideIcons.HelpCircle;

  // --- Handlers ---

  const handleTitleChange = (e: React.FocusEvent<HTMLInputElement>) => {
    if (e.target.value !== card.title) {
        onUpdateCard({ title: e.target.value });
    }
  };

  const handleIconSelect = (newIconName: string) => {
    setCurrentIconName(newIconName);
    onUpdateCard({ icon: newIconName, iconName: newIconName } as any);
    setShowIconPicker(false);
  };

  const handleChangeCoverClick = () => {
    fileInputRef.current?.click();
  };

  const handleToggleFullWidth = () => {
    const newValue = !fullWidth;
    setFullWidth(newValue);
    onUpdateCard({ fullWidth: newValue });
  };

  const handleToggleSmallText = () => {
    const newValue = !smallText;
    setSmallText(newValue);
    onUpdateCard({ smallText: newValue });
  };

  const handleContentUpdate = (newHtml: string) => {
    if (newHtml !== card.content) {
        onUpdateCard({ content: newHtml });
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
