import React, { useState } from 'react';
import { X, RefreshCw, Save, Copy, Check } from 'lucide-react';
import { API_URL } from '../constants';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSync: () => Promise<void>;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, onSync }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [copied, setCopied] = useState(false);

  const handleSaveAndSync = async () => {
    setIsLoading(true);
    setStatus('idle');

    try {
      await onSync();
      setStatus('success');
      setTimeout(() => {
        onClose();
        setStatus('idle');
      }, 1000);
    } catch (error) {
      console.error(error);
      setStatus('error');
    } finally {
      setIsLoading(false);
    }
  };

  const copyScript = () => {
    navigator.clipboard.writeText(GOOGLE_SCRIPT_CODE);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-[#202020] w-full max-w-2xl max-h-[90vh] rounded-xl shadow-2xl border border-white/10 flex flex-col relative">

        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5 shrink-0">
            <h2 className="text-notion-text font-medium text-lg">Integração Google Sheets & Drive</h2>
            <button onClick={onClose} className="text-notion-muted hover:text-notion-text transition-colors">
                <X size={20} />
            </button>
        </div>

        {/* Scrollable Body */}
        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar">

            {/* Status Section */}
            <div className="bg-[#252525] p-4 rounded border border-white/5">
                <label className="block text-xs font-bold text-notion-muted uppercase mb-2">
                    Status da Conexão
                </label>
                <div className="flex flex-col gap-2">
                   <p className="text-sm text-notion-text">
                       Conectado ao Web App integrado:
                   </p>
                   <code className="text-xs text-notion-muted break-all bg-[#191919] p-2 rounded">
                       {API_URL}
                   </code>
                </div>
                {status === 'error' && <p className="text-red-400 text-xs mt-2">Erro ao conectar. Verifique sua conexão.</p>}
                {status === 'success' && <p className="text-green-400 text-xs mt-2">Sincronizado com sucesso!</p>}
            </div>

            {/* Script Section */}
            <div>
                <div className="flex items-center justify-between mb-2">
                    <label className="block text-xs font-bold text-notion-muted uppercase">
                        Script do Backend
                    </label>
                    <button 
                        onClick={copyScript}
                        className="flex items-center gap-1 text-xs text-notion-blue hover:text-notion-blueHover transition-colors"
                    >
                        {copied ? <Check size={12} /> : <Copy size={12} />}
                        {copied ? 'Copiado!' : 'Copiar Script'}
                    </button>
                </div>

                <div className="text-xs text-notion-muted mb-2 space-y-1">
                   <p>Atualize seu script no Google Apps Script para habilitar a função de <b>Excluir</b> e <b>Ordenação</b>.</p>
                </div>

                <div className="relative group">
                    <pre className="bg-[#151515] text-gray-300 p-4 rounded border border-white/5 text-[11px] font-mono overflow-x-auto whitespace-pre leading-relaxed select-all">
                        {GOOGLE_SCRIPT_CODE}
                    </pre>
                </div>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-white/5 flex justify-end gap-2 shrink-0 bg-[#202020]">
            <button 
                onClick={onClose}
                className="px-3 py-1.5 text-sm text-notion-muted hover:bg-white/5 rounded transition-colors"
            >
                Fechar
            </button>
            <button 
                onClick={handleSaveAndSync}
                disabled={isLoading}
                className="px-3 py-1.5 text-sm bg-notion-blue hover:bg-notion-blueHover text-white rounded shadow-sm disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
                {isLoading ? <RefreshCw className="animate-spin" size={14} /> : <Save size={14} />}
                {isLoading ? 'Sincronizando...' : 'Forçar Sincronização'}
            </button>
        </div>

      </div>
    </div>
  );
};

const GOOGLE_SCRIPT_CODE = `// CONFIGURAÇÃO
var DRIVE_FOLDER_ID = "1w-DofVpEHKA46fEr6Gij38AcQJijl6iC";
var METADATA_SHEET_NAME = "_Metadata";

function doGet() {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheets = ss.getSheets();
    var cards = [];
    var metadata = {};

    // 1. Ler Metadados
    var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
    if (metaSheet) {
      var data = metaSheet.getDataRange().getValues();
      for (var i = 0; i < data.length; i++) {
        if (data[i][0]) metadata[data[i][0].toString().toLowerCase()] = data[i][1];
      }
    }

    // 2. Ler Cartões
    sheets.forEach(function(sheet) {
      if (sheet.getName().startsWith("_")) return;

      var title = sheet.getRange("B1").getValue();
      if (!title) title = sheet.getName();

      // Leitura robusta das células
      var image = sheet.getRange("B2").getValue();
      var icon = sheet.getRange("B3").getValue();
      var content = sheet.getRange("B4").getValue();
      var fullWidth = sheet.getRange("B5").getValue();
      var smallText = sheet.getRange("B6").getValue();
      var parentId = sheet.getRange("B7").getValue(); // Parent ID
      var order = sheet.getRange("B8").getValue(); // NOVO: Order

      cards.push({
        id: sheet.getSheetId().toString(), 
        title: title,
        image: image || "https://picsum.photos/800/400",
        icon: icon || "FileText",
        content: content || "",
        fullWidth: fullWidth === true || fullWidth === "TRUE",
        smallText: smallText === true || smallText === "TRUE",
        parentId: parentId ? parentId.toString() : "",
        order: typeof order === 'number' ? order : 0
      });
    });

    return createJSONOutput({status: "success", cards: cards, metadata: metadata});
  } catch(e) {
    return createJSONOutput({status: "error", message: e.toString()});
  }
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(30000);

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- DELETE ACTION ---
    if (data.type === 'delete' && data.id) {
        var sheets = ss.getSheets();
        var sheetToDelete = null;
        for (var i = 0; i < sheets.length; i++) {
            if (sheets[i].getSheetId().toString() === data.id) {
                sheetToDelete = sheets[i];
                break;
            }
        }
        if (sheetToDelete) {
            ss.deleteSheet(sheetToDelete);
            return createJSONOutput({status: "success", message: "Deleted"});
        } else {
            return createJSONOutput({status: "error", message: "Sheet not found"});
        }
    }

    // --- METADATA (Capa Global) ---
    if (data.type === 'metadata') {
       var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
       if (!metaSheet) {
         metaSheet = ss.insertSheet(METADATA_SHEET_NAME);
         metaSheet.appendRow(["Key", "Value"]);
       }

       var saveData = function(key, val) {
         var range = metaSheet.getDataRange();
         var values = range.getValues();
         for(var i=0; i<values.length; i++) {
           if(values[i][0].toString().toLowerCase() === key.toLowerCase()) {
             metaSheet.getRange(i+1, 2).setValue(val);
             return;
           }
         }
         metaSheet.appendRow([key, val]);
       };

       if (data.homeCoverPosition) saveData("home_cover_pos", data.homeCoverPosition);

       if (data.imageBase64) {
         var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Home_Cover_" + new Date().getTime());
         if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
         saveData("home_cover_image", uploadResult.url);
         data.image = uploadResult.url;
       }

       return createJSONOutput({status: "success", data: data});
    }

    // --- CARTÕES (Abas) ---
    var sheets = ss.getSheets();
    var targetSheet = null;

    if (data.id) {
      for (var i = 0; i < sheets.length; i++) {
        if (sheets[i].getSheetId().toString() === data.id) {
          targetSheet = sheets[i];
          break;
        }
      }
    }
    if (!targetSheet && data.title) targetSheet = ss.getSheetByName(data.title);

    // Criar Nova Aba se não existir
    if (!targetSheet) {
       var safeTitle = (data.title || "New Page " + new Date().getSeconds()).substring(0,50);
       try { targetSheet = ss.insertSheet(safeTitle); } 
       catch(e) { targetSheet = ss.insertSheet(safeTitle + Math.floor(Math.random()*100)); }

       targetSheet.getRange("A1:A8").setValues([["Title"], ["Image"], ["Icon"], ["ContentHTML"], ["FullWidth"], ["SmallText"], ["ParentID"], ["Order"]]);
    }

    // Salvar Dados
    if (data.title) targetSheet.getRange("B1").setValue(data.title);
    if (data.icon) targetSheet.getRange("B3").setValue(data.icon);
    if (data.content !== undefined) targetSheet.getRange("B4").setValue(data.content);
    if (data.fullWidth !== undefined) targetSheet.getRange("B5").setValue(data.fullWidth);
    if (data.smallText !== undefined) targetSheet.getRange("B6").setValue(data.smallText);
    if (data.parentId !== undefined) targetSheet.getRange("B7").setValue(data.parentId);
    if (data.order !== undefined) targetSheet.getRange("B8").setValue(data.order);

    // Upload da Imagem do Cartão
    if (data.imageBase64) {
      var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Card_" + targetSheet.getName() + "_" + new Date().getTime());
      if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
      targetSheet.getRange("B2").setValue(uploadResult.url);
      data.image = uploadResult.url;
    }

    // Atualizar nome da aba
    if (data.title && targetSheet.getName() !== data.title) {
        try { targetSheet.setName(data.title.substring(0, 50)); } catch(e) {}
    }

    data.id = targetSheet.getSheetId().toString();
    return createJSONOutput({status: "success", data: data});

  } catch (err) {
    return createJSONOutput({status: "error", message: err.toString()});
  } finally {
    lock.releaseLock();
  }
}

function uploadToDrive(base64Data, mimeType, fileName) {
  try {
    var folder;
    if (DRIVE_FOLDER_ID) {
      try { folder = DriveApp.getFolderById(DRIVE_FOLDER_ID); } catch(e) { folder = null; }
    }
    if (!folder) folder = DriveApp.getRootFolder();

    var cleanBase64 = base64Data;
    if (base64Data.indexOf("base64,") !== -1) {
      cleanBase64 = base64Data.split("base64,")[1];
    }

    var blob = Utilities.newBlob(Utilities.base64Decode(cleanBase64), mimeType || "image/jpeg", fileName);
    var file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    return { url: "https://lh3.googleusercontent.com/d/" + file.getId() };

  } catch(e) {
    return { error: e.toString() };
  }
}

function createJSONOutput(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}`;

import React, { useRef, useEffect, useState } from 'react';
import { 
  Bold, Italic, List, Heading1, Heading2, 
  Highlighter, Smile, Image as ImageIcon, Minus,
  Maximize, Minimize, Square, Circle, Type, Box, Trash2
} from 'lucide-react';

interface RichTextEditorProps {
  initialContent: string;
  onUpdate: (html: string) => void;
  readOnly?: boolean;
}

export const RichTextEditor: React.FC<RichTextEditorProps> = ({ initialContent, onUpdate, readOnly = false }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showHighlightMenu, setShowHighlightMenu] = useState(false);
  const [showEmojiMenu, setShowEmojiMenu] = useState(false);

  // Image Editing State
  const [selectedImage, setSelectedImage] = useState<HTMLElement | null>(null);

  // Initialize Content
  useEffect(() => {
    if (editorRef.current && initialContent) {
        if (editorRef.current.innerHTML !== initialContent) {
            editorRef.current.innerHTML = initialContent;
        }
    }
  }, [initialContent]);

  // --- Core Editor Functions ---

  const handleInput = () => {
    // If we delete the selected image, clear selection
    if (selectedImage && !document.contains(selectedImage)) {
        setSelectedImage(null);
    }
  };

  const handleBlur = (e: React.FocusEvent) => {
    // Don't save immediately if clicking toolbar to prevent race conditions
    if (e.relatedTarget && (e.relatedTarget as HTMLElement).closest('.editor-toolbar')) {
        return;
    }
    if (editorRef.current) {
      onUpdate(editorRef.current.innerHTML);
    }
  };

  // Detect selection of images
  const handleEditorClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;

    // Check if clicked on an image or inside a figure
    if (target.tagName === 'IMG') {
        setSelectedImage(target);
        setShowHighlightMenu(false);
        setShowEmojiMenu(false);
        e.stopPropagation(); // Prevent deselecting immediately
    } else if (target.closest('figure')) {
        if (target.tagName === 'FIGCAPTION') {
             setSelectedImage(null);
        } else {
            const img = target.closest('figure')?.querySelector('img');
            if (img) setSelectedImage(img as HTMLElement);
        }
    } else {
        setSelectedImage(null);
    }
  };

  const exec = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    editorRef.current?.focus();
    setShowHighlightMenu(false);
    setShowEmojiMenu(false);
  };

  const insertEmoji = (emoji: string) => {
    exec('insertText', emoji);
  };

  // --- Image Handling ---

  const handleImageClick = () => {
    fileInputRef.current?.click();
  };

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            const base64 = e.target?.result as string;
            insertImageBlock(base64);
        };
        reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const insertImageBlock = (src: string) => {
    if (!editorRef.current) return;
    editorRef.current.focus();

    const id = Date.now();
    // Simplified structure
    const html = `
        <figure class="image-block w-full max-w-full my-4 group relative select-none">
            <div class="image-wrapper relative w-full flex justify-center">
                <img src="${src}" class="rounded-md shadow-sm transition-all duration-200" style="width: 100%;" data-id="${id}" />
            </div>
            <figcaption class="text-center text-notion-muted text-sm mt-2 outline-none border-none empty:before:content-['Adicionar_legenda...'] cursor-text" contenteditable="true"></figcaption>
        </figure>
        <p><br/></p>
    `;

    document.execCommand('insertHTML', false, html);
    onUpdate(editorRef.current.innerHTML);
  };

  // --- Image Styling Actions ---
  const updateImageStyle = (e: React.MouseEvent, action: 'size' | 'rounded' | 'border' | 'frame' | 'delete', value?: string) => {
    e.preventDefault(); // CRITICAL: Prevents focus loss
    if (!selectedImage || selectedImage.tagName !== 'IMG') return;

    const img = selectedImage as HTMLImageElement;
    const figure = img.closest('figure');

    if (!figure) return;

    switch (action) {
        case 'delete':
            figure.remove();
            setSelectedImage(null);
            break;
        case 'size':
            img.style.width = value || '100%';
            break;
        case 'rounded':
             if (img.classList.contains('rounded-xl')) {
                 img.classList.remove('rounded-xl');
                 img.classList.add('rounded-md'); 
             } else {
                 img.classList.remove('rounded-md', 'rounded-full');
                 img.classList.add('rounded-xl');
             }
             break;
        case 'border':
             if (img.style.border === '4px solid rgba(255, 255, 255, 0.2)') {
                 img.style.border = '';
             } else {
                 img.style.border = '4px solid rgba(255, 255, 255, 0.2)';
             }
             break;
        case 'frame':
             if (figure.classList.contains('bg-white/5')) {
                 figure.classList.remove('border', 'border-white/10', 'bg-white/5', 'rounded-xl', 'p-4');
             } else {
                 figure.classList.add('border', 'border-white/10', 'bg-white/5', 'rounded-xl', 'p-4');
             }
             break;
    }

    // Force update
    if (editorRef.current) {
        onUpdate(editorRef.current.innerHTML);
        if (action !== 'delete') {
            setSelectedImage(img); 
        }
    }
  };


  // Colors
  const highlights = [
    { label: 'Padrão', color: 'transparent', icon: '🚫' },
    { label: 'Cinza', color: 'rgba(255, 255, 255, 0.15)', icon: '⚪' },
    { label: 'Marrom', color: 'rgba(68, 42, 30, 0.6)', icon: '🟤' },
    { label: 'Laranja', color: 'rgba(217, 115, 13, 0.3)', icon: '🟠' },
    { label: 'Amarelo', color: 'rgba(202, 138, 4, 0.3)', icon: '🟡' },
    { label: 'Verde', color: 'rgba(22, 163, 74, 0.3)', icon: '🟢' },
    { label: 'Azul', color: 'rgba(37, 99, 235, 0.3)', icon: '🔵' },
    { label: 'Vermelho', color: 'rgba(220, 38, 38, 0.3)', icon: '🔴' },
  ];

  const emojis = ['🌐', '🍽️', '🍕', '🥞', '🥩', '🕒', '📅', '📍', '🏊', '🍸'];

  return (
    <div className="relative group/editor">
      <style>{`
        .editor-content h1 { font-size: 1.875rem; font-weight: 700; margin-top: 1.5em; margin-bottom: 0.5em; line-height: 1.2; }
        .editor-content h2 { font-size: 1.5rem; font-weight: 600; margin-top: 1.2em; margin-bottom: 0.5em; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 4px; }
        .editor-content ul { list-style-type: disc; padding-left: 1.5em; margin-bottom: 1em; }
        .editor-content ol { list-style-type: decimal; padding-left: 1.5em; margin-bottom: 1em; }
        .editor-content li { margin-bottom: 0.25em; padding-left: 0.2em; }
        .editor-content p { margin-bottom: 0.75em; min-height: 1.5em; }
        .editor-content b, .editor-content strong { font-weight: 700; color: #fff; }
        .editor-content hr { border-color: rgba(255,255,255,0.1); margin: 1.5em 0; }
        .editor-content img { transition: all 0.2s; display: block; }
        .editor-content figure.image-block { margin: 1.5rem 0; display: block; }
        .editor-content figcaption { color: #9b9b9b; text-align: center; margin-top: 0.5rem; font-size: 0.875rem; }
        .editor-content span[style*="background-color"] { padding: 2px 4px; border-radius: 4px; color: #fff; }

        /* Selection Outline for Image */
        .editor-content img.selected-img { outline: 3px solid #2383e2; box-shadow: 0 0 0 4px rgba(35, 131, 226, 0.3); }
      `}</style>

      {/* Hidden File Input for Image Block */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        className="hidden" 
      />

      {/* --- Main Text Toolbar --- */}
      {!readOnly && !selectedImage && (
        <div className="editor-toolbar sticky top-11 z-40 mb-4 bg-[#252525] border border-white/10 rounded-lg p-1 flex items-center gap-1 w-fit shadow-xl opacity-0 group-hover/editor:opacity-100 focus-within:opacity-100 transition-opacity">

          <button onMouseDown={(e) => { e.preventDefault(); exec('formatBlock', 'H1'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 1">
            <Heading1 size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); exec('formatBlock', 'H2'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 2">
            <Heading2 size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          <button onMouseDown={(e) => { e.preventDefault(); exec('bold'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Negrito">
            <Bold size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); exec('italic'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Itálico">
            <Italic size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); exec('insertUnorderedList'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Lista">
            <List size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          <button onMouseDown={(e) => { e.preventDefault(); exec('insertHorizontalRule'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Divisor">
            <Minus size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); handleImageClick(); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Inserir Imagem">
            <ImageIcon size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          {/* Highlight Dropdown */}
          <div className="relative">
            <button 
                onMouseDown={(e) => { e.preventDefault(); setShowHighlightMenu(!showHighlightMenu); setShowEmojiMenu(false); }}
                className={`p-1.5 hover:bg-white/10 rounded transition-colors flex items-center gap-1 ${showHighlightMenu ? 'bg-white/20 text-white' : 'text-notion-muted hover:text-white'}`} 
                title="Cor de Fundo"
            >
                <Highlighter size={16} />
            </button>
            {showHighlightMenu && (
                <div className="absolute top-full left-0 mt-2 bg-[#252525] border border-white/10 rounded shadow-xl p-1 grid grid-cols-4 gap-1 w-32 z-50">
                    {highlights.map((h) => (
                        <button
                            key={h.label}
                            onMouseDown={(e) => { e.preventDefault(); exec('hiliteColor', h.color); }}
                            className="w-6 h-6 rounded hover:scale-110 transition-transform flex items-center justify-center border border-white/5"
                            style={{ backgroundColor: h.color === 'transparent' ? '#333' : h.color }}
                            title={h.label}
                        >
                            {h.color === 'transparent' ? <div className="w-full h-px bg-red-400 rotate-45" /> : null}
                        </button>
                    ))}
                </div>
            )}
          </div>

          {/* Emoji Dropdown */}
          <div className="relative">
            <button 
                onMouseDown={(e) => { e.preventDefault(); setShowEmojiMenu(!showEmojiMenu); setShowHighlightMenu(false); }}
                className={`p-1.5 hover:bg-white/10 rounded transition-colors ${showEmojiMenu ? 'bg-white/20 text-white' : 'text-notion-muted hover:text-white'}`} 
                title="Inserir Ícone"
            >
                <Smile size={16} />
            </button>
            {showEmojiMenu && (
                <div className="absolute top-full left-0 mt-2 bg-[#252525] border border-white/10 rounded shadow-xl p-2 grid grid-cols-5 gap-1 w-40 z-50">
                    {emojis.map((emoji) => (
                        <button
                            key={emoji}
                            onMouseDown={(e) => { e.preventDefault(); insertEmoji(emoji); }}
                            className="text-lg hover:bg-white/10 rounded p-1 transition-colors"
                        >
                            {emoji}
                        </button>
                    ))}
                </div>
            )}
          </div>

        </div>
      )}

      {/* --- Image Context Toolbar --- */}
      {!readOnly && selectedImage && (
        <div className="editor-toolbar sticky top-11 z-50 mb-4 bg-notion-blue text-white rounded-full px-3 py-1.5 flex items-center gap-3 w-fit shadow-2xl animate-in fade-in slide-in-from-bottom-2 mx-auto select-none">

            <div className="flex items-center gap-1 border-r border-white/20 pr-2">
                <button onMouseDown={(e) => updateImageStyle(e, 'size', '30%')} className="p-1 hover:bg-white/20 rounded" title="Pequeno"><Minimize size={14}/></button>
                <button onMouseDown={(e) => updateImageStyle(e, 'size', '60%')} className="p-1 hover:bg-white/20 rounded" title="Médio"><Box size={14}/></button>
                <button onMouseDown={(e) => updateImageStyle(e, 'size', '100%')} className="p-1 hover:bg-white/20 rounded" title="Cheio"><Maximize size={14}/></button>
            </div>

            <div className="flex items-center gap-1 border-r border-white/20 pr-2">
                 <button onMouseDown={(e) => updateImageStyle(e, 'rounded')} className="p-1 hover:bg-white/20 rounded" title="Arredondar"><Circle size={14}/></button>
                 <button onMouseDown={(e) => updateImageStyle(e, 'border')} className="p-1 hover:bg-white/20 rounded" title="Borda"><Square size={14}/></button>
                 <button onMouseDown={(e) => updateImageStyle(e, 'frame')} className="p-1 hover:bg-white/20 rounded" title="Moldura"><Type size={14}/></button>
            </div>

            <button onMouseDown={(e) => updateImageStyle(e, 'delete')} className="p-1 hover:bg-red-500/50 rounded text-red-100 transition-colors" title="Excluir"><Trash2 size={16}/></button>

            <button onMouseDown={(e) => { e.preventDefault(); setSelectedImage(null); }} className="text-xs font-bold hover:underline ml-1">OK</button>
        </div>
      )}

      {/* Editable Area */}
      <div
        ref={editorRef}
        contentEditable={!readOnly}
        onInput={handleInput}
        onBlur={handleBlur}
