        spellCheck={false}
      />
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { DashboardCard } from '../types';
import { MoreHorizontal, Trash2, ArrowLeft, ArrowRight } from 'lucide-react';

interface CardProps {
  card: DashboardCard;
  onClick: (card: DashboardCard) => void;
  onDrop?: (draggedId: string, targetId: string) => void;
  onDelete?: (cardId: string) => void;
  onReorder?: (cardId: string, direction: 'left' | 'right') => void;
}

export const Card: React.FC<CardProps> = ({ card, onClick, onDrop, onDelete, onReorder }) => {
  const Icon = card.icon;
  const [showMenu, setShowMenu] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setShowMenu(false);
      }
    };
    if (showMenu) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showMenu]);

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('cardId', card.id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); 
    e.currentTarget.classList.add('ring-2', 'ring-notion-blue', 'bg-notion-hover');
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.currentTarget.classList.remove('ring-2', 'ring-notion-blue', 'bg-notion-hover');
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.currentTarget.classList.remove('ring-2', 'ring-notion-blue', 'bg-notion-hover');

    const draggedId = e.dataTransfer.getData('cardId');
    if (draggedId && draggedId !== card.id && onDrop) {
        onDrop(draggedId, card.id);
    }
  };

  const handleMenuClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowMenu(!showMenu);
  };

  const handleDeleteClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setShowMenu(false);
    if (onDelete) onDelete(card.id);
  };

  const handleReorderClick = (e: React.MouseEvent, direction: 'left' | 'right') => {
    e.stopPropagation();
    if (onReorder) onReorder(card.id, direction);
  };

  return (
    <div 
      draggable={!!onDrop}
      onDragStart={handleDragStart}
      onDragOver={onDrop ? handleDragOver : undefined}
      onDragLeave={onDrop ? handleDragLeave : undefined}
      onDrop={onDrop ? handleDrop : undefined}
      onClick={() => onClick(card)}
      className={`group relative flex flex-col rounded-xl bg-notion-card hover:bg-notion-hover transition-colors cursor-pointer border border-transparent hover:border-white/5 shadow-sm hover:shadow-lg select-none ${showMenu ? 'z-50' : 'z-auto'}`}
    >
      {/* Menu Trigger */}
      {(onDelete || onReorder) && (
        <div className={`absolute top-2 right-2 z-20 ${showMenu ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'} transition-opacity`}>
            <button 
                onClick={handleMenuClick}
                className="p-1 bg-black/60 hover:bg-black/80 text-white rounded backdrop-blur-sm shadow-sm"
            >
                <MoreHorizontal size={16} />
            </button>

            {showMenu && (
                <div 
                    ref={menuRef}
                    className="absolute right-0 top-8 w-48 bg-[#252525] border border-white/10 rounded-lg shadow-xl py-1 z-50 animate-in fade-in zoom-in-95 duration-100 overflow-hidden"
                    onClick={(e) => e.stopPropagation()} 
                >
                    {onReorder && (
                        <div className="flex border-b border-white/5 mb-1">
                            <button 
                                onClick={(e) => handleReorderClick(e, 'left')}
                                className="flex-1 px-3 py-2 text-sm text-notion-text hover:bg-white/5 flex items-center justify-center gap-1"
                                title="Mover para esquerda/cima"
                            >
                                <ArrowLeft size={14} />
                            </button>
                            <div className="w-px bg-white/5"></div>
                            <button 
                                onClick={(e) => handleReorderClick(e, 'right')}
                                className="flex-1 px-3 py-2 text-sm text-notion-text hover:bg-white/5 flex items-center justify-center gap-1"
                                title="Mover para direita/baixo"
                            >
                                <ArrowRight size={14} />
                            </button>
                        </div>
                    )}

                    {onDelete && (
                        <button 
                            onClick={handleDeleteClick}
                            className="w-full text-left px-3 py-2 text-sm text-red-400 hover:bg-white/5 flex items-center gap-2"
                        >
                            <Trash2 size={14} />
                            Excluir
                        </button>
                    )}
                </div>
            )}
        </div>
      )}

      {/* Image Area - Added rounded-t-xl to ensure corners match card, and overflow-hidden to contain zoom */}
      <div className="h-32 w-full overflow-hidden relative pointer-events-none rounded-t-xl">
        <img 
          src={card.image} 
          alt={card.title} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
        />
        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-colors" />
      </div>

      {/* Content Area */}
      <div className="p-3 flex items-center gap-3 pointer-events-none rounded-b-xl">
        <div className="flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-lg bg-white/5 text-notion-text border border-white/5 shadow-sm">
          <Icon size={18} />
        </div>
        <span className="text-sm font-medium text-notion-text truncate w-full border-b border-transparent group-hover:border-notion-muted/50 pb-0.5 transition-all">
          {card.title}
        </span>
      </div>
    </div>
  );
};

