    if (file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            const base64 = e.target?.result as string;
            insertImageBlock(base64);
        };
        reader.readAsDataURL(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const insertImageBlock = (src: string) => {
    if (!editorRef.current) return;
    editorRef.current.focus();

    const id = Date.now();
    // Simplified structure
    const html = `
        <figure class="image-block w-full max-w-full my-4 group relative select-none">
            <div class="image-wrapper relative w-full flex justify-center">
                <img src="${src}" class="rounded-md shadow-sm transition-all duration-200" style="width: 100%;" data-id="${id}" />
            </div>
            <figcaption class="text-center text-notion-muted text-sm mt-2 outline-none border-none empty:before:content-['Adicionar_legenda...'] cursor-text" contenteditable="true"></figcaption>
        </figure>
        <p><br/></p>
    `;

    document.execCommand('insertHTML', false, html);
    onUpdate(editorRef.current.innerHTML);
  };

  // --- Image Styling Actions ---
  const updateImageStyle = (e: React.MouseEvent, action: 'size' | 'rounded' | 'border' | 'frame' | 'delete', value?: string) => {
    e.preventDefault(); // CRITICAL: Prevents focus loss
    if (!selectedImage || selectedImage.tagName !== 'IMG') return;

    const img = selectedImage as HTMLImageElement;
    const figure = img.closest('figure');

    if (action === 'delete') {
         if (figure) {
             figure.remove();
         } else {
             img.remove();
         }
         setSelectedImage(null);
    } else if (figure) {
        switch (action) {
            case 'size':
                img.style.width = value || '100%';
                break;
            case 'rounded':
                 if (img.classList.contains('rounded-xl')) {
                     img.classList.remove('rounded-xl');
                     img.classList.add('rounded-md'); 
                 } else {
                     img.classList.remove('rounded-md', 'rounded-full');
                     img.classList.add('rounded-xl');
                 }
                 break;
            case 'border':
                 if (img.style.border === '4px solid rgba(255, 255, 255, 0.2)') {
                     img.style.border = '';
                 } else {
                     img.style.border = '4px solid rgba(255, 255, 255, 0.2)';
                 }
                 break;
            case 'frame':
                 if (figure.classList.contains('bg-white/5')) {
                     figure.classList.remove('border', 'border-white/10', 'bg-white/5', 'rounded-xl', 'p-4');
                 } else {
                     figure.classList.add('border', 'border-white/10', 'bg-white/5', 'rounded-xl', 'p-4');
                 }
                 break;
        }
    }

    // Force update
    if (editorRef.current) {
        onUpdate(editorRef.current.innerHTML);
        if (action !== 'delete') {
            setSelectedImage(img); 
        }
    }
  };


  // Colors
  const highlights = [
    { label: 'Padrão', color: 'transparent', icon: '🚫' },
    { label: 'Cinza', color: 'rgba(255, 255, 255, 0.15)', icon: '⚪' },
    { label: 'Marrom', color: 'rgba(68, 42, 30, 0.6)', icon: '🟤' },
    { label: 'Laranja', color: 'rgba(217, 115, 13, 0.3)', icon: '🟠' },
    { label: 'Amarelo', color: 'rgba(202, 138, 4, 0.3)', icon: '🟡' },
    { label: 'Verde', color: 'rgba(22, 163, 74, 0.3)', icon: '🟢' },
    { label: 'Azul', color: 'rgba(37, 99, 235, 0.3)', icon: '🔵' },
    { label: 'Vermelho', color: 'rgba(220, 38, 38, 0.3)', icon: '🔴' },
  ];

  const emojis = ['🌐', '🍽️', '🍕', '🥞', '🥩', '🕒', '📅', '📍', '🏊', '🍸'];

  return (
    <div className="relative group/editor">
      <style>{`
        .editor-content h1 { font-size: 1.875rem; font-weight: 700; margin-top: 1.5em; margin-bottom: 0.5em; line-height: 1.2; }
        .editor-content h2 { font-size: 1.5rem; font-weight: 600; margin-top: 1.2em; margin-bottom: 0.5em; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 4px; }
        .editor-content ul { list-style-type: disc; padding-left: 1.5em; margin-bottom: 1em; }
        .editor-content ol { list-style-type: decimal; padding-left: 1.5em; margin-bottom: 1em; }
        .editor-content li { margin-bottom: 0.25em; padding-left: 0.2em; }
        .editor-content p { margin-bottom: 0.75em; min-height: 1.5em; }
        .editor-content b, .editor-content strong { font-weight: 700; color: #fff; }
        .editor-content hr { border-color: rgba(255,255,255,0.1); margin: 1.5em 0; }
        .editor-content img { transition: all 0.2s; display: block; }
        .editor-content figure.image-block { margin: 1.5rem 0; display: block; }
        .editor-content figcaption { color: #9b9b9b; text-align: center; margin-top: 0.5rem; font-size: 0.875rem; }
        .editor-content span[style*="background-color"] { padding: 2px 4px; border-radius: 4px; color: #fff; }

        /* Selection Outline for Image */
        .editor-content img.selected-img { outline: 3px solid #2383e2; box-shadow: 0 0 0 4px rgba(35, 131, 226, 0.3); }
      `}</style>

      {/* Hidden File Input for Image Block */}
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        className="hidden" 
      />

      {/* --- Main Text Toolbar --- */}
      {!readOnly && !selectedImage && (
        <div className="editor-toolbar sticky top-11 z-40 mb-4 bg-[#252525] border border-white/10 rounded-lg p-1 flex items-center gap-1 w-fit shadow-xl opacity-0 group-hover/editor:opacity-100 focus-within:opacity-100 transition-opacity">

          <button onMouseDown={(e) => { e.preventDefault(); exec('formatBlock', 'H1'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 1">
            <Heading1 size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); exec('formatBlock', 'H2'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Título 2">
            <Heading2 size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          <button onMouseDown={(e) => { e.preventDefault(); exec('bold'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Negrito">
            <Bold size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); exec('italic'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Itálico">
            <Italic size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); exec('insertUnorderedList'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Lista">
            <List size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          <button onMouseDown={(e) => { e.preventDefault(); exec('insertHorizontalRule'); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Divisor">
            <Minus size={16} />
          </button>
          <button onMouseDown={(e) => { e.preventDefault(); handleImageClick(); }} className="p-1.5 hover:bg-white/10 rounded text-notion-muted hover:text-white transition-colors" title="Inserir Imagem">
            <ImageIcon size={16} />
          </button>

          <div className="w-px h-4 bg-white/10 mx-1" />

          {/* Highlight Dropdown */}
          <div className="relative">
            <button 
                onMouseDown={(e) => { e.preventDefault(); setShowHighlightMenu(!showHighlightMenu); setShowEmojiMenu(false); }}
                className={`p-1.5 hover:bg-white/10 rounded transition-colors flex items-center gap-1 ${showHighlightMenu ? 'bg-white/20 text-white' : 'text-notion-muted hover:text-white'}`} 
                title="Cor de Fundo"
            >
                <Highlighter size={16} />
            </button>
            {showHighlightMenu && (
                <div className="absolute top-full left-0 mt-2 bg-[#252525] border border-white/10 rounded shadow-xl p-1 grid grid-cols-4 gap-1 w-32 z-50">
                    {highlights.map((h) => (
                        <button
                            key={h.label}
                            onMouseDown={(e) => { e.preventDefault(); exec('hiliteColor', h.color); }}
                            className="w-6 h-6 rounded hover:scale-110 transition-transform flex items-center justify-center border border-white/5"
                            style={{ backgroundColor: h.color === 'transparent' ? '#333' : h.color }}
                            title={h.label}
                        >
                            {h.color === 'transparent' ? <div className="w-full h-px bg-red-400 rotate-45" /> : null}
                        </button>
                    ))}
                </div>
            )}
          </div>

          {/* Emoji Dropdown */}
          <div className="relative">
            <button 
                onMouseDown={(e) => { e.preventDefault(); setShowEmojiMenu(!showEmojiMenu); setShowHighlightMenu(false); }}
                className={`p-1.5 hover:bg-white/10 rounded transition-colors ${showEmojiMenu ? 'bg-white/20 text-white' : 'text-notion-muted hover:text-white'}`} 
                title="Inserir Ícone"
            >
                <Smile size={16} />
            </button>
            {showEmojiMenu && (
                <div className="absolute top-full left-0 mt-2 bg-[#252525] border border-white/10 rounded shadow-xl p-2 grid grid-cols-5 gap-1 w-40 z-50">
                    {emojis.map((emoji) => (
                        <button
                            key={emoji}
                            onMouseDown={(e) => { e.preventDefault(); insertEmoji(emoji); }}
                            className="text-lg hover:bg-white/10 rounded p-1 transition-colors"
                        >
                            {emoji}
                        </button>
                    ))}
                </div>
            )}
          </div>

        </div>
      )}

      {/* --- Image Context Toolbar --- */}
      {!readOnly && selectedImage && (
        <div className="editor-toolbar sticky top-11 z-50 mb-4 bg-notion-blue text-white rounded-full px-3 py-1.5 flex items-center gap-3 w-fit shadow-2xl animate-in fade-in slide-in-from-bottom-2 mx-auto select-none">

            <div className="flex items-center gap-1 border-r border-white/20 pr-2">
                <button onMouseDown={(e) => updateImageStyle(e, 'size', '30%')} className="p-1 hover:bg-white/20 rounded" title="Pequeno"><Minimize size={14}/></button>
                <button onMouseDown={(e) => updateImageStyle(e, 'size', '60%')} className="p-1 hover:bg-white/20 rounded" title="Médio"><Box size={14}/></button>
                <button onMouseDown={(e) => updateImageStyle(e, 'size', '100%')} className="p-1 hover:bg-white/20 rounded" title="Cheio"><Maximize size={14}/></button>
            </div>

            <div className="flex items-center gap-1 border-r border-white/20 pr-2">
                 <button onMouseDown={(e) => updateImageStyle(e, 'rounded')} className="p-1 hover:bg-white/20 rounded" title="Arredondar"><Circle size={14}/></button>
                 <button onMouseDown={(e) => updateImageStyle(e, 'border')} className="p-1 hover:bg-white/20 rounded" title="Borda"><Square size={14}/></button>
                 <button onMouseDown={(e) => updateImageStyle(e, 'frame')} className="p-1 hover:bg-white/20 rounded" title="Moldura"><Type size={14}/></button>
            </div>

            <button onMouseDown={(e) => updateImageStyle(e, 'delete')} className="p-1 hover:bg-red-500/50 rounded text-red-100 transition-colors" title="Excluir"><Trash2 size={16}/></button>

            <button onMouseDown={(e) => { e.preventDefault(); setSelectedImage(null); }} className="text-xs font-bold hover:underline ml-1">OK</button>
        </div>
      )}

      {/* Editable Area */}
      <div
        ref={editorRef}
        contentEditable={!readOnly}
        onInput={handleInput}
        onBlur={handleBlur}
        onClick={handleEditorClick}
        className={`editor-content w-full min-h-[60px] outline-none text-notion-text empty:before:content-['Clique_para_editar...'] empty:before:text-notion-muted/50 ${readOnly ? '' : 'cursor-text'}`}
        spellCheck={false}
      />
    </div>
  );
};

import { LucideIcon } from 'lucide-react';
import React from 'react';

export interface DashboardCard {
  id: string;
  title: string;
  image: string;
  icon: LucideIcon | string; // Pode ser o componente ou o nome da string vinda da API
  iconName?: string;
  content?: React.ReactNode | string; // Conteúdo interno do bloco

  // Hierarchy
  parentId?: string; // ID da página pai (se vazio, é página inicial)

  // Layout preferences
  fullWidth?: boolean;
  smallText?: boolean;

  // Ordering
  order?: number;

  // Sync State
  _isUnsynced?: boolean; // Se true, esta versão local é mais recente que o servidor
}

export interface NavItem {
  label: string;
  href: string;
}

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE, API_URL } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCardId, setActiveCardId] = useState<string | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Derived state for active card to ensure single source of truth
  const activeCard = activeCardId ? cards.find(c => c.id === activeCardId) || null : null;

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards && Array.isArray(parsed.cards)) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle
                }));
                // Sort by order
                rehydrated.sort((a: DashboardCard, b: DashboardCard) => (a.order || 0) - (b.order || 0));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                const img = parsed.metadata.home_cover_image || parsed.metadata.Home_Cover_Image;
                const pos = parsed.metadata.home_cover_pos || parsed.metadata.Home_Cover_Pos;
                if (img) setHomeCover(img);
                if (pos) setHomeCoverPos(Number(pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }

    // Auto-Sync on Mount
    handleSync();
  }, []);

  // Navigation Logic
  const handleBackToHome = () => {
    setActiveCardId(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleNavigateToCard = (card: DashboardCard) => {
    setActiveCardId(card.id);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleBreadcrumbClick = (targetCard: DashboardCard) => {
    setActiveCardId(targetCard.id);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Helper to build Breadcrumbs path from activeCard up to root
  const getBreadcrumbs = () => {
    if (!activeCard) return undefined;

    const path: { label: string; onClick?: () => void }[] = [];

    // Add Home
    path.push({ label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome });

    // Build hierarchy recursively
    const hierarchy: DashboardCard[] = [];
    let current: DashboardCard | undefined = activeCard;

    while (current) {
        hierarchy.unshift(current); // Add to front
        if (current.parentId) {
            // Loose comparison for robustness (string vs number)
            current = cards.find(c => c.id == current?.parentId);
        } else {
            current = undefined;
        }
    }

    hierarchy.forEach((c, index) => {
        const isLast = index === hierarchy.length - 1;
        path.push({
            label: c.title,
            onClick: isLast ? undefined : () => handleBreadcrumbClick(c)
        });
    });

    return path;
  };

  const handleCreateNewCard = (parentId?: string) => {
    const newId = Date.now().toString(); 
    const safeParentId = typeof parentId === 'string' ? parentId : undefined;

    // Determine new order (at end of list)
    const siblings = cards.filter(c => c.parentId == safeParentId);
    const maxOrder = siblings.reduce((max, c) => Math.max(max, c.order || 0), 0);

    const newCard: DashboardCard = {
        id: newId,
        title: 'Nova Página',
        image: 'https://picsum.photos/seed/' + newId + '/600/300',
        icon: LucideIcons.FileText,
        iconName: 'FileText',
        content: '<p>Comece a escrever aqui...</p>',
        fullWidth: false,
        smallText: false,
        parentId: safeParentId,
        order: maxOrder + 1,
        _isUnsynced: true // Mark as needing sync
    };

    // Optimistically add to state
    const updatedCards = [...cards, newCard];
    setCards(updatedCards);
    setActiveCardId(newId); // Navigate to new card
    window.scrollTo({ top: 0, behavior: 'auto' });
    saveToLocalCache(updatedCards);

    // Sync
    handleUpdateCard(newCard, true);
  };

  // --- Deletion Logic ---
  const handleDeleteCard = async (cardId: string) => {
    if (!window.confirm("Tem certeza que deseja excluir esta página e todo o conteúdo dela?")) return;

    // Optimistic UI Update
    const updatedCards = cards.filter(c => c.id !== cardId && c.parentId !== cardId); 
    setCards(updatedCards);
    saveToLocalCache(updatedCards);

    // If active card was deleted, go home
    if (activeCard && activeCard.id === cardId) {
        handleBackToHome();
    }

    try {
        const payload = {
            type: 'delete',
            id: cardId
        };
        await fetch(API_URL, { method: 'POST', body: JSON.stringify(payload) });
    } catch (e) {
        console.error("Delete failed on server", e);
        alert("Erro ao excluir no servidor. A alteração local foi mantida.");
    }
  };

  // --- Reorder Logic ---
  const handleReorderCard = async (cardId: string, direction: 'left' | 'right') => {
    const card = cards.find(c => c.id === cardId);
    if (!card) return;

    const siblings = cards
        .filter(c => c.parentId === card.parentId)
        .sort((a, b) => (a.order || 0) - (b.order || 0));

    const currentIndex = siblings.findIndex(c => c.id === cardId);
    if (currentIndex === -1) return;

    const targetIndex = direction === 'left' ? currentIndex - 1 : currentIndex + 1;

    if (targetIndex >= 0 && targetIndex < siblings.length) {
        const swapCard = siblings[targetIndex];

        // Swap orders
        const cardOrder = card.order || 0;
        const swapOrder = swapCard.order || 0;

        // Handling equal orders case
        if (cardOrder === swapOrder) {
             siblings.forEach((c, idx) => c.order = idx);
             card.order = currentIndex;
             swapCard.order = targetIndex;
             const temp = card.order;
             card.order = swapCard.order;
             swapCard.order = temp;
        } else {
             const temp = card.order;
             card.order = swapCard.order;
             swapCard.order = temp;
        }

        const updatedCards = [...cards]; 
        updatedCards.sort((a, b) => (a.order || 0) - (b.order || 0));

        setCards(updatedCards);
        saveToLocalCache(updatedCards);

        await handleUpdateCard(card);
        await handleUpdateCard(swapCard);
    }
  };

  // --- Move/Nest Logic (Drag and Drop) ---
  const handleMoveCard = async (draggedId: string, targetParentId?: string) => {
    if (draggedId === targetParentId) return;

    console.log(`Moving ${draggedId} to ${targetParentId || 'root'}`);

    const cardToMove = cards.find(c => c.id === draggedId);
    if (!cardToMove) return;

    const newSiblings = cards.filter(c => c.parentId == targetParentId);
    const maxOrder = newSiblings.reduce((max, c) => Math.max(max, c.order || 0), 0);

    const updatedCard = { 
        ...cardToMove, 
        parentId: targetParentId, 
        order: maxOrder + 1,
        _isUnsynced: true 
    };

    const updatedList = cards.map(c => c.id === draggedId ? updatedCard : c);
    updatedList.sort((a, b) => (a.order || 0) - (b.order || 0));

    setCards(updatedList);
    saveToLocalCache(updatedList);

    if (activeCard && activeCard.id === draggedId) {
        // Active card state updates automatically via activeCardId
    }

    // Server Sync
    handleUpdateCard(updatedCard);
  };

  const handleSync = async () => {
    try {
        const response = await fetch(API_URL);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();
        console.log("Sync Result:", result); 

        const serverCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id ? item.id.toString() : Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText,
                parentId: item.parentId ? item.parentId.toString() : undefined,
                order: Number(item.order) || 0,
                _isUnsynced: false // Server items are synced by definition
            };
        });

        // MERGE LOGIC: Prefer local "unsynced" items over server items
        setCards(currentCards => {
            const mergedCards = [...serverCards];

            // Re-apply local changes that haven't hit the server yet
            currentCards.forEach(localCard => {
                if (localCard._isUnsynced) {
                    const serverIndex = mergedCards.findIndex(c => c.id === localCard.id);
                    if (serverIndex !== -1) {
                        // Conflict: Keep local because it's newer/dirty
                        mergedCards[serverIndex] = localCard;
                    } else {
                        // New local card not on server yet: Keep it
                        mergedCards.push(localCard);
                    }
                }
            });

            mergedCards.sort((a, b) => (a.order || 0) - (b.order || 0));
            saveToLocalCache(mergedCards, result.metadata);
            return mergedCards;
        });

        if (result.metadata) {
            const img = result.metadata['home_cover_image'] || result.metadata['Home_Cover_Image'];
            const pos = result.metadata['home_cover_pos'] || result.metadata['Home_Cover_Pos'];
            if (img) setHomeCover(img);
            if (pos) setHomeCoverPos(Number(pos));
        }

    } catch (error) {
        console.error("Sync failed:", error);
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        if (result.status === 'success' && result.data.image && result.data.image.startsWith('http')) {
            setHomeCover(result.data.image);
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string } | DashboardCard, isNew = false) => {

    // Determine the card to update
    const targetCardId = (updatedFields as any).id || activeCardId;
    const targetCard = isNew ? (updatedFields as DashboardCard) : cards.find(c => c.id === targetCardId);

    if (!targetCard) return;

    const updatedCardFull: DashboardCard = { 
        ...targetCard, 
        ...updatedFields,
        icon: (updatedFields as any).iconName ? (LucideIcons as any)[(updatedFields as any).iconName] : (updatedFields.icon || targetCard.icon),
        _isUnsynced: true // MARK AS DIRTY
    };

    // Update Local State Immediately
    setCards(prev => {
        const newCards = prev.map(c => c.id === targetCard.id ? updatedCardFull : c);
        if (isNew && !prev.find(c => c.id === targetCard.id)) {
            newCards.push(updatedCardFull);
        }
        newCards.sort((a, b) => (a.order || 0) - (b.order || 0));
        saveToLocalCache(newCards);
        return newCards;
    });

    try {
        const payload = {
            id: targetCard.id,
            title: updatedFields.title || targetCard.title,
            icon: (updatedFields as any).iconName || (targetCard as any).iconName || 'HelpCircle',
            content: updatedFields.content !== undefined ? updatedFields.content : targetCard.content,
            imageBase64: (updatedFields as any).imageBase64, 
            mimeType: (updatedFields as any).mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText,
            // CRITICAL FIX: Send "" if undefined so backend clears the cell
            parentId: updatedCardFull.parentId === undefined ? "" : updatedCardFull.parentId, 
            order: updatedCardFull.order 
        };

        const response = await fetch(API_URL, { 
            method: 'POST', 
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        if (result.status === 'success' && result.data) {
            // Success: Update state to remove dirty flag and set image URL if needed
            setCards(prev => {
                const finalCards = prev.map(c => {
                    if (c.id === targetCard.id) {
                        return {
                            ...c,
                            _isUnsynced: false, // Clean
                            image: (result.data.image && result.data.image.startsWith('http')) ? result.data.image : c.image
                        };
                    }
                    return c;
                });
                saveToLocalCache(finalCards);
                return finalCards;
            });
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
        // Leave _isUnsynced = true so next handleSync prefers this version
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = getBreadcrumbs();

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                key={activeCard.id} 
                card={activeCard} 
                allCards={cards} 
                onUpdateCard={handleUpdateCard} 
                onNavigateToCard={handleNavigateToCard}
                onCreateSubPage={handleCreateNewCard}
                onDeleteCard={handleDeleteCard} 
                onMoveCard={handleMoveCard}
                onReorderCard={handleReorderCard} 
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards.filter(c => !c.parentId)} 
                    onCardClick={handleNavigateToCard} 
                    onNewCard={() => handleCreateNewCard()}
                    onMoveCard={handleMoveCard}
                    onDeleteCard={handleDeleteCard} 
                    onReorderCard={handleReorderCard} 
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

