import React from 'react';

export interface DashboardCard {
  id: string;
  title: string;
  image: string;
  icon: LucideIcon | string; // Pode ser o componente ou o nome da string vinda da API
  iconName?: string;
  content?: React.ReactNode | string; // Conteúdo interno do bloco

  // Hierarchy
  parentId?: string; // ID da página pai (se vazio, é página inicial)

  // Layout preferences
  fullWidth?: boolean;
  smallText?: boolean;

  // Ordering
  order?: number;

  // Sync State
  _isUnsynced?: boolean; // Se true, esta versão local é mais recente que o servidor
  _deleted?: boolean;    // Se true, o item foi excluído localmente mas aguarda confirmação do servidor
}

