const GOOGLE_SCRIPT_CODE = `// CONFIGURAÇÃO
var DRIVE_FOLDER_ID = "1w-DofVpEHKA46fEr6Gij38AcQJijl6iC";
var METADATA_SHEET_NAME = "_Metadata";

function doGet() {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheets = ss.getSheets();
    var cards = [];
    var metadata = {};

    // 1. Ler Metadados
    var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
    if (metaSheet) {
      var data = metaSheet.getDataRange().getValues();
      for (var i = 0; i < data.length; i++) {
        if (data[i][0]) metadata[data[i][0].toString().toLowerCase()] = data[i][1];
      }
    }

    // 2. Ler Cartões
    sheets.forEach(function(sheet) {
      if (sheet.getName().startsWith("_")) return;

      var title = sheet.getRange("B1").getValue();
      if (!title) title = sheet.getName();

      // Leitura robusta das células
      var image = sheet.getRange("B2").getValue();
      var icon = sheet.getRange("B3").getValue();
      var content = sheet.getRange("B4").getValue();
      var fullWidth = sheet.getRange("B5").getValue();
      var smallText = sheet.getRange("B6").getValue();
      var parentId = sheet.getRange("B7").getValue(); 
      var order = sheet.getRange("B8").getValue();
      var galleryRaw = sheet.getRange("B9").getValue();

      var gallery = [];
      try {
         if (galleryRaw) gallery = JSON.parse(galleryRaw);
      } catch(e) {}

      cards.push({
        id: sheet.getSheetId().toString(), 
        title: title,
        image: image || "https://picsum.photos/800/400",
        icon: icon || "FileText",
        content: content || "",
        fullWidth: fullWidth === true || fullWidth === "TRUE",
        smallText: smallText === true || smallText === "TRUE",
        parentId: parentId ? parentId.toString() : "",
        order: typeof order === 'number' ? order : 0,
        gallery: Array.isArray(gallery) ? gallery : []
      });
    });

    return createJSONOutput({status: "success", cards: cards, metadata: metadata});
  } catch(e) {
    return createJSONOutput({status: "error", message: e.toString()});
  }
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(30000);

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- UPLOAD ACTION (Novo) ---
    if (data.type === 'upload') {
       var name = data.fileName || "Upload_" + new Date().getTime();
       var result = uploadToDrive(data.imageBase64, data.mimeType, name);
       if (result.error) return createJSONOutput({status: "error", message: result.error});
       return createJSONOutput({status: "success", url: result.url});
    }

    // --- DELETE ACTION ---
    if (data.type === 'delete' && data.id) {
        var sheets = ss.getSheets();
        var sheetToDelete = null;
        for (var i = 0; i < sheets.length; i++) {
            if (sheets[i].getSheetId().toString() === data.id) {
                sheetToDelete = sheets[i];
                break;
            }
        }
        if (sheetToDelete) {
            ss.deleteSheet(sheetToDelete);
            return createJSONOutput({status: "success", message: "Deleted"});
        } else {
            return createJSONOutput({status: "error", message: "Sheet not found"});
        }
    }

    // --- METADATA (Capa Global) ---
    if (data.type === 'metadata') {
       var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
       if (!metaSheet) {
         metaSheet = ss.insertSheet(METADATA_SHEET_NAME);
         metaSheet.appendRow(["Key", "Value"]);
       }

       var saveData = function(key, val) {
         var range = metaSheet.getDataRange();
         var values = range.getValues();
         for(var i=0; i<values.length; i++) {
           if(values[i][0].toString().toLowerCase() === key.toLowerCase()) {
             metaSheet.getRange(i+1, 2).setValue(val);
             return;
           }
         }
         metaSheet.appendRow([key, val]);
       };

       if (data.homeCoverPosition) saveData("home_cover_pos", data.homeCoverPosition);

       if (data.imageBase64) {
         var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Home_Cover_" + new Date().getTime());
         if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
         saveData("home_cover_image", uploadResult.url);
         data.image = uploadResult.url;
       }

       return createJSONOutput({status: "success", data: data});
    }

    // --- CARTÕES (Abas) ---
    var sheets = ss.getSheets();
    var targetSheet = null;

    if (data.id) {
      for (var i = 0; i < sheets.length; i++) {
        if (sheets[i].getSheetId().toString() === data.id) {
          targetSheet = sheets[i];
          break;
        }
      }
    }
    if (!targetSheet && data.title) targetSheet = ss.getSheetByName(data.title);

    // Criar Nova Aba se não existir
    if (!targetSheet) {
       var safeTitle = (data.title || "New Page " + new Date().getSeconds()).substring(0,50);
       try { targetSheet = ss.insertSheet(safeTitle); } 
       catch(e) { targetSheet = ss.insertSheet(safeTitle + Math.floor(Math.random()*100)); }

       targetSheet.getRange("A1:A9").setValues([["Title"], ["Image"], ["Icon"], ["ContentHTML"], ["FullWidth"], ["SmallText"], ["ParentID"], ["Order"], ["Gallery"]]);
    }

    // Salvar Dados
    if (data.title) targetSheet.getRange("B1").setValue(data.title);
    if (data.icon) targetSheet.getRange("B3").setValue(data.icon);
    if (data.content !== undefined) targetSheet.getRange("B4").setValue(data.content);
    if (data.fullWidth !== undefined) targetSheet.getRange("B5").setValue(data.fullWidth);
    if (data.smallText !== undefined) targetSheet.getRange("B6").setValue(data.smallText);
    if (data.parentId !== undefined) targetSheet.getRange("B7").setValue(data.parentId);
    if (data.order !== undefined) targetSheet.getRange("B8").setValue(data.order);
    if (data.gallery !== undefined) targetSheet.getRange("B9").setValue(JSON.stringify(data.gallery));

    // Upload da Imagem do Cartão
    if (data.imageBase64) {
      var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Card_" + targetSheet.getName() + "_" + new Date().getTime());
      if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
      targetSheet.getRange("B2").setValue(uploadResult.url);
      data.image = uploadResult.url;
    }

    // Atualizar nome da aba
    if (data.title && targetSheet.getName() !== data.title) {
        try { targetSheet.setName(data.title.substring(0, 50)); } catch(e) {}
    }

    data.id = targetSheet.getSheetId().toString();
    return createJSONOutput({status: "success", data: data});

  } catch (err) {
    return createJSONOutput({status: "error", message: err.toString()});
  } finally {
    lock.releaseLock();
  }
}

function uploadToDrive(base64Data, mimeType, fileName) {
  try {
    var folder;
    if (DRIVE_FOLDER_ID) {
      try { folder = DriveApp.getFolderById(DRIVE_FOLDER_ID); } catch(e) { folder = null; }
    }
    if (!folder) folder = DriveApp.getRootFolder();

    var cleanBase64 = base64Data;
    if (base64Data.indexOf("base64,") !== -1) {
      cleanBase64 = base64Data.split("base64,")[1];
    }

    var blob = Utilities.newBlob(Utilities.base64Decode(cleanBase64), mimeType || "image/jpeg", fileName);
    var file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    return { url: "https://lh3.googleusercontent.com/d/" + file.getId() };

  } catch(e) {
    return { error: e.toString() };
  }
}

function createJSONOutput(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}`

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE, API_URL } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCardId, setActiveCardId] = useState<string | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Derived state for active card to ensure single source of truth
  const activeCard = activeCardId ? cards.find(c => c.id === activeCardId) || null : null;

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards && Array.isArray(parsed.cards)) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle,
                    gallery: Array.isArray(c.gallery) ? c.gallery : []
                }));
                // Sort by order
                rehydrated.sort((a: DashboardCard, b: DashboardCard) => (a.order || 0) - (b.order || 0));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                const img = parsed.metadata.home_cover_image || parsed.metadata.Home_Cover_Image;
                const pos = parsed.metadata.home_cover_pos || parsed.metadata.Home_Cover_Pos;
                if (img) setHomeCover(img);
                if (pos) setHomeCoverPos(Number(pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }

    // Auto-Sync on Mount
    handleSync();
  }, []);

  // Navigation Logic
  const handleBackToHome = () => {
    setActiveCardId(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleNavigateToCard = (card: DashboardCard) => {
    setActiveCardId(card.id);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleBreadcrumbClick = (targetCard: DashboardCard) => {
    setActiveCardId(targetCard.id);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Helper to build Breadcrumbs path from activeCard up to root
  const getBreadcrumbs = () => {
    if (!activeCard) return undefined;

    const path: { label: string; onClick?: () => void }[] = [];

    // Add Home
    path.push({ label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome });

    // Build hierarchy recursively
    const hierarchy: DashboardCard[] = [];
    let current: DashboardCard | undefined = activeCard;

    while (current) {
        hierarchy.unshift(current); // Add to front
        if (current.parentId) {
            // Loose comparison for robustness (string vs number)
            current = cards.find(c => c.id == current?.parentId);
        } else {
            current = undefined;
        }
    }

    hierarchy.forEach((c, index) => {
        const isLast = index === hierarchy.length - 1;
        path.push({
            label: c.title,
            onClick: isLast ? undefined : () => handleBreadcrumbClick(c)
        });
    });

    return path;
  };

  const handleCreateNewCard = (parentId?: string) => {
    const newId = Date.now().toString(); 
    const safeParentId = typeof parentId === 'string' ? parentId : undefined;

    // Determine new order (at end of list)
    const siblings = cards.filter(c => c.parentId == safeParentId && !c._deleted);
    const maxOrder = siblings.reduce((max, c) => Math.max(max, c.order || 0), 0);

    const newCard: DashboardCard = {
        id: newId,
        title: 'Nova Página',
        image: 'https://picsum.photos/seed/' + newId + '/600/300',
        icon: LucideIcons.FileText,
        iconName: 'FileText',
        content: '<p>Comece a escrever aqui...</p>',
        fullWidth: false,
        smallText: false,
        parentId: safeParentId,
        order: maxOrder + 1,
        gallery: [],
        _isUnsynced: true // Mark as needing sync
    };

    // Optimistically add to state
    const updatedCards = [...cards, newCard];
    setCards(updatedCards);
    setActiveCardId(newId); // Navigate to new card
    window.scrollTo({ top: 0, behavior: 'auto' });
    saveToLocalCache(updatedCards);

    // Sync
    handleUpdateCard(newCard, true);
  };

  // --- Deletion Logic ---
  const performDeleteAPI = async (cardId: string) => {
    const payload = { type: 'delete', id: cardId };
    await fetch(API_URL, { 
        method: 'POST', 
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(payload) 
    });
  };

  const handleDeleteCard = async (cardId: string) => {
    if (!window.confirm("Tem certeza que deseja excluir esta página e todo o conteúdo dela?")) return;

    // Optimistic UI Update: MARK as deleted instead of removing
    setCards(prev => {
        const newCards = prev.map(c => {
            if (c.id === cardId || c.parentId === cardId) {
                return { ...c, _deleted: true, _isUnsynced: true };
            }
            return c;
        });
        saveToLocalCache(newCards);
        return newCards;
    });

    if (activeCard && activeCard.id === cardId) {
        handleBackToHome();
    }

    try {
        await performDeleteAPI(cardId);
    } catch (e) {
        console.error("Delete failed on server", e);
    }
  };

  // --- Reorder Logic ---
  const handleReorderCard = async (cardId: string, direction: 'left' | 'right') => {
    const card = cards.find(c => c.id === cardId);
    if (!card) return;

    const siblings = cards
        .filter(c => c.parentId === card.parentId && !c._deleted)
        .sort((a, b) => (a.order || 0) - (b.order || 0));

    const currentIndex = siblings.findIndex(c => c.id === cardId);
    if (currentIndex === -1) return;

    const targetIndex = direction === 'left' ? currentIndex - 1 : currentIndex + 1;

    if (targetIndex >= 0 && targetIndex < siblings.length) {
        const swapCard = siblings[targetIndex];

        // Swap orders
        const cardOrder = card.order || 0;
        const swapOrder = swapCard.order || 0;

        // Handling equal orders case
        if (cardOrder === swapOrder) {
             siblings.forEach((c, idx) => c.order = idx);
             card.order = currentIndex;
             swapCard.order = targetIndex;
             const temp = card.order;
             card.order = swapCard.order;
             swapCard.order = temp;
        } else {
             const temp = card.order;
             card.order = swapCard.order;
             swapCard.order = temp;
        }

        const updatedCards = cards.map(c => {
            if (c.id === card.id) return { ...c, order: card.order, _isUnsynced: true };
            if (c.id === swapCard.id) return { ...c, order: swapCard.order, _isUnsynced: true };
            return c;
        });

        updatedCards.sort((a, b) => (a.order || 0) - (b.order || 0));

        setCards(updatedCards);
        saveToLocalCache(updatedCards);

        await handleUpdateCard(card);
        await handleUpdateCard(swapCard);
    }
  };

  // --- Move/Nest Logic (Drag and Drop) ---
  const handleMoveCard = async (draggedId: string, targetParentId?: string) => {
    if (draggedId === targetParentId) return;

    const cardToMove = cards.find(c => c.id === draggedId);
    if (!cardToMove) return;

    const newSiblings = cards.filter(c => c.parentId == targetParentId && !c._deleted);
    const maxOrder = newSiblings.reduce((max, c) => Math.max(max, c.order || 0), 0);

    const updatedCard = { 
        ...cardToMove, 
        parentId: targetParentId, 
        order: maxOrder + 1,
        _isUnsynced: true 
    };

    const updatedList = cards.map(c => c.id === draggedId ? updatedCard : c);
    updatedList.sort((a, b) => (a.order || 0) - (b.order || 0));

    setCards(updatedList);
    saveToLocalCache(updatedList);

    handleUpdateCard(updatedCard);
  };

  // --- Upload Gallery Image Logic ---
  const handleUploadGalleryImage = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = async () => {
            try {
                const base64String = reader.result as string;
                const payload = {
                    type: 'upload',
                    imageBase64: base64String,
                    mimeType: file.type,
                    fileName: "Gallery_" + file.name
                };

                const response = await fetch(API_URL, {
                    method: 'POST',
                    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                    body: JSON.stringify(payload)
                });

                const result = await response.json();
                if (result.status === 'success' && result.url) {
                    resolve(result.url);
                } else {
                    reject(new Error(result.message || 'Upload failed'));
                }
            } catch (e) {
                reject(e);
            }
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  };

  const handleSync = async () => {
    try {
        const response = await fetch(API_URL);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();
        console.log("Sync Result:", result); 

        const serverCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id ? item.id.toString() : Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText,
                parentId: item.parentId ? item.parentId.toString() : undefined,
                order: Number(item.order) || 0,
                gallery: Array.isArray(item.gallery) ? item.gallery : [],
                _isUnsynced: false // Server items are synced by definition
            };
        });

        // MERGE LOGIC
        const itemsToRetry: DashboardCard[] = [];

        setCards(currentCards => {
            const freshMergedCards = [...serverCards];

            currentCards.forEach(localCard => {
                if (localCard._isUnsynced) {
                    const serverIndex = freshMergedCards.findIndex(c => c.id === localCard.id);

                    if (serverIndex !== -1) {
                        freshMergedCards[serverIndex] = localCard;
                        itemsToRetry.push(localCard);
                    } else {
                        if (!localCard._deleted) {
                            freshMergedCards.push(localCard);
                            itemsToRetry.push(localCard);
                        }
                    }
                }
            });

            freshMergedCards.sort((a, b) => (a.order || 0) - (b.order || 0));
            saveToLocalCache(freshMergedCards, result.metadata);
            return freshMergedCards;
        });

        if (result.metadata) {
            const img = result.metadata['home_cover_image'] || result.metadata['Home_Cover_Image'];
            const pos = result.metadata['home_cover_pos'] || result.metadata['Home_Cover_Pos'];
            if (img) setHomeCover(img);
            if (pos) setHomeCoverPos(Number(pos));
        }

        if (itemsToRetry.length > 0) {
            for (const item of itemsToRetry) {
                if (item._deleted) {
                    await performDeleteAPI(item.id);
                } else {
                    await handleUpdateCard(item); 
                }
                await new Promise(r => setTimeout(r, 500));
            }
        }

    } catch (error) {
        console.error("Sync failed:", error);
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(API_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        if (result.status === 'success' && result.data.image && result.data.image.startsWith('http')) {
            setHomeCover(result.data.image);
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string } | DashboardCard, isNew = false) => {

    const targetCardId = (updatedFields as any).id || activeCardId;

    let targetCard: DashboardCard | undefined;
    if (isNew) {
        targetCard = updatedFields as DashboardCard;
    } else {
        targetCard = cards.find(c => c.id === targetCardId);
    }

    if (!targetCard) return;
    if (targetCard._deleted && !isNew) return;

    const updatedCardFull: DashboardCard = { 
        ...targetCard, 
        ...updatedFields,
        icon: (updatedFields as any).iconName ? (LucideIcons as any)[(updatedFields as any).iconName] : (updatedFields.icon || targetCard.icon),
        _isUnsynced: true 
    };

    setCards(prev => {
        let newCards;
        const exists = prev.find(c => c.id === targetCard!.id);

        if (exists) {
            newCards = prev.map(c => c.id === targetCard!.id ? updatedCardFull : c);
        } else {
            newCards = [...prev, updatedCardFull];
        }

        newCards.sort((a, b) => (a.order || 0) - (b.order || 0));
        saveToLocalCache(newCards);
        return newCards;
    });

    try {
        const payload = {
            id: targetCard.id,
            title: updatedFields.title || targetCard.title,
            icon: (updatedFields as any).iconName || (targetCard as any).iconName || 'HelpCircle',
            content: updatedFields.content !== undefined ? updatedFields.content : targetCard.content,
            imageBase64: (updatedFields as any).imageBase64, 
            mimeType: (updatedFields as any).mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText,
            parentId: updatedCardFull.parentId === undefined ? "" : updatedCardFull.parentId, 
            order: updatedCardFull.order,
            gallery: updatedCardFull.gallery // Send gallery array
        };

        const response = await fetch(API_URL, { 
            method: 'POST', 
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        if (result.status === 'success' && result.data) {
            setCards(prev => {
                const finalCards = prev.map(c => {
                    if (c.id === targetCard!.id) {
                        return {
                            ...c,
                            _isUnsynced: false, 
                            image: (result.data.image && result.data.image.startsWith('http')) ? result.data.image : c.image
                        };
                    }
                    return c;
                });
                saveToLocalCache(finalCards);
                return finalCards;
            });
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = getBreadcrumbs();

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                key={activeCard.id} 
                card={activeCard} 
                allCards={cards} 
                onUpdateCard={handleUpdateCard} 
                onNavigateToCard={handleNavigateToCard}
                onCreateSubPage={handleCreateNewCard}
                onDeleteCard={handleDeleteCard} 
                onMoveCard={handleMoveCard}
                onReorderCard={handleReorderCard}
                onUploadGalleryImage={handleUploadGalleryImage}
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards.filter(c => !c.parentId && !c._deleted)} 
                    onCardClick={handleNavigateToCard} 
                    onNewCard={() => handleCreateNewCard()}
                    onMoveCard={handleMoveCard}
                    onDeleteCard={handleDeleteCard} 
                    onReorderCard={handleReorderCard} 
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { DashboardCard } from '../types';
import { LayoutTemplate, Loader2, MoreHorizontal, Plus, Trash2, ArrowUpCircle, ImagePlus, X } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { IconPicker } from './IconPicker';
import { RichTextEditor } from './RichTextEditor';
import { Card } from './Card'; // Import reused Card component

interface ActivePageProps {
  card: DashboardCard;
  allCards: DashboardCard[]; 
  onUpdateCard: (fields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string }) => void;
  onNavigateToCard: (card: DashboardCard) => void;
  onCreateSubPage: (parentId: string) => void;
  onDeleteCard: (cardId: string) => void;
  onMoveCard: (draggedId: string, targetParentId?: string) => void;
  onReorderCard: (cardId: string, direction: 'left' | 'right') => void;
  onUploadGalleryImage?: (file: File) => Promise<string>;
}

export const ActivePage: React.FC<ActivePageProps> = ({ 
  card, 
  allCards, 
  onUpdateCard, 
  onNavigateToCard, 
  onCreateSubPage,
  onDeleteCard,
  onMoveCard,
  onReorderCard,
  onUploadGalleryImage
}) => {
  const [currentIconName, setCurrentIconName] = useState<string>(
    typeof card.icon === 'string' ? card.icon : ((card as any).iconName || 'HelpCircle')
  );
  const [isUploading, setIsUploading] = useState(false);
  const [isGalleryUploading, setIsGalleryUploading] = useState(false);
  const [showIconPicker, setShowIconPicker] = useState(false);
  const [showPageOptions, setShowPageOptions] = useState(false);

  const [fullWidth, setFullWidth] = useState(card.fullWidth || false);
  const [smallText, setSmallText] = useState(card.smallText || false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const optionsMenuRef = useRef<HTMLDivElement>(null);

  // Filter subpages - Ignore deleted ones
  const subPages = allCards.filter(c => c.parentId === card.id && !c._deleted);

  useEffect(() => {
    setFullWidth(card.fullWidth || false);
    setSmallText(card.smallText || false);
  }, [card.id, card.fullWidth, card.smallText]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (optionsMenuRef.current && !optionsMenuRef.current.contains(event.target as Node)) {
        setShowPageOptions(false);
      }
    };
    if (showPageOptions) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showPageOptions]);

  const Icon = (LucideIcons as any)[currentIconName] || LucideIcons.HelpCircle;

  // --- Handlers ---

  const handleTitleChange = (e: React.FocusEvent<HTMLInputElement>) => {
    if (e.target.value !== card.title) {
        onUpdateCard({ title: e.target.value });
    }
  };

  const handleIconSelect = (newIconName: string) => {
    setCurrentIconName(newIconName);
    onUpdateCard({ icon: newIconName, iconName: newIconName } as any);
    setShowIconPicker(false);
  };

  const handleChangeCoverClick = () => {
    fileInputRef.current?.click();
  };

  const handleToggleFullWidth = () => {
    const newValue = !fullWidth;
    setFullWidth(newValue);
    onUpdateCard({ fullWidth: newValue });
  };

  const handleToggleSmallText = () => {
    const newValue = !smallText;
    setSmallText(newValue);
    onUpdateCard({ smallText: newValue });
  };

  const handleContentUpdate = (newHtml: string) => {
    if (newHtml !== card.content) {
        onUpdateCard({ content: newHtml });
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 5 * 1024 * 1024) { 
          alert("A imagem deve ser menor que 5MB.");
          return;
      }

      setIsUploading(true);
      const reader = new FileReader();

      reader.onloadend = () => {
        const base64String = reader.result as string;
        onUpdateCard({ 
            image: base64String, // Temporário para UI
            imageBase64: base64String, // Para upload
            mimeType: file.type 
        });
        setTimeout(() => setIsUploading(false), 5000); 
      };

      reader.readAsDataURL(file);
    }
  };

  // --- Gallery Handlers ---

  const handleGalleryClick = () => {
    galleryInputRef.current?.click();
  };

  const handleGalleryFilesChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    if (!onUploadGalleryImage) {
        alert("Upload de galeria não configurado.");
        return;
    }

    setIsGalleryUploading(true);
    const newGallery = [...(card.gallery || [])];

    // Optimistically add placehoders (not implemented for brevity, just loader)

    try {
        for (let i = 0; i < files.length; i++) {
            const file = files[i];
            // Simple validation
            if (file.size > 5 * 1024 * 1024) continue;

            const url = await onUploadGalleryImage(file);
            newGallery.push(url);
        }
        // Update Card with new gallery
        onUpdateCard({ gallery: newGallery });
    } catch (e) {
        console.error("Gallery upload error", e);
        alert("Erro ao enviar algumas imagens.");
    } finally {
        setIsGalleryUploading(false);
        if (galleryInputRef.current) galleryInputRef.current.value = '';
    }
  };

  const handleRemoveGalleryImage = (indexToRemove: number) => {
      const newGallery = (card.gallery || []).filter((_, idx) => idx !== indexToRemove);
      onUpdateCard({ gallery: newGallery });
  };

  return (
    <div className={`w-full min-h-screen bg-notion-bg text-notion-text pb-32 animate-in fade-in duration-300 ${smallText ? 'text-sm' : 'text-base'}`}>

      {showIconPicker && (
          <IconPicker 
            onSelect={handleIconSelect} 
            onClose={() => setShowIconPicker(false)} 
          />
      )}

      {/* Cover Image */}
      <div className="h-[30vh] min-h-[200px] w-full group relative bg-notion-card select-none">
        <img 
          src={card.image} 
          alt={card.title} 
          className={`w-full h-full object-cover object-center transition-opacity ${isUploading ? 'opacity-50' : 'opacity-100'}`}
        />

        {isUploading && (
            <div className="absolute inset-0 flex items-center justify-center">
                <div className="bg-black/60 px-4 py-2 rounded-full flex items-center gap-2 text-white text-sm backdrop-blur-sm shadow-lg border border-white/10">
                    <Loader2 className="animate-spin text-notion-blue" size={16} />
                    <span>Salvando no Drive...</span>
                </div>
            </div>
        )}

        <div className="absolute inset-0 bg-black/10 group-hover:bg-black/0 transition-colors pointer-events-none" />

        <button 
            onClick={handleChangeCoverClick}
            disabled={isUploading}
            className="absolute bottom-4 right-4 bg-black/50 hover:bg-black/70 text-xs px-2 py-1 rounded backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 disabled:opacity-0 cursor-pointer text-white"
        >
            Alterar capa
        </button>
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
        />
      </div>

      {/* Main Layout Container */}
      <div className={`mx-auto px-4 relative transition-all duration-300 ${fullWidth ? 'max-w-full px-8 md:px-12' : 'max-w-[900px] md:px-24'}`}>

        {/* Page Options Menu */}
        <div className="absolute top-4 right-4 z-50" ref={optionsMenuRef}>
            <button 
                onClick={() => setShowPageOptions(!showPageOptions)}
                className="p-1 text-notion-muted hover:bg-notion-hover hover:text-notion-text rounded transition-colors"
                title="Opções da página"
            >
                <MoreHorizontal size={20} />
            </button>

            {showPageOptions && (
                <div className="absolute right-0 top-8 w-60 bg-[#252525] border border-white/10 rounded-lg shadow-xl p-2 flex flex-col gap-1 animate-in fade-in slide-in-from-top-2 z-50">
                    <div className="px-2 py-1.5 text-xs font-bold text-notion-muted uppercase tracking-wider">
                        Estilo da página
                    </div>
                    <div className="flex items-center justify-between px-2 py-1.5 hover:bg-white/5 rounded transition-colors select-none">
                        <div className="flex items-center gap-2 text-sm text-notion-text">
                            <span className="text-xs border border-white/20 px-1 rounded">A</span>
                            <span>Small text</span>
                        </div>
                        <div 
                            onClick={handleToggleSmallText}
                            className={`w-9 h-5 rounded-full p-0.5 cursor-pointer transition-colors ${smallText ? 'bg-notion-blue' : 'bg-notion-muted/40'}`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${smallText ? 'translate-x-4' : 'translate-x-0'}`} />
                        </div>
                    </div>
                    <div className="flex items-center justify-between px-2 py-1.5 hover:bg-white/5 rounded transition-colors select-none">
                        <div className="flex items-center gap-2 text-sm text-notion-text">
                            <LayoutTemplate size={14} />
                            <span>Full width</span>
                        </div>
                        <div 
                            onClick={handleToggleFullWidth}
                            className={`w-9 h-5 rounded-full p-0.5 cursor-pointer transition-colors ${fullWidth ? 'bg-notion-blue' : 'bg-notion-muted/40'}`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${fullWidth ? 'translate-x-4' : 'translate-x-0'}`} />
                        </div>
                    </div>

                    <div className="h-px bg-white/10 my-1" />

                    {/* Move/Delete Actions */}
                    {card.parentId && (
                        <button 
                            onClick={() => onMoveCard(card.id, undefined)} // Undefined parentId means Move to Root
                            className="flex items-center gap-2 px-2 py-1.5 hover:bg-white/5 rounded transition-colors text-sm text-notion-text text-left w-full"
                        >
                            <ArrowUpCircle size={14} />
                            <span>Mover para o topo (Home)</span>
                        </button>
                    )}

                    <button 
                        onClick={() => onDeleteCard(card.id)}
                        className="flex items-center gap-2 px-2 py-1.5 hover:bg-red-900/30 text-red-400 rounded transition-colors text-sm text-left w-full"
                    >
                        <Trash2 size={14} />
                        <span>Excluir página</span>
                    </button>
                </div>
            )}
        </div>

        {/* Icon */}
        <div className="-mt-10 mb-2 relative z-10 group w-fit">
          <div 
            onClick={() => setShowIconPicker(true)}
            className="w-[78px] h-[78px] flex items-center justify-center rounded-full bg-notion-card shadow-sm hover:bg-notion-hover cursor-pointer transition-colors text-notion-text relative border border-white/5 overflow-hidden"
          >
            {React.createElement(Icon, { size: 40 })}
            <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-full opacity-0 group-hover:opacity-100 transition-opacity text-xs font-medium text-white pointer-events-none">
                Editar
            </div>
          </div>
        </div>

        {/* Title */}
        <div className="mb-6 group relative">
            <input 
                type="text"
                defaultValue={card.title}
                onBlur={handleTitleChange}
                className="w-full text-4xl font-bold text-notion-text bg-transparent border-none outline-none placeholder:text-notion-muted/20 focus:ring-0 p-0 m-0"
                placeholder="Sem título"
            />
        </div>

        {/* Divider */}
        <div className="h-px bg-white/10 w-full mb-6" />

        {/* --- Sub-Pages Grid --- */}
        <div className="mb-6">
            {subPages.length > 0 && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 mb-2">
                    {subPages.map(subCard => (
                        <Card 
                            key={subCard.id} 
                            card={subCard} 
                            onClick={onNavigateToCard}
                            onDrop={onMoveCard}
                            onDelete={onDeleteCard}
                            onReorder={onReorderCard}
                        />
                    ))}
                </div>
            )}

            <button 
                onClick={() => onCreateSubPage(card.id)}
                className="group flex items-center gap-2 text-notion-muted hover:text-notion-text text-sm w-fit py-1 px-1 rounded hover:bg-notion-hover transition-colors cursor-pointer"
            >
                <Plus size={16} />
                <span>Nova sub-página</span>
            </button>
        </div>

        {/* --- Gallery Section --- */}
        <div className="mb-8">
            <h3 className="text-sm font-semibold text-notion-muted uppercase tracking-wider mb-3 flex items-center justify-between">
                <span>Galeria de Fotos</span>
                {isGalleryUploading && (
                    <span className="flex items-center gap-2 text-notion-blue normal-case text-xs">
                         <Loader2 className="animate-spin" size={12} /> Enviando...
                    </span>
                )}
            </h3>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {card.gallery && card.gallery.map((imgUrl, index) => (
                    <div key={index} className="group relative aspect-square bg-notion-card rounded-lg overflow-hidden border border-white/5 hover:border-white/20 transition-all">
                        <img src={imgUrl} alt={`Gallery ${index}`} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <button 
                                onClick={() => handleRemoveGalleryImage(index)}
                                className="p-2 bg-red-500/80 hover:bg-red-600 text-white rounded-full backdrop-blur-sm"
                                title="Remover imagem"
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </div>
                ))}

                {/* Add Button */}
                <button 
                    onClick={handleGalleryClick}
                    disabled={isGalleryUploading}
                    className="aspect-square flex flex-col items-center justify-center bg-notion-hover/50 hover:bg-notion-hover rounded-lg border border-dashed border-white/20 hover:border-notion-blue transition-colors text-notion-muted hover:text-notion-blue gap-2"
                >
                    <ImagePlus size={24} />
                    <span className="text-xs font-medium">Adicionar</span>
                </button>
            </div>

            <input 
                type="file" 
                ref={galleryInputRef} 
                onChange={handleGalleryFilesChange} 
                accept="image/*" 
                multiple 
                className="hidden" 
            />
        </div>

        {/* --- Rich Text Editor Integration --- */}
        <div className="w-full">
            <h3 className="text-sm font-semibold text-notion-muted uppercase tracking-wider mb-2">Conteúdo</h3>
            <RichTextEditor 
                initialContent={typeof card.content === 'string' ? card.content : ''}
                onUpdate={handleContentUpdate}
            />
        </div>

      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { DashboardCard } from '../types';
import { LayoutTemplate, Loader2, MoreHorizontal, Plus, Trash2, ArrowUpCircle, ImagePlus, X } from 'lucide-react';
import * as LucideIcons from 'lucide-react';
import { IconPicker } from './IconPicker';
import { RichTextEditor } from './RichTextEditor';
import { Card } from './Card'; // Import reused Card component

interface ActivePageProps {
  card: DashboardCard;
  allCards: DashboardCard[]; 
  onUpdateCard: (fields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string }) => void;
  onNavigateToCard: (card: DashboardCard) => void;
  onCreateSubPage: (parentId: string) => void;
  onDeleteCard: (cardId: string) => void;
  onMoveCard: (draggedId: string, targetParentId?: string) => void;
  onReorderCard: (cardId: string, direction: 'left' | 'right') => void;
  onUploadGalleryImage?: (file: File) => Promise<string>;
}

// Utility: Client-side Image Compression
const compressImage = (file: File): Promise<File> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 1200;
        const MAX_HEIGHT = 1200;
        let width = img.width;
        let height = img.height;

        if (width > height) {
          if (width > MAX_WIDTH) {
            height *= MAX_WIDTH / width;
            width = MAX_WIDTH;
          }
        } else {
          if (height > MAX_HEIGHT) {
            width *= MAX_HEIGHT / height;
            height = MAX_HEIGHT;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        canvas.toBlob(
          (blob) => {
            if (blob) {
              const newFile = new File([blob], file.name, {
                type: 'image/jpeg',
                lastModified: Date.now(),
              });
              resolve(newFile);
            } else {
              reject(new Error('Image compression failed'));
            }
          },
          'image/jpeg',
          0.85 // 85% Quality
        );
      };
      img.onerror = (error) => reject(error);
    };
    reader.onerror = (error) => reject(error);
  });
};

export const ActivePage: React.FC<ActivePageProps> = ({ 
  card, 
  allCards, 
  onUpdateCard, 
  onNavigateToCard, 
  onCreateSubPage,
  onDeleteCard,
  onMoveCard,
  onReorderCard,
  onUploadGalleryImage
}) => {
  const [currentIconName, setCurrentIconName] = useState<string>(
    typeof card.icon === 'string' ? card.icon : ((card as any).iconName || 'HelpCircle')
  );
  const [isUploading, setIsUploading] = useState(false);
  const [isGalleryUploading, setIsGalleryUploading] = useState(false);
  const [showIconPicker, setShowIconPicker] = useState(false);
  const [showPageOptions, setShowPageOptions] = useState(false);

  const [fullWidth, setFullWidth] = useState(card.fullWidth || false);
  const [smallText, setSmallText] = useState(card.smallText || false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);
  const optionsMenuRef = useRef<HTMLDivElement>(null);

  // Filter subpages - Ignore deleted ones
  const subPages = allCards.filter(c => c.parentId === card.id && !c._deleted);

  useEffect(() => {
    setFullWidth(card.fullWidth || false);
    setSmallText(card.smallText || false);
  }, [card.id, card.fullWidth, card.smallText]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (optionsMenuRef.current && !optionsMenuRef.current.contains(event.target as Node)) {
        setShowPageOptions(false);
      }
    };
    if (showPageOptions) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showPageOptions]);

  const Icon = (LucideIcons as any)[currentIconName] || LucideIcons.HelpCircle;

  // --- Handlers ---

  const handleTitleChange = (e: React.FocusEvent<HTMLInputElement>) => {
    if (e.target.value !== card.title) {
        onUpdateCard({ title: e.target.value });
    }
  };

  const handleIconSelect = (newIconName: string) => {
    setCurrentIconName(newIconName);
    onUpdateCard({ icon: newIconName, iconName: newIconName } as any);
    setShowIconPicker(false);
  };

  const handleChangeCoverClick = () => {
    fileInputRef.current?.click();
  };

  const handleToggleFullWidth = () => {
    const newValue = !fullWidth;
    setFullWidth(newValue);
    onUpdateCard({ fullWidth: newValue });
  };

  const handleToggleSmallText = () => {
    const newValue = !smallText;
    setSmallText(newValue);
    onUpdateCard({ smallText: newValue });
  };

  const handleContentUpdate = (newHtml: string) => {
    if (newHtml !== card.content) {
        onUpdateCard({ content: newHtml });
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.size > 10 * 1024 * 1024) { 
          alert("A imagem deve ser menor que 10MB.");
          return;
      }

      setIsUploading(true);

      // Compress Cover Image as well
      compressImage(file).then(compressedFile => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = reader.result as string;
            onUpdateCard({ 
                image: base64String, // Temporário para UI
                imageBase64: base64String, // Para upload
                mimeType: compressedFile.type 
            });
            setTimeout(() => setIsUploading(false), 5000); 
        };
        reader.readAsDataURL(compressedFile);
      }).catch(err => {
        console.error("Cover compression error", err);
        setIsUploading(false);
        alert("Erro ao processar imagem.");
      });
    }
  };

  // --- Gallery Handlers ---

  const handleGalleryClick = () => {
    galleryInputRef.current?.click();
  };

  const handleGalleryFilesChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    if (!onUploadGalleryImage) {
        alert("Upload de galeria não configurado.");
        return;
    }

    setIsGalleryUploading(true);

    // Copy current gallery
    let currentGallery = [...(card.gallery || [])];

    try {
        for (let i = 0; i < files.length; i++) {
            const file = files[i];

            try {
                // Compress before upload to ensure fetch success
                const compressedFile = await compressImage(file);

                const url = await onUploadGalleryImage(compressedFile);
                currentGallery = [...currentGallery, url];

                // Save incrementally so if one fails, previous ones are kept
                onUpdateCard({ gallery: currentGallery });

            } catch (err) {
                console.error(`Error uploading ${file.name}`, err);
                alert(`Falha ao enviar ${file.name}. Verifique a conexão.`);
            }
        }
    } catch (e) {
        console.error("Gallery batch error", e);
    } finally {
        setIsGalleryUploading(false);
        if (galleryInputRef.current) galleryInputRef.current.value = '';
    }
  };

  const handleRemoveGalleryImage = (indexToRemove: number) => {
      const newGallery = (card.gallery || []).filter((_, idx) => idx !== indexToRemove);
      onUpdateCard({ gallery: newGallery });
  };

  return (
    <div className={`w-full min-h-screen bg-notion-bg text-notion-text pb-32 animate-in fade-in duration-300 ${smallText ? 'text-sm' : 'text-base'}`}>

      {showIconPicker && (
          <IconPicker 
            onSelect={handleIconSelect} 
            onClose={() => setShowIconPicker(false)} 
          />
      )}

      {/* Cover Image */}
      <div className="h-[30vh] min-h-[200px] w-full group relative bg-notion-card select-none">
        <img 
          src={card.image} 
          alt={card.title} 
          className={`w-full h-full object-cover object-center transition-opacity ${isUploading ? 'opacity-50' : 'opacity-100'}`}
        />

        {isUploading && (
            <div className="absolute inset-0 flex items-center justify-center">
                <div className="bg-black/60 px-4 py-2 rounded-full flex items-center gap-2 text-white text-sm backdrop-blur-sm shadow-lg border border-white/10">
                    <Loader2 className="animate-spin text-notion-blue" size={16} />
                    <span>Otimizando e salvando...</span>
                </div>
            </div>
        )}

        <div className="absolute inset-0 bg-black/10 group-hover:bg-black/0 transition-colors pointer-events-none" />

        <button 
            onClick={handleChangeCoverClick}
            disabled={isUploading}
            className="absolute bottom-4 right-4 bg-black/50 hover:bg-black/70 text-xs px-2 py-1 rounded backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity border border-white/10 disabled:opacity-0 cursor-pointer text-white"
        >
            Alterar capa
        </button>
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept="image/*" 
            className="hidden" 
        />
      </div>

      {/* Main Layout Container */}
      <div className={`mx-auto px-4 relative transition-all duration-300 ${fullWidth ? 'max-w-full px-8 md:px-12' : 'max-w-[900px] md:px-24'}`}>

        {/* Page Options Menu */}
        <div className="absolute top-4 right-4 z-50" ref={optionsMenuRef}>
            <button 
                onClick={() => setShowPageOptions(!showPageOptions)}
                className="p-1 text-notion-muted hover:bg-notion-hover hover:text-notion-text rounded transition-colors"
                title="Opções da página"
            >
                <MoreHorizontal size={20} />
            </button>

            {showPageOptions && (
                <div className="absolute right-0 top-8 w-60 bg-[#252525] border border-white/10 rounded-lg shadow-xl p-2 flex flex-col gap-1 animate-in fade-in slide-in-from-top-2 z-50">
                    <div className="px-2 py-1.5 text-xs font-bold text-notion-muted uppercase tracking-wider">
                        Estilo da página
                    </div>
                    <div className="flex items-center justify-between px-2 py-1.5 hover:bg-white/5 rounded transition-colors select-none">
                        <div className="flex items-center gap-2 text-sm text-notion-text">
                            <span className="text-xs border border-white/20 px-1 rounded">A</span>
                            <span>Small text</span>
                        </div>
                        <div 
                            onClick={handleToggleSmallText}
                            className={`w-9 h-5 rounded-full p-0.5 cursor-pointer transition-colors ${smallText ? 'bg-notion-blue' : 'bg-notion-muted/40'}`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${smallText ? 'translate-x-4' : 'translate-x-0'}`} />
                        </div>
                    </div>
                    <div className="flex items-center justify-between px-2 py-1.5 hover:bg-white/5 rounded transition-colors select-none">
                        <div className="flex items-center gap-2 text-sm text-notion-text">
                            <LayoutTemplate size={14} />
                            <span>Full width</span>
                        </div>
                        <div 
                            onClick={handleToggleFullWidth}
                            className={`w-9 h-5 rounded-full p-0.5 cursor-pointer transition-colors ${fullWidth ? 'bg-notion-blue' : 'bg-notion-muted/40'}`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transition-transform ${fullWidth ? 'translate-x-4' : 'translate-x-0'}`} />
                        </div>
                    </div>

                    <div className="h-px bg-white/10 my-1" />

                    {/* Move/Delete Actions */}
                    {card.parentId && (
                        <button 
                            onClick={() => onMoveCard(card.id, undefined)} // Undefined parentId means Move to Root
                            className="flex items-center gap-2 px-2 py-1.5 hover:bg-white/5 rounded transition-colors text-sm text-notion-text text-left w-full"
                        >
                            <ArrowUpCircle size={14} />
                            <span>Mover para o topo (Home)</span>
                        </button>
                    )}

                    <button 
                        onClick={() => onDeleteCard(card.id)}
                        className="flex items-center gap-2 px-2 py-1.5 hover:bg-red-900/30 text-red-400 rounded transition-colors text-sm text-left w-full"
                    >
                        <Trash2 size={14} />
                        <span>Excluir página</span>
                    </button>
                </div>
            )}
        </div>

        {/* Icon */}
        <div className="-mt-10 mb-2 relative z-10 group w-fit">
          <div 
            onClick={() => setShowIconPicker(true)}
            className="w-[78px] h-[78px] flex items-center justify-center rounded-full bg-notion-card shadow-sm hover:bg-notion-hover cursor-pointer transition-colors text-notion-text relative border border-white/5 overflow-hidden"
          >
            {React.createElement(Icon, { size: 40 })}
            <div className="absolute inset-0 flex items-center justify-center bg-black/40 rounded-full opacity-0 group-hover:opacity-100 transition-opacity text-xs font-medium text-white pointer-events-none">
                Editar
            </div>
          </div>
        </div>

        {/* Title */}
        <div className="mb-6 group relative">
            <input 
                type="text"
                defaultValue={card.title}
                onBlur={handleTitleChange}
                className="w-full text-4xl font-bold text-notion-text bg-transparent border-none outline-none placeholder:text-notion-muted/20 focus:ring-0 p-0 m-0"
                placeholder="Sem título"
            />
        </div>

        {/* Divider */}
        <div className="h-px bg-white/10 w-full mb-6" />

        {/* --- Sub-Pages Grid --- */}
        <div className="mb-6">
            {subPages.length > 0 && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 mb-2">
                    {subPages.map(subCard => (
                        <Card 
                            key={subCard.id} 
                            card={subCard} 
                            onClick={onNavigateToCard}
                            onDrop={onMoveCard}
                            onDelete={onDeleteCard}
                            onReorder={onReorderCard}
                        />
                    ))}
                </div>
            )}

            <button 
                onClick={() => onCreateSubPage(card.id)}
                className="group flex items-center gap-2 text-notion-muted hover:text-notion-text text-sm w-fit py-1 px-1 rounded hover:bg-notion-hover transition-colors cursor-pointer"
            >
                <Plus size={16} />
                <span>Nova sub-página</span>
            </button>
        </div>

        {/* --- Gallery Section --- */}
        <div className="mb-8">
            <h3 className="text-sm font-semibold text-notion-muted uppercase tracking-wider mb-3 flex items-center justify-between">
                <span>Galeria de Fotos</span>
                {isGalleryUploading && (
                    <span className="flex items-center gap-2 text-notion-blue normal-case text-xs">
                         <Loader2 className="animate-spin" size={12} /> Enviando e salvando...
                    </span>
                )}
            </h3>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {card.gallery && card.gallery.map((imgUrl, index) => (
                    <div key={index} className="group relative aspect-square bg-notion-card rounded-lg overflow-hidden border border-white/5 hover:border-white/20 transition-all">
                        <img src={imgUrl} alt={`Gallery ${index}`} className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                            <button 
                                onClick={() => handleRemoveGalleryImage(index)}
                                className="p-2 bg-red-500/80 hover:bg-red-600 text-white rounded-full backdrop-blur-sm"
                                title="Remover imagem"
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </div>
                ))}

                {/* Add Button */}
                <button 
                    onClick={handleGalleryClick}
                    disabled={isGalleryUploading}
                    className="aspect-square flex flex-col items-center justify-center bg-notion-hover/50 hover:bg-notion-hover rounded-lg border border-dashed border-white/20 hover:border-notion-blue transition-colors text-notion-muted hover:text-notion-blue gap-2"
                >
                    <ImagePlus size={24} />
                    <span className="text-xs font-medium">Adicionar</span>
                </button>
            </div>

            <input 
                type="file" 
                ref={galleryInputRef} 
                onChange={handleGalleryFilesChange} 
                accept="image/*" 
                multiple 
                className="hidden" 
            />
            <p className="text-[10px] text-notion-muted mt-2">
                Dica: Você pode selecionar várias fotos de uma vez.
            </p>
        </div>

        {/* --- Rich Text Editor Integration --- */}
        <div className="w-full">
            <h3 className="text-sm font-semibold text-notion-muted uppercase tracking-wider mb-2">Conteúdo</h3>
            <RichTextEditor 
                initialContent={typeof card.content === 'string' ? card.content : ''}
                onUpdate={handleContentUpdate}
            />
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, RefreshCw, Save, Copy, Check } from 'lucide-react';
import { API_URL } from '../constants';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSync: () => Promise<void>;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, onSync }) => {
  const [isLoading, setIsLoading] = useState(false);
  const [status, setStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [copied, setCopied] = useState(false);

  const handleSaveAndSync = async () => {
    setIsLoading(true);
    setStatus('idle');

    try {
      await onSync();
      setStatus('success');
      setTimeout(() => {
        onClose();
        setStatus('idle');
      }, 1000);
    } catch (error) {
      console.error(error);
      setStatus('error');
    } finally {
      setIsLoading(false);
    }
  };

  const copyScript = () => {
    navigator.clipboard.writeText(GOOGLE_SCRIPT_CODE);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-[#202020] w-full max-w-2xl max-h-[90vh] rounded-xl shadow-2xl border border-white/10 flex flex-col relative">

        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/5 shrink-0">
            <h2 className="text-notion-text font-medium text-lg">Integração Google Sheets & Drive</h2>
            <button onClick={onClose} className="text-notion-muted hover:text-notion-text transition-colors">
                <X size={20} />
            </button>
        </div>

        {/* Scrollable Body */}
        <div className="p-6 space-y-6 overflow-y-auto custom-scrollbar">

            {/* Status Section */}
            <div className="bg-[#252525] p-4 rounded border border-white/5">
                <label className="block text-xs font-bold text-notion-muted uppercase mb-2">
                    Status da Conexão
                </label>
                <div className="flex flex-col gap-2">
                   <p className="text-sm text-notion-text">
                       Conectado ao Web App integrado:
                   </p>
                   <code className="text-xs text-notion-muted break-all bg-[#191919] p-2 rounded">
                       {API_URL}
                   </code>
                </div>
                {status === 'error' && <p className="text-red-400 text-xs mt-2">Erro ao conectar. Verifique sua conexão.</p>}
                {status === 'success' && <p className="text-green-400 text-xs mt-2">Sincronizado com sucesso!</p>}
            </div>

            {/* Script Section */}
            <div>
                <div className="flex items-center justify-between mb-2">
                    <label className="block text-xs font-bold text-notion-muted uppercase">
                        Script do Backend
                    </label>
                    <button 
                        onClick={copyScript}
                        className="flex items-center gap-1 text-xs text-notion-blue hover:text-notion-blueHover transition-colors"
                    >
                        {copied ? <Check size={12} /> : <Copy size={12} />}
                        {copied ? 'Copiado!' : 'Copiar Script'}
                    </button>
                </div>

                <div className="text-xs text-notion-muted mb-2 space-y-1">
                   <p>Atualize seu script no Google Apps Script para habilitar a organização automática de imagens.</p>
                </div>

                <div className="relative group">
                    <pre className="bg-[#151515] text-gray-300 p-4 rounded border border-white/5 text-[11px] font-mono overflow-x-auto whitespace-pre leading-relaxed select-all">
                        {GOOGLE_SCRIPT_CODE}
                    </pre>
                </div>
            </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-white/5 flex justify-end gap-2 shrink-0 bg-[#202020]">
            <button 
                onClick={onClose}
                className="px-3 py-1.5 text-sm text-notion-muted hover:bg-white/5 rounded transition-colors"
            >
                Fechar
            </button>
            <button 
                onClick={handleSaveAndSync}
                disabled={isLoading}
                className="px-3 py-1.5 text-sm bg-notion-blue hover:bg-notion-blueHover text-white rounded shadow-sm disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
                {isLoading ? <RefreshCw className="animate-spin" size={14} /> : <Save size={14} />}
                {isLoading ? 'Sincronizando...' : 'Forçar Sincronização'}
            </button>
        </div>

      </div>
    </div>
  );
};

const GOOGLE_SCRIPT_CODE = `// CONFIGURAÇÃO
// Deixe vazio para usar a pasta "Dashboard_Assets" na raiz
var DRIVE_FOLDER_ID = ""; 
var METADATA_SHEET_NAME = "_Metadata";

function doGet() {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheets = ss.getSheets();
    var cards = [];
    var metadata = {};

    // 1. Ler Metadados
    var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
    if (metaSheet) {
      var data = metaSheet.getDataRange().getValues();
      for (var i = 0; i < data.length; i++) {
        if (data[i][0]) metadata[data[i][0].toString().toLowerCase()] = data[i][1];
      }
    }

    // 2. Ler Cartões
    sheets.forEach(function(sheet) {
      if (sheet.getName().startsWith("_")) return;

      var title = sheet.getRange("B1").getValue();
      if (!title) title = sheet.getName();

      // Leitura robusta das células
      var image = sheet.getRange("B2").getValue();
      var icon = sheet.getRange("B3").getValue();
      var content = sheet.getRange("B4").getValue();
      var fullWidth = sheet.getRange("B5").getValue();
      var smallText = sheet.getRange("B6").getValue();
      var parentId = sheet.getRange("B7").getValue(); 
      var order = sheet.getRange("B8").getValue();
      var galleryRaw = sheet.getRange("B9").getValue();

      var gallery = [];
      try {
         if (galleryRaw) gallery = JSON.parse(galleryRaw);
      } catch(e) {}

      cards.push({
        id: sheet.getSheetId().toString(), 
        title: title,
        image: image || "https://picsum.photos/800/400",
        icon: icon || "FileText",
        content: content || "",
        fullWidth: fullWidth === true || fullWidth === "TRUE",
        smallText: smallText === true || smallText === "TRUE",
        parentId: parentId ? parentId.toString() : "",
        order: typeof order === 'number' ? order : 0,
        gallery: Array.isArray(gallery) ? gallery : []
      });
    });

    return createJSONOutput({status: "success", cards: cards, metadata: metadata});
  } catch(e) {
    return createJSONOutput({status: "error", message: e.toString()});
  }
}

function doPost(e) {
  var lock = LockService.getScriptLock();
  lock.tryLock(30000);

  try {
    var data = JSON.parse(e.postData.contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();

    // --- UPLOAD ACTION (Novo) ---
    if (data.type === 'upload') {
       var name = data.fileName || "Upload_" + new Date().getTime();
       var result = uploadToDrive(data.imageBase64, data.mimeType, name);
       if (result.error) return createJSONOutput({status: "error", message: result.error});
       return createJSONOutput({status: "success", url: result.url});
    }

    // --- DELETE ACTION ---
    if (data.type === 'delete' && data.id) {
        var sheets = ss.getSheets();
        var sheetToDelete = null;
        for (var i = 0; i < sheets.length; i++) {
            if (sheets[i].getSheetId().toString() === data.id) {
                sheetToDelete = sheets[i];
                break;
            }
        }
        if (sheetToDelete) {
            ss.deleteSheet(sheetToDelete);
            return createJSONOutput({status: "success", message: "Deleted"});
        } else {
            return createJSONOutput({status: "error", message: "Sheet not found"});
        }
    }

    // --- METADATA (Capa Global) ---
    if (data.type === 'metadata') {
       var metaSheet = ss.getSheetByName(METADATA_SHEET_NAME);
       if (!metaSheet) {
         metaSheet = ss.insertSheet(METADATA_SHEET_NAME);
         metaSheet.appendRow(["Key", "Value"]);
       }

       var saveData = function(key, val) {
         var range = metaSheet.getDataRange();
         var values = range.getValues();
         for(var i=0; i<values.length; i++) {
           if(values[i][0].toString().toLowerCase() === key.toLowerCase()) {
             metaSheet.getRange(i+1, 2).setValue(val);
             return;
           }
         }
         metaSheet.appendRow([key, val]);
       };

       if (data.homeCoverPosition) saveData("home_cover_pos", data.homeCoverPosition);

       if (data.imageBase64) {
         var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Home_Cover_" + new Date().getTime());
         if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
         saveData("home_cover_image", uploadResult.url);
         data.image = uploadResult.url;
       }

       return createJSONOutput({status: "success", data: data});
    }

    // --- CARTÕES (Abas) ---
    var sheets = ss.getSheets();
    var targetSheet = null;

    if (data.id) {
      for (var i = 0; i < sheets.length; i++) {
        if (sheets[i].getSheetId().toString() === data.id) {
          targetSheet = sheets[i];
          break;
        }
      }
    }
    if (!targetSheet && data.title) targetSheet = ss.getSheetByName(data.title);

    // Criar Nova Aba se não existir
    if (!targetSheet) {
       var safeTitle = (data.title || "New Page " + new Date().getSeconds()).substring(0,50);
       try { targetSheet = ss.insertSheet(safeTitle); } 
       catch(e) { targetSheet = ss.insertSheet(safeTitle + Math.floor(Math.random()*100)); }

       targetSheet.getRange("A1:A9").setValues([["Title"], ["Image"], ["Icon"], ["ContentHTML"], ["FullWidth"], ["SmallText"], ["ParentID"], ["Order"], ["Gallery"]]);
    }

    // Salvar Dados
    if (data.title) targetSheet.getRange("B1").setValue(data.title);
    if (data.icon) targetSheet.getRange("B3").setValue(data.icon);
    if (data.content !== undefined) targetSheet.getRange("B4").setValue(data.content);
    if (data.fullWidth !== undefined) targetSheet.getRange("B5").setValue(data.fullWidth);
    if (data.smallText !== undefined) targetSheet.getRange("B6").setValue(data.smallText);
    if (data.parentId !== undefined) targetSheet.getRange("B7").setValue(data.parentId);
    if (data.order !== undefined) targetSheet.getRange("B8").setValue(data.order);
    if (data.gallery !== undefined) targetSheet.getRange("B9").setValue(JSON.stringify(data.gallery));

    // Upload da Imagem do Cartão
    if (data.imageBase64) {
      var uploadResult = uploadToDrive(data.imageBase64, data.mimeType, "Card_" + targetSheet.getName() + "_" + new Date().getTime());
      if (uploadResult.error) return createJSONOutput({status: "error", message: uploadResult.error});
      targetSheet.getRange("B2").setValue(uploadResult.url);
      data.image = uploadResult.url;
    }

    // Atualizar nome da aba
    if (data.title && targetSheet.getName() !== data.title) {
        try { targetSheet.setName(data.title.substring(0, 50)); } catch(e) {}
    }

    data.id = targetSheet.getSheetId().toString();
    return createJSONOutput({status: "success", data: data});

  } catch (err) {
    return createJSONOutput({status: "error", message: err.toString()});
  } finally {
    lock.releaseLock();
  }
}

function uploadToDrive(base64Data, mimeType, fileName) {
  try {
    var folder;

    // Se ID fornecido, tenta usar. Senão, procura ou cria pasta Dashboard_Assets
    if (DRIVE_FOLDER_ID && DRIVE_FOLDER_ID !== "") {
       try { folder = DriveApp.getFolderById(DRIVE_FOLDER_ID); } catch(e) { folder = null; }
    }

    if (!folder) {
       var folders = DriveApp.getFoldersByName("Dashboard_Assets");
       if (folders.hasNext()) {
         folder = folders.next();
       } else {
         folder = DriveApp.createFolder("Dashboard_Assets");
       }
    }

    var cleanBase64 = base64Data;
    if (base64Data.indexOf("base64,") !== -1) {
      cleanBase64 = base64Data.split("base64,")[1];
    }

    var blob = Utilities.newBlob(Utilities.base64Decode(cleanBase64), mimeType || "image/jpeg", fileName);
    var file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);

    return { url: "https://lh3.googleusercontent.com/d/" + file.getId() };

  } catch(e) {
    return { error: e.toString() };
  }
}

function createJSONOutput(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}`

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { CoverImage } from './components/CoverImage';
import { PageContent } from './components/PageContent';
import { ActivePage } from './components/ActivePage';
import { SettingsModal } from './components/SettingsModal';
import { DashboardCard } from './types';
import { DASHBOARD_CARDS, HERO_IMAGE, API_URL } from './constants';
import * as LucideIcons from 'lucide-react';

const App: React.FC = () => {
  const [activeCardId, setActiveCardId] = useState<string | null>(null);
  const [cards, setCards] = useState<DashboardCard[]>(DASHBOARD_CARDS);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  // Derived state for active card to ensure single source of truth
  const activeCard = activeCardId ? cards.find(c => c.id === activeCardId) || null : null;

  // Home Cover State (Global)
  const [homeCover, setHomeCover] = useState(HERO_IMAGE);
  const [homeCoverPos, setHomeCoverPos] = useState(50);

  // Load Cache on Init
  useEffect(() => {
    const cachedData = localStorage.getItem('vilage_dashboard_data');
    if (cachedData) {
        try {
            const parsed = JSON.parse(cachedData);
            if (parsed.cards && Array.isArray(parsed.cards)) {
                const rehydrated = parsed.cards.map((c: any) => ({
                    ...c,
                    icon: (LucideIcons as any)[c.iconName] || LucideIcons.HelpCircle,
                    gallery: Array.isArray(c.gallery) ? c.gallery : []
                }));
                // Sort by order
                rehydrated.sort((a: DashboardCard, b: DashboardCard) => (a.order || 0) - (b.order || 0));
                setCards(rehydrated);
            }
            if (parsed.metadata) {
                const img = parsed.metadata.home_cover_image || parsed.metadata.Home_Cover_Image;
                const pos = parsed.metadata.home_cover_pos || parsed.metadata.Home_Cover_Pos;
                if (img) setHomeCover(img);
                if (pos) setHomeCoverPos(Number(pos));
            }
        } catch (e) {
            console.error("Cache load error", e);
        }
    }

    // Auto-Sync on Mount
    handleSync();
  }, []);

  // Navigation Logic
  const handleBackToHome = () => {
    setActiveCardId(null);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleNavigateToCard = (card: DashboardCard) => {
    setActiveCardId(card.id);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  const handleBreadcrumbClick = (targetCard: DashboardCard) => {
    setActiveCardId(targetCard.id);
    window.scrollTo({ top: 0, behavior: 'auto' });
  };

  // Helper to build Breadcrumbs path from activeCard up to root
  const getBreadcrumbs = () => {
    if (!activeCard) return undefined;

    const path: { label: string; onClick?: () => void }[] = [];

    // Add Home
    path.push({ label: 'Hotel Vilage Inn Poços de Caldas', onClick: handleBackToHome });

    // Build hierarchy recursively
    const hierarchy: DashboardCard[] = [];
    let current: DashboardCard | undefined = activeCard;

    while (current) {
        hierarchy.unshift(current); // Add to front
        if (current.parentId) {
            // Loose comparison for robustness (string vs number)
            current = cards.find(c => c.id == current?.parentId);
        } else {
            current = undefined;
        }
    }

    hierarchy.forEach((c, index) => {
        const isLast = index === hierarchy.length - 1;
        path.push({
            label: c.title,
            onClick: isLast ? undefined : () => handleBreadcrumbClick(c)
        });
    });

    return path;
  };

  const handleCreateNewCard = (parentId?: string) => {
    const newId = Date.now().toString(); 
    const safeParentId = typeof parentId === 'string' ? parentId : undefined;

    // Determine new order (at end of list)
    const siblings = cards.filter(c => c.parentId == safeParentId && !c._deleted);
    const maxOrder = siblings.reduce((max, c) => Math.max(max, c.order || 0), 0);

    const newCard: DashboardCard = {
        id: newId,
        title: 'Nova Página',
        image: 'https://picsum.photos/seed/' + newId + '/600/300',
        icon: LucideIcons.FileText,
        iconName: 'FileText',
        content: '<p>Comece a escrever aqui...</p>',
        fullWidth: false,
        smallText: false,
        parentId: safeParentId,
        order: maxOrder + 1,
        gallery: [],
        _isUnsynced: true // Mark as needing sync
    };

    // Optimistically add to state
    const updatedCards = [...cards, newCard];
    setCards(updatedCards);
    setActiveCardId(newId); // Navigate to new card
    window.scrollTo({ top: 0, behavior: 'auto' });
    saveToLocalCache(updatedCards);

    // Sync
    handleUpdateCard(newCard, true);
  };

  // --- Deletion Logic ---
  const performDeleteAPI = async (cardId: string) => {
    const payload = { type: 'delete', id: cardId };
    await fetch(API_URL, { 
        method: 'POST', 
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(payload) 
    });
  };

  const handleDeleteCard = async (cardId: string) => {
    if (!window.confirm("Tem certeza que deseja excluir esta página e todo o conteúdo dela?")) return;

    // Optimistic UI Update: MARK as deleted instead of removing
    setCards(prev => {
        const newCards = prev.map(c => {
            if (c.id === cardId || c.parentId === cardId) {
                return { ...c, _deleted: true, _isUnsynced: true };
            }
            return c;
        });
        saveToLocalCache(newCards);
        return newCards;
    });

    if (activeCard && activeCard.id === cardId) {
        handleBackToHome();
    }

    try {
        await performDeleteAPI(cardId);
    } catch (e) {
        console.error("Delete failed on server", e);
    }
  };

  // --- Reorder Logic ---
  const handleReorderCard = async (cardId: string, direction: 'left' | 'right') => {
    const card = cards.find(c => c.id === cardId);
    if (!card) return;

    const siblings = cards
        .filter(c => c.parentId === card.parentId && !c._deleted)
        .sort((a, b) => (a.order || 0) - (b.order || 0));

    const currentIndex = siblings.findIndex(c => c.id === cardId);
    if (currentIndex === -1) return;

    const targetIndex = direction === 'left' ? currentIndex - 1 : currentIndex + 1;

    if (targetIndex >= 0 && targetIndex < siblings.length) {
        const swapCard = siblings[targetIndex];

        // Swap orders
        const cardOrder = card.order || 0;
        const swapOrder = swapCard.order || 0;

        // Handling equal orders case
        if (cardOrder === swapOrder) {
             siblings.forEach((c, idx) => c.order = idx);
             card.order = currentIndex;
             swapCard.order = targetIndex;
             const temp = card.order;
             card.order = swapCard.order;
             swapCard.order = temp;
        } else {
             const temp = card.order;
             card.order = swapCard.order;
             swapCard.order = temp;
        }

        const updatedCards = cards.map(c => {
            if (c.id === card.id) return { ...c, order: card.order, _isUnsynced: true };
            if (c.id === swapCard.id) return { ...c, order: swapCard.order, _isUnsynced: true };
            return c;
        });

        updatedCards.sort((a, b) => (a.order || 0) - (b.order || 0));

        setCards(updatedCards);
        saveToLocalCache(updatedCards);

        await handleUpdateCard(card);
        await handleUpdateCard(swapCard);
    }
  };

  // --- Move/Nest Logic (Drag and Drop) ---
  const handleMoveCard = async (draggedId: string, targetParentId?: string) => {
    if (draggedId === targetParentId) return;

    const cardToMove = cards.find(c => c.id === draggedId);
    if (!cardToMove) return;

    const newSiblings = cards.filter(c => c.parentId == targetParentId && !c._deleted);
    const maxOrder = newSiblings.reduce((max, c) => Math.max(max, c.order || 0), 0);

    const updatedCard = { 
        ...cardToMove, 
        parentId: targetParentId, 
        order: maxOrder + 1,
        _isUnsynced: true 
    };

    const updatedList = cards.map(c => c.id === draggedId ? updatedCard : c);
    updatedList.sort((a, b) => (a.order || 0) - (b.order || 0));

    setCards(updatedList);
    saveToLocalCache(updatedList);

    handleUpdateCard(updatedCard);
  };

  // --- Upload Gallery Image Logic ---
  const handleUploadGalleryImage = async (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = async () => {
            try {
                const base64String = reader.result as string;
                const payload = {
                    type: 'upload',
                    imageBase64: base64String,
                    mimeType: file.type,
                    fileName: "Gallery_" + file.name
                };

                const response = await fetch(API_URL, {
                    method: 'POST',
                    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                    body: JSON.stringify(payload)
                });

                const result = await response.json();
                if (result.status === 'success' && result.url) {
                    resolve(result.url);
                } else {
                    reject(new Error(result.message || 'Upload failed'));
                }
            } catch (e) {
                reject(e);
            }
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  };

  const handleSync = async () => {
    try {
        const response = await fetch(API_URL);
        if (!response.ok) throw new Error('Response not ok');

        const result = await response.json();
        console.log("Sync Result:", result); 

        const serverCards: DashboardCard[] = (result.cards || []).map((item: any) => {
            const IconComponent = (LucideIcons as any)[item.icon] || LucideIcons.Info;
            return {
                id: item.id ? item.id.toString() : Math.random().toString(),
                title: item.title,
                image: item.image,
                icon: IconComponent,
                iconName: item.icon, 
                content: item.content || '',
                fullWidth: item.fullWidth,
                smallText: item.smallText,
                parentId: item.parentId ? item.parentId.toString() : undefined,
                order: Number(item.order) || 0,
                gallery: Array.isArray(item.gallery) ? item.gallery : [],
                _isUnsynced: false // Server items are synced by definition
            };
        });

        // MERGE LOGIC
        const itemsToRetry: DashboardCard[] = [];

        setCards(currentCards => {
            const freshMergedCards = [...serverCards];

            currentCards.forEach(localCard => {
                if (localCard._isUnsynced) {
                    const serverIndex = freshMergedCards.findIndex(c => c.id === localCard.id);

                    if (serverIndex !== -1) {
                        freshMergedCards[serverIndex] = localCard;
                        itemsToRetry.push(localCard);
                    } else {
                        if (!localCard._deleted) {
                            freshMergedCards.push(localCard);
                            itemsToRetry.push(localCard);
                        }
                    }
                }
            });

            freshMergedCards.sort((a, b) => (a.order || 0) - (b.order || 0));
            saveToLocalCache(freshMergedCards, result.metadata);
            return freshMergedCards;
        });

        if (result.metadata) {
            const img = result.metadata['home_cover_image'] || result.metadata['Home_Cover_Image'];
            const pos = result.metadata['home_cover_pos'] || result.metadata['Home_Cover_Pos'];
            if (img) setHomeCover(img);
            if (pos) setHomeCoverPos(Number(pos));
        }

        if (itemsToRetry.length > 0) {
            for (const item of itemsToRetry) {
                if (item._deleted) {
                    await performDeleteAPI(item.id);
                } else {
                    await handleUpdateCard(item); 
                }
                await new Promise(r => setTimeout(r, 500));
            }
        }

    } catch (error) {
        console.error("Sync failed:", error);
    }
  };

  const handleUpdateGlobalSettings = async (data: { imageBase64?: string, mimeType?: string, position?: number }) => {
    if (data.imageBase64) setHomeCover(data.imageBase64);
    if (data.position !== undefined) setHomeCoverPos(data.position);

    try {
        const payload = {
            type: 'metadata',
            imageBase64: data.imageBase64,
            mimeType: data.mimeType,
            homeCoverPosition: data.position
        };

        const response = await fetch(API_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();
        if (result.status === 'success' && result.data.image && result.data.image.startsWith('http')) {
            setHomeCover(result.data.image);
        }
    } catch (e) {
        console.error("Failed to update global settings", e);
    }
  };

  const handleUpdateCard = async (updatedFields: Partial<DashboardCard> & { imageBase64?: string, mimeType?: string, iconName?: string } | DashboardCard, isNew = false) => {

    const targetCardId = (updatedFields as any).id || activeCardId;

    let targetCard: DashboardCard | undefined;
    if (isNew) {
        targetCard = updatedFields as DashboardCard;
    } else {
        targetCard = cards.find(c => c.id === targetCardId);
    }

    if (!targetCard) return;
    if (targetCard._deleted && !isNew) return;

    const updatedCardFull: DashboardCard = { 
        ...targetCard, 
        ...updatedFields,
        icon: (updatedFields as any).iconName ? (LucideIcons as any)[(updatedFields as any).iconName] : (updatedFields.icon || targetCard.icon),
        _isUnsynced: true 
    };

    setCards(prev => {
        let newCards;
        const exists = prev.find(c => c.id === targetCard!.id);

        if (exists) {
            newCards = prev.map(c => c.id === targetCard!.id ? updatedCardFull : c);
        } else {
            newCards = [...prev, updatedCardFull];
        }

        newCards.sort((a, b) => (a.order || 0) - (b.order || 0));
        saveToLocalCache(newCards);
        return newCards;
    });

    try {
        const payload = {
            id: targetCard.id,
            title: updatedFields.title || targetCard.title,
            icon: (updatedFields as any).iconName || (targetCard as any).iconName || 'HelpCircle',
            content: updatedFields.content !== undefined ? updatedFields.content : targetCard.content,
            imageBase64: (updatedFields as any).imageBase64, 
            mimeType: (updatedFields as any).mimeType,
            fullWidth: updatedCardFull.fullWidth,
            smallText: updatedCardFull.smallText,
            parentId: updatedCardFull.parentId === undefined ? "" : updatedCardFull.parentId, 
            order: updatedCardFull.order,
            gallery: updatedCardFull.gallery // Send gallery array
        };

        const response = await fetch(API_URL, { 
            method: 'POST', 
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(payload)
        });

        const result = await response.json();

        if (result.status === 'success' && result.data) {
            // FIX: Handle ID change (Temp -> Real)
            const serverId = result.data.id ? result.data.id.toString() : null;
            const oldId = targetCard.id;
            const idChanged = serverId && serverId !== oldId;

            setCards(prev => {
                const finalCards = prev.map(c => {
                    // Update the card itself
                    if (c.id === oldId) {
                        return {
                            ...c,
                            id: serverId || c.id, // Update ID if server provides one
                            _isUnsynced: false, 
                            image: (result.data.image && result.data.image.startsWith('http')) ? result.data.image : c.image
                        };
                    }
                    // Update children referencing this card (if it was a temp ID)
                    if (idChanged && c.parentId === oldId) {
                         return {
                             ...c,
                             parentId: serverId,
                             _isUnsynced: true // Mark as unsynced so we update the parentId on server later
                         };
                    }
                    return c;
                });

                // Check active ID change outside map
                if (activeCardId === oldId && idChanged) {
                    setActiveCardId(serverId);
                }

                saveToLocalCache(finalCards);
                return finalCards;
            });
        }
    } catch (e) {
        console.error("Failed to update remote sheet", e);
    }
  };

  const saveToLocalCache = (cardsData: DashboardCard[], meta?: any) => {
    try {
        const cacheableCards = cardsData.map((c: any) => ({
            ...c,
            icon: undefined,
            iconName: c.iconName || (typeof c.icon === 'string' ? c.icon : 'Info'),
            imageBase64: undefined 
        }));

        const cachePayload = {
            cards: cacheableCards,
            metadata: meta || { home_cover_image: homeCover, home_cover_pos: homeCoverPos }
        };

        localStorage.setItem('vilage_dashboard_data', JSON.stringify(cachePayload));
    } catch (e) {
        console.warn("Storage full");
    }
  };

  const breadcrumbs = getBreadcrumbs();

  return (
    <div className="min-h-screen bg-notion-bg text-notion-text font-sans selection:bg-[#2383e2]/30 selection:text-white">
      <Navbar 
        breadcrumbs={breadcrumbs} 
        onBack={activeCard ? handleBackToHome : undefined} 
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        onSync={handleSync}
      />

      <div className="mt-11"> 
        {activeCard ? (
            <ActivePage 
                key={activeCard.id} 
                card={activeCard} 
                allCards={cards} 
                onUpdateCard={handleUpdateCard} 
                onNavigateToCard={handleNavigateToCard}
                onCreateSubPage={handleCreateNewCard}
                onDeleteCard={handleDeleteCard} 
                onMoveCard={handleMoveCard}
                onReorderCard={handleReorderCard}
                onUploadGalleryImage={handleUploadGalleryImage}
            />
        ) : (
            <div className="flex flex-col w-full animate-in fade-in duration-300">
                <CoverImage 
                    imageSrc={homeCover}
                    positionY={homeCoverPos}
                    onUpdate={handleUpdateGlobalSettings}
                />
                <PageContent 
                    cards={cards.filter(c => !c.parentId && !c._deleted)} 
                    onCardClick={handleNavigateToCard} 
                    onNewCard={() => handleCreateNewCard()}
                    onMoveCard={handleMoveCard}
                    onDeleteCard={handleDeleteCard} 
                    onReorderCard={handleReorderCard} 
                />
            </div>
        )}
      </div>

      <button className="fixed bottom-4 right-4 w-8 h-8 flex items-center justify-center rounded-full bg-notion-card hover:bg-notion-hover border border-white/10 text-notion-muted hover:text-notion-text transition-all shadow-lg z-50">
        <span className="font-bold text-lg">?</span>
      </button>
    </div>
  );
};

export default App;

